INSERT INTO "milestones" VALUES('milestone:reference:SRC/MPCD','reference:SRC/MPCD','SRC/MPCD',NULL,'Socle fonctionnel (avant les jalons 0493x)','Collision particulaire SRC/MPCD','Streaming des particules, collision stochastique par cellule, rotation SRD, grid shift et thermostat. C''est le fluide mésoscopique de base.','CODE','CORE','Socle actif','B',NULL,NULL,NULL,NULL,'referentiel_jalons_SRC_GPU_SURF_20260905.tex',40);
INSERT INTO "milestones" VALUES('milestone:reference:Q6','reference:Q6','Q6',NULL,'Socle fonctionnel (avant les jalons 0493x)','Projection quasi-incompressible','Projection du champ de vitesse/moment pour réduire la divergence. Les variantes récentes opèrent sur GPU résident.','CODE','CORE','Socle actif selon RUN_MODE','B',NULL,NULL,NULL,NULL,'referentiel_jalons_SRC_GPU_SURF_20260905.tex',41);
INSERT INTO "milestones" VALUES('milestone:reference:Q9','reference:Q9','Q9',NULL,'Socle fonctionnel (avant les jalons 0493x)','Relaxation basse fréquence du flux de masse','Ancienne projection complémentaire du flux de masse à grande longueur d''onde.','CODE','CORE','Historique / séparée du chemin Q6-g-f actuel','B',NULL,NULL,NULL,NULL,'referentiel_jalons_SRC_GPU_SURF_20260905.tex',42);
INSERT INTO "milestones" VALUES('milestone:reference:Resampling','reference:Resampling','Resampling',NULL,'Socle fonctionnel (avant les jalons 0493x)','Contrôle du support particulaire','Rééchantillonnage local conservatif pour maintenir population et masse cellulaire; distinct de Q6 et opt-in.','QUALIFICATION','CORE','Module séparé, OFF dans les qualifications surface libre récentes','B',NULL,NULL,NULL,NULL,'referentiel_jalons_SRC_GPU_SURF_20260905.tex',43);
INSERT INTO "milestones" VALUES('milestone:reference:Q6 multi-espèces','reference:Q6 multi-espèces','Q6 multi-espèces',NULL,'Socle fonctionnel (avant les jalons 0493x)','Projection sélective par espèce','Registre d''espèces; mode independent_masked pour projeter le liquide sans projeter directement le gaz.','INFRA','CORE','Socle multi-espèces','B',NULL,NULL,NULL,NULL,'referentiel_jalons_SRC_GPU_SURF_20260905.tex',44);
INSERT INTO "milestones" VALUES('milestone:reference:Q6-g','reference:Q6-g','Q6-g',NULL,'Socle fonctionnel (avant les jalons 0493x)','Q6 force-aware','Inclut la force dans la vitesse tentative avant le streaming afin que la projection corrige la vitesse réellement utilisée pour transporter les particules.','CODE','CORE','Introduit par x3, base de Q6-g-f','B',NULL,NULL,NULL,NULL,'referentiel_jalons_SRC_GPU_SURF_20260905.tex',45);
INSERT INTO "milestones" VALUES('milestone:reference:Q6-g-f','reference:Q6-g-f','Q6-g-f',NULL,'Socle fonctionnel (avant les jalons 0493x)','Q6 force-aware + interface + face-particule + densité','Chaîne: vitesse tentative forcée, interface physique alpha=0.5, condition de pression, reconstruction face-particule B1/RT0 et relaxation lente de densité dans le même solveur CG.','CODE','CORE','Chaîne de projection de référence','B',NULL,NULL,NULL,NULL,'referentiel_jalons_SRC_GPU_SURF_20260905.tex',46);
INSERT INTO "milestones" VALUES('milestone:0493x1','0493x1','x1','0493x1','Socle fonctionnel (avant les jalons 0493x)','Jalon ancien non individualisé dans le rapport consolidé','Le rapport consolidé actuel ne donne pas une définition séparée et fiable de x1.','CODE','CORE','À retrouver dans l''historique Git si nécessaire','C',NULL,NULL,NULL,NULL,'referentiel_jalons_SRC_GPU_SURF_20260905.tex',47);
INSERT INTO "milestones" VALUES('milestone:0493x2','0493x2','x2','0493x2','Socle fonctionnel (avant les jalons 0493x)','Test Q6 liquide seul / gravité','Campagne liquide seul qui a montré que le kick gravitaire appliqué avant une projection trop tardive pouvait court-circuiter l''objectif de Q6.','CODE','CORE','Historique; mène à x3','B',NULL,NULL,NULL,NULL,'referentiel_jalons_SRC_GPU_SURF_20260905.tex',48);
INSERT INTO "milestones" VALUES('milestone:0493x3','0493x3','x3','0493x3','x3-x7 : Q6-g / Q6-g-f, dam-break et fermeture incompressible','Q6-g force-aware - preuve de concept','Projette une vitesse tentative incluant la force avant streaming; première version avec double projection pour démontrer la cause de la sédimentation parasite.','CODE','Q6_GF','Supplanté par x4a/x4b','B',NULL,NULL,NULL,NULL,'referentiel_jalons_SRC_GPU_SURF_20260905.tex',50);
INSERT INTO "milestones" VALUES('milestone:0493x4a','0493x4a','x4a','0493x4a','x3-x7 : Q6-g / Q6-g-f, dam-break et fermeture incompressible','prestream_single','Une seule projection avant transport; évite le double solve tout en supprimant la dérive gravitaire.','CODE','Q6_GF','Supplanté par x4b','B',NULL,NULL,NULL,NULL,'referentiel_jalons_SRC_GPU_SURF_20260905.tex',51);
INSERT INTO "milestones" VALUES('milestone:0493x4b','0493x4b','x4b','0493x4b','x3-x7 : Q6-g / Q6-g-f, dam-break et fermeture incompressible','prestream_single_fused','Fusionne dépôt de v+a dt, projection Q6, puis application force+Q6 sans passage particulaire dédié au kick.','CODE','Q6_GF','Séquençage de référence Q6-g-f','B',NULL,NULL,NULL,NULL,'referentiel_jalons_SRC_GPU_SURF_20260905.tex',52);
INSERT INTO "milestones" VALUES('milestone:0493x5a','0493x5a','x5a','0493x5a','x3-x7 : Q6-g / Q6-g-f, dam-break et fermeture incompressible','free_surface_masked initial','Masque Q6 du liquide partiellement rempli; bord du support traité comme pression de jauge nulle à demi-maille.','CODE','Q6_GF','Étape historique','B',NULL,NULL,NULL,NULL,'referentiel_jalons_SRC_GPU_SURF_20260905.tex',53);
INSERT INTO "milestones" VALUES('milestone:0493x5a2','0493x5a2','x5a2','0493x5a2','x3-x7 : Q6-g / Q6-g-f, dam-break et fermeture incompressible','Dam-break vide','Validation du masque surface libre sur dam-break sans gaz; robuste avant impact mais révèle que bord du support != interface physique.','QUALIFICATION','Q6_GF','Historique / discriminant','B',NULL,NULL,NULL,NULL,'referentiel_jalons_SRC_GPU_SURF_20260905.tex',54);
INSERT INTO "milestones" VALUES('milestone:0493x5b','0493x5b','x5b','0493x5b','x3-x7 : Q6-g / Q6-g-f, dam-break et fermeture incompressible','Gaz explicite compressible','Ajoute une espèce gaz q6Strength=0 qui collisionne avec le liquide sans être projetée incompressible.','CODE','Q6_GF','Base du couplage gaz','B',NULL,NULL,NULL,NULL,'referentiel_jalons_SRC_GPU_SURF_20260905.tex',55);
INSERT INTO "milestones" VALUES('milestone:0493x6a','0493x6a','x6a','0493x6a','x3-x7 : Q6-g / Q6-g-f, dam-break et fermeture incompressible','Diagnostic EOS gaz','Reconstruit une pression gazeuse EOS sans modifier la physique afin d''auditer le futur couplage de pression.','DIAGNOSTIC','Q6_GF','Diagnostic historique','B',NULL,NULL,NULL,NULL,'referentiel_jalons_SRC_GPU_SURF_20260905.tex',56);
INSERT INTO "milestones" VALUES('milestone:0493x6b','0493x6b','x6b','0493x6b','x3-x7 : Q6-g / Q6-g-f, dam-break et fermeture incompressible','Audit support vs interface','Compare seuil de support Q6 et isovaleur physique alpha=0.5.','DIAGNOSTIC','Q6_GF','Diagnostic historique','B',NULL,NULL,NULL,NULL,'referentiel_jalons_SRC_GPU_SURF_20260905.tex',57);
INSERT INTO "milestones" VALUES('milestone:0493x6c','0493x6c','x6c','0493x6c','x3-x7 : Q6-g / Q6-g-f, dam-break et fermeture incompressible','Alpha physique résident','Construit sur GPU un champ alpha du liquide, filtré par stencil cinq points, distinct du simple carrier Q6.','CODE','Q6_GF','Actif, base géométrique Q6/capillarité','B',NULL,NULL,NULL,NULL,'referentiel_jalons_SRC_GPU_SURF_20260905.tex',58);
INSERT INTO "milestones" VALUES('milestone:0493x6d','0493x6d','x6d','0493x6d','x3-x7 : Q6-g / Q6-g-f, dam-break et fermeture incompressible','Distance sous-maille 1/theta','Utilise la position locale de l''isovaleur pour corriger la distance de frontière au lieu du facteur demi-maille.','CODE','Q6_GF','Supplanté par x6f','B',NULL,NULL,NULL,NULL,'referentiel_jalons_SRC_GPU_SURF_20260905.tex',59);
INSERT INTO "milestones" VALUES('milestone:0493x6e','0493x6e','x6e','0493x6e','x3-x7 : Q6-g / Q6-g-f, dam-break et fermeture incompressible','Audit topologique des crossings','Montre que l''interface alpha=0.5 traverse souvent des paires de cellules qui sont encore toutes deux dans le carrier numérique.','DIAGNOSTIC','Q6_GF','Diagnostic architectural','B',NULL,NULL,NULL,NULL,'referentiel_jalons_SRC_GPU_SURF_20260905.tex',60);
INSERT INTO "milestones" VALUES('milestone:0493x6f','0493x6f','x6f','0493x6f','x3-x7 : Q6-g / Q6-g-f, dam-break et fermeture incompressible','Stencil physique d''interface','Sépare pressureMask et carrierMask; prépare les coefficients de face sur les crossings alpha=0.5 et la distance sous-maille theta.','CODE','Q6_GF','Actif','B',NULL,NULL,NULL,NULL,'referentiel_jalons_SRC_GPU_SURF_20260905.tex',61);
INSERT INTO "milestones" VALUES('milestone:0493x6g','0493x6g','x6g','0493x6g','x3-x7 : Q6-g / Q6-g-f, dam-break et fermeture incompressible','Pression gazeuse interfaciale','Fournit p_g sur les faces d''interface et impose p_L|Gamma=p_g dans le Dirichlet Q6; plus tard composé avec sigma*kappa.','CODE','Q6_GF','Actif quand gaz explicite','B',NULL,NULL,NULL,NULL,'referentiel_jalons_SRC_GPU_SURF_20260905.tex',62);
INSERT INTO "milestones" VALUES('milestone:0493x6h-a','0493x6h-a','x6h-A','0493x6h-a','x3-x7 : Q6-g / Q6-g-f, dam-break et fermeture incompressible','Reconstruction faces basses','Reconstruit les corrections ouest/sud sur frontières physiques basses absentes du stockage east/north.','CODE','Q6_GF','Actif dans Q6-g-f','B',NULL,NULL,NULL,NULL,'referentiel_jalons_SRC_GPU_SURF_20260905.tex',63);
INSERT INTO "milestones" VALUES('milestone:0493x6h-b0','0493x6h-b0','x6h-B0','0493x6h-b0','x3-x7 : Q6-g / Q6-g-f, dam-break et fermeture incompressible','Diagnostic post-application','Sépare bulk/interface/paroi/zones mixtes pour localiser la divergence après application aux particules.','DIAGNOSTIC','Q6_GF','Diagnostic OFF production','B',NULL,NULL,NULL,NULL,'referentiel_jalons_SRC_GPU_SURF_20260905.tex',64);
INSERT INTO "milestones" VALUES('milestone:0493x6h-b1','0493x6h-b1','x6h-B1','0493x6h-b1','x3-x7 : Q6-g / Q6-g-f, dam-break et fermeture incompressible','Reconstruction face-particule RT0','Remplace une correction constante par cellule par une reconstruction affine entre corrections de faces, cohérente avec la divergence FV projetée.','CODE','Q6_GF','Actif dans Q6-g-f','B',NULL,NULL,NULL,NULL,'referentiel_jalons_SRC_GPU_SURF_20260905.tex',65);
INSERT INTO "milestones" VALUES('milestone:reference:x7a/x7b','reference:x7a/x7b','x7a/x7b',NULL,'x3-x7 : Q6-g / Q6-g-f, dam-break et fermeture incompressible','Kick viriel de densité','Tentatives de restauration de densité par kick post-projection de type ressort/viriel.','ABLATION','Q6_GF','Rejeté dans Q6-g-f; mutuellement exclusif avec x7d','B',NULL,NULL,NULL,NULL,'referentiel_jalons_SRC_GPU_SURF_20260905.tex',66);
INSERT INTO "milestones" VALUES('milestone:0493x7d','0493x7d','x7d','0493x7d','x3-x7 : Q6-g / Q6-g-f, dam-break et fermeture incompressible','Relaxation de densité dans le RHS','Ajoute (f-1)/tau_rho dans le second membre Q6 pour restaurer lentement la densité sans resampling ni kick post-projection.','CODE','Q6_GF','Actif; tau_rho=0.25 dans profil qualifié','B',NULL,NULL,NULL,NULL,'referentiel_jalons_SRC_GPU_SURF_20260905.tex',67);
INSERT INTO "milestones" VALUES('milestone:0493x7e','0493x7e','x7e','0493x7e','x3-x7 : Q6-g / Q6-g-f, dam-break et fermeture incompressible','Qualification x6g+x7d','Valide la coexistence pression gaz + relaxation de densité dans le même RHS, y compris runs longs/coarse-fine.','QUALIFICATION','Q6_GF','Qualification historique','B',NULL,NULL,NULL,NULL,'referentiel_jalons_SRC_GPU_SURF_20260905.tex',68);
INSERT INTO "milestones" VALUES('milestone:0493x7f','0493x7f','x7f','0493x7f','x3-x7 : Q6-g / Q6-g-f, dam-break et fermeture incompressible','Extension multi-topologies','Étend Q6-g-f aux topologies statiques supportées: périodique, canal, boîte fermée, inlet/outlet, segments.','CODE','Q6_GF','Actif','B',NULL,NULL,NULL,NULL,'referentiel_jalons_SRC_GPU_SURF_20260905.tex',69);
INSERT INTO "milestones" VALUES('milestone:0493x7f-fix2','0493x7f-fix2','x7f-fix2','0493x7f-fix2','x3-x7 : Q6-g / Q6-g-f, dam-break et fermeture incompressible','Garde wall-simple','Autorise une face specular simple sans imposer artificiellement wallVP.','FIX','Q6_GF','Correctif actif','B',NULL,NULL,NULL,NULL,'referentiel_jalons_SRC_GPU_SURF_20260905.tex',70);
INSERT INTO "milestones" VALUES('milestone:0493x7g','0493x7g','x7g','0493x7g','x3-x7 : Q6-g / Q6-g-f, dam-break et fermeture incompressible','Darcy avant projection','Place le kick Darcy-Brinkman dans la vitesse tentative avant Q6-g-f, sans le rejouer après collision.','CODE','Q6_GF','Actif selon mode Darcy','B',NULL,NULL,NULL,NULL,'referentiel_jalons_SRC_GPU_SURF_20260905.tex',71);
INSERT INTO "milestones" VALUES('milestone:0493x7h','0493x7h','x7h','0493x7h','x3-x7 : Q6-g / Q6-g-f, dam-break et fermeture incompressible','Factorisation run_ok','Rassemble dans les runners le profil src-q6-g-f: x4b, B1, x6f, registre espèces et relaxation densité.','INFRA','Q6_GF','Infrastructure runner','B',NULL,NULL,NULL,NULL,'referentiel_jalons_SRC_GPU_SURF_20260905.tex',72);
INSERT INTO "milestones" VALUES('milestone:0493x7i','0493x7i','x7i','0493x7i','x3-x7 : Q6-g / Q6-g-f, dam-break et fermeture incompressible','Qualification multi-conditions-limites','Campagne commune Taylor-Green, Poiseuille, bend-pipe Darcy et same-face IO pour comparer SRC/Q6/Q6-g-f.','BENCHMARK','Q6_GF','Benchmark de référence','B',NULL,NULL,NULL,NULL,'referentiel_jalons_SRC_GPU_SURF_20260905.tex',73);
INSERT INTO "milestones" VALUES('milestone:0493x7j','0493x7j','x7j','0493x7j','x3-x7 : Q6-g / Q6-g-f, dam-break et fermeture incompressible','CG coopératif CUDA résident','Remplace les réductions/synchronisations host à chaque itération par un unique CG coopératif entièrement GPU.','PERF','Q6_GF','Actif; optimisation majeure coût','B',NULL,NULL,NULL,NULL,'referentiel_jalons_SRC_GPU_SURF_20260905.tex',74);
INSERT INTO "milestones" VALUES('milestone:reference:x7k/x7l','reference:x7k/x7l','x7k/x7l',NULL,'x3-x7 : Q6-g / Q6-g-f, dam-break et fermeture incompressible','Réduction de télémétrie','Calcule audits Q6-g-f et réductions host thermostat uniquement au premier pas / cadence summary, sans changer la physique.','DIAGNOSTIC','Q6_GF','Actif','B',NULL,NULL,NULL,NULL,'referentiel_jalons_SRC_GPU_SURF_20260905.tex',75);
INSERT INTO "milestones" VALUES('milestone:0493x7m','0493x7m','x7m','0493x7m','x3-x7 : Q6-g / Q6-g-f, dam-break et fermeture incompressible','Correction topologie monophase','Empêche une fluctuation alpha<0.5 de créer une fausse interface interne dans un fluide monophase complet.','CODE','Q6_GF','Actif automatiquement','B',NULL,NULL,NULL,NULL,'referentiel_jalons_SRC_GPU_SURF_20260905.tex',76);
INSERT INTO "milestones" VALUES('milestone:0493x7o','0493x7o','x7o','0493x7o','x3-x7 : Q6-g / Q6-g-f, dam-break et fermeture incompressible','Symétrisation Q6 indépendant','Supprime le biais est/nord dans la reconstruction des faces pour le domaine complet independent_masked.','CODE','Q6_GF','Actif','B',NULL,NULL,NULL,NULL,'referentiel_jalons_SRC_GPU_SURF_20260905.tex',77);
INSERT INTO "milestones" VALUES('milestone:0493x7p','0493x7p','x7p','0493x7p','x3-x7 : Q6-g / Q6-g-f, dam-break et fermeture incompressible','Symétrisation Q6 commun','Applique la même convention symétrique au Q6 commun.','CODE','Q6_GF','Actif','B',NULL,NULL,NULL,NULL,'referentiel_jalons_SRC_GPU_SURF_20260905.tex',78);
INSERT INTO "milestones" VALUES('milestone:0493x7q','0493x7q','x7q','0493x7q','x3-x7 : Q6-g / Q6-g-f, dam-break et fermeture incompressible','Fermeture exacte du moment périodique','Mesure le moment B1/RT0 réellement appliqué aux particules et enlève le résidu uniforme k=0 dans les directions périodiques fullDomain.','CODE','Q6_GF','Actif automatiquement seulement dans son domaine; pas sur dam-break partiel','B',NULL,NULL,NULL,NULL,'referentiel_jalons_SRC_GPU_SURF_20260905.tex',79);
INSERT INTO "milestones" VALUES('milestone:0493x8k','0493x8k','x8k','0493x8k','x8 : conditions limites ouvertes et benchmark von Karman','Inlet segmenté Poiseuille local','Définit une coordonnée locale au segment et impose u_n=4 Umax eta(1-eta) de façon cohérente à l''injection particulaire et à Q6.','CODE','OPEN_BOUNDARY','Actif','B',NULL,NULL,NULL,NULL,'referentiel_jalons_SRC_GPU_SURF_20260905.tex',81);
INSERT INTO "milestones" VALUES('milestone:0493x8q','0493x8q','x8q','0493x8q','x8 : conditions limites ouvertes et benchmark von Karman','Continuation cinétique outlet','Supprime les sortants et reconstruit la demi-distribution entrante depuis les moments de couches intérieures, pondérée par le flux normal.','CODE','OPEN_BOUNDARY','Actif pour outlet Neumann','B',NULL,NULL,NULL,NULL,'referentiel_jalons_SRC_GPU_SURF_20260905.tex',82);
INSERT INTO "milestones" VALUES('milestone:0493x8r','0493x8r','x8r','0493x8r','x8 : conditions limites ouvertes et benchmark von Karman','Outlet pression Neumann','Conserve gradient de vitesse normal nul pour la vitesse tentative mais impose phi_out=0 côté projection; ne réimpose plus UOUT comme cible physique.','CODE','OPEN_BOUNDARY','Actif','B',NULL,NULL,NULL,NULL,'referentiel_jalons_SRC_GPU_SURF_20260905.tex',83);
INSERT INTO "milestones" VALUES('milestone:0493x8s','0493x8s','x8s','0493x8s','x8 : conditions limites ouvertes et benchmark von Karman','Déflation des modes lents du CG','Résout analytiquement les modes longitudinaux les plus lents à l''initialisation du CG pour améliorer le conditionnement du canal long.','PERF','OPEN_BOUNDARY','Actif dans cas applicable','B',NULL,NULL,NULL,NULL,'referentiel_jalons_SRC_GPU_SURF_20260905.tex',84);
INSERT INTO "milestones" VALUES('milestone:0493x8t','0493x8t','x8t','0493x8t','x8 : conditions limites ouvertes et benchmark von Karman','Relaxation densité sans mode moyen','Retire uniquement la moyenne spatiale de la cible de relaxation de densité quand outlet pression + fullDomain sont actifs.','CODE','OPEN_BOUNDARY','Actif dans cas applicable','B',NULL,NULL,NULL,NULL,'referentiel_jalons_SRC_GPU_SURF_20260905.tex',85);
INSERT INTO "milestones" VALUES('milestone:0493x8j','0493x8j','x8j','0493x8j','x8 : conditions limites ouvertes et benchmark von Karman','Analyse VK POD + sondes','Analyseur de shedding: fréquence POD et probe, phase spatiale, période et comparaison bibliographique.','ANALYZER','OPEN_BOUNDARY','Tooling/qualification, pas une physique','B',NULL,NULL,NULL,NULL,'referentiel_jalons_SRC_GPU_SURF_20260905.tex',86);
INSERT INTO "milestones" VALUES('milestone:0493x9a-x9c','0493x9a-x9c','x9a-x9c','0493x9a-x9c','x9 : tension superficielle, courbure et mouillage','Choix de la géométrie de courbure','Compare les constructions de champ de courbure; production retient trois passes binomiales 3x3 + gradient/divergence de Scharr (p3).','CODE','SURFACE_TENSION','Étapes de sélection; p3 retenu','B',NULL,NULL,NULL,NULL,'referentiel_jalons_SRC_GPU_SURF_20260905.tex',88);
INSERT INTO "milestones" VALUES('milestone:0493x9d','0493x9d','x9d','0493x9d','x9 : tension superficielle, courbure et mouillage','Activation du saut de Laplace','Ajoute sigma*kappa au potentiel de Dirichlet Q6-g-f; pas de force CSF ni kick particulaire direct.','CODE','SURFACE_TENSION','Actif; coeur de la tension superficielle','B',NULL,NULL,NULL,NULL,'referentiel_jalons_SRC_GPU_SURF_20260905.tex',89);
INSERT INTO "milestones" VALUES('milestone:0493x9e','0493x9e','x9e','0493x9e','x9 : tension superficielle, courbure et mouillage','Diagnostic pression goutte statique','Mesure le saut de pression reconstruit dans la solution Q6 et les grandeurs géométriques des gouttes.','DIAGNOSTIC','SURFACE_TENSION','Diagnostic/qualification','B',NULL,NULL,NULL,NULL,'referentiel_jalons_SRC_GPU_SURF_20260905.tex',90);
INSERT INTO "milestones" VALUES('milestone:0493x9f','0493x9f','x9f','0493x9f','x9 : tension superficielle, courbure et mouillage','Diagnostic quadrupole signé','Observable de forme pour suivre les modes d''oscillation des gouttes.','DIAGNOSTIC','SURFACE_TENSION','Diagnostic/qualification','B',NULL,NULL,NULL,NULL,'referentiel_jalons_SRC_GPU_SURF_20260905.tex',91);
INSERT INTO "milestones" VALUES('milestone:0493x9g','0493x9g','x9g','0493x9g','x9 : tension superficielle, courbure et mouillage','Sélecteurs de phases A/B','Généralise les côtés de l''interface: family:liquid/gas, type:N, vacuum, wall, etc.','CODE','SURFACE_TENSION','Actif','B',NULL,NULL,NULL,NULL,'referentiel_jalons_SRC_GPU_SURF_20260905.tex',92);
INSERT INTO "milestones" VALUES('milestone:0493x9h','0493x9h','x9h','0493x9h','x9 : tension superficielle, courbure et mouillage','Géométrie de paroi pour mouillage','Traite wall comme troisième objet géométrique, distinct des deux phases capillaires.','CODE','SURFACE_TENSION','Actif dans mouillage','B',NULL,NULL,NULL,NULL,'referentiel_jalons_SRC_GPU_SURF_20260905.tex',93);
INSERT INTO "milestones" VALUES('milestone:0493x9i-x9l','0493x9i-x9l','x9i-x9l','0493x9i-x9l','x9 : tension superficielle, courbure et mouillage','Prototypes angle de contact','Teste remplacement de normale, ghost alpha et reconstructions pariétales; révèle biais de courbure malgré angle local correct.','ABLATION','SURFACE_TENSION','Ablations/supplantés','B',NULL,NULL,NULL,NULL,'referentiel_jalons_SRC_GPU_SURF_20260905.tex',94);
INSERT INTO "milestones" VALUES('milestone:0493x9m','0493x9m','x9m','0493x9m','x9 : tension superficielle, courbure et mouillage','Fermeture statique de mouillage','Construit la courbure de contact à partir d''une normale imposée au mur et d''une normale p3 hors support pariétal.','CODE','SURFACE_TENSION','Bonne statique; dynamique ligne triple non fermée','B',NULL,NULL,NULL,NULL,'referentiel_jalons_SRC_GPU_SURF_20260905.tex',95);
INSERT INTO "milestones" VALUES('milestone:0493x9r','0493x9r','x9r','0493x9r','x9 : tension superficielle, courbure et mouillage','Cutoff de petite courbure résolue','Borne uniquement kappa utilisé dans sigma*kappa par un rayon minimal en cellules; ne modifie pas alpha ni le champ kappa brut.','BENCHMARK','SURFACE_TENSION','Actif selon benchmark; paramètre de résolution','B',NULL,NULL,NULL,NULL,'referentiel_jalons_SRC_GPU_SURF_20260905.tex',96);
INSERT INTO "milestones" VALUES('milestone:0493x9s','0493x9s','x9s','0493x9s','x9 : tension superficielle, courbure et mouillage','Impact/splash paramétrable','Runners goutte -> paroi sèche ou flaque pour changements de topologie et splash.','BENCHMARK','SURFACE_TENSION','Démonstration/qualification qualitative','B',NULL,NULL,NULL,NULL,'referentiel_jalons_SRC_GPU_SURF_20260905.tex',97);
INSERT INTO "milestones" VALUES('milestone:0493x10a-x10e','0493x10a-x10e','x10a-x10e','0493x10a-x10e','x10-x12 : fermeture cinétique de surface libre','Premières barrières / seals / réactions','Premières géométries de crossing et réactions locales pour empêcher les sorties de support.','CODE','FREE_SURFACE_KINETICS','Historique, supplanté','B',NULL,NULL,NULL,NULL,'referentiel_jalons_SRC_GPU_SURF_20260905.tex',99);
INSERT INTO "milestones" VALUES('milestone:0493x10f-x10g','0493x10f-x10g','x10f-x10g','0493x10f-x10g','x10-x12 : fermeture cinétique de surface libre','Réaction conservative globale','Réduction globale des grandeurs de réaction pour éviter des receivers cellule par cellule.','CODE','FREE_SURFACE_KINETICS','Code conservé sans call-site actif','B',NULL,NULL,NULL,NULL,'referentiel_jalons_SRC_GPU_SURF_20260905.tex',100);
INSERT INTO "milestones" VALUES('milestone:0493x10h-x10i','0493x10h-x10i','x10h-x10i','0493x10h-x10i','x10-x12 : fermeture cinétique de surface libre','Critère relatif et réaction par blocs','Utilise (v-u_Gamma).n et une réaction mésoscopique; x10i sert de fallback hard r=1 legacy.','RUNNER','FREE_SURFACE_KINETICS','Legacy; bypassé par x10o dans runners récents','B',NULL,NULL,NULL,NULL,'referentiel_jalons_SRC_GPU_SURF_20260905.tex',101);
INSERT INTO "milestones" VALUES('milestone:0493x10j','0493x10j','x10j','0493x10j','x10-x12 : fermeture cinétique de surface libre','Réflexion spéculaire labo','Réfléchit la vitesse dans le repère laboratoire.','ABLATION','FREE_SURFACE_KINETICS','Ablation rejetée: bloque fortement le dripping','B',NULL,NULL,NULL,NULL,'referentiel_jalons_SRC_GPU_SURF_20260905.tex',102);
INSERT INTO "milestones" VALUES('milestone:0493x10k','0493x10k','x10k','0493x10k','x10-x12 : fermeture cinétique de surface libre','Réflexion spéculaire repère interface','Réflexion dans le repère local mobile de l''interface.','ABLATION','FREE_SURFACE_KINETICS','Ablation rejetée','B',NULL,NULL,NULL,NULL,'referentiel_jalons_SRC_GPU_SURF_20260905.tex',103);
INSERT INTO "milestones" VALUES('milestone:0493x10l','0493x10l','x10l','0493x10l','x10-x12 : fermeture cinétique de surface libre','Diagnostic pré-mur cinétique','Mesure l''état juste avant fermeture et montre que Q6/B1 garde un mouvement normal sortant avant le traitement cinétique.','DIAGNOSTIC','FREE_SURFACE_KINETICS','Diagnostic passif','B',NULL,NULL,NULL,NULL,'referentiel_jalons_SRC_GPU_SURF_20260905.tex',104);
INSERT INTO "milestones" VALUES('milestone:0493x10m','0493x10m','x10m','0493x10m','x10-x12 : fermeture cinétique de surface libre','Paroi implicite mobile / scratch','Étape architecturale; buffers cellulaires ensuite réutilisés par x10v et autres briques.','ABLATION','FREE_SURFACE_KINETICS','Ablation/infrastructure','B',NULL,NULL,NULL,NULL,'referentiel_jalons_SRC_GPU_SURF_20260905.tex',105);
INSERT INTO "milestones" VALUES('milestone:0493x10n','0493x10n','x10n','0493x10n','x10-x12 : fermeture cinétique de surface libre','Polyligne continue marching-squares','Construit segments, normales et primitives continues réutilisées par x10o, Q2, x12a et plus tard x14.','INFRA','FREE_SURFACE_KINETICS','Infrastructure active','B',NULL,NULL,NULL,NULL,'referentiel_jalons_SRC_GPU_SURF_20260905.tex',106);
INSERT INTO "milestones" VALUES('milestone:0493x10o','0493x10o','x10o','0493x10o','x10-x12 : fermeture cinétique de surface libre','Paroi thermique / enveloppe locale','Interface continue Q6 avec enveloppe thermique delta_th=min(C_T dt sqrt(kBT/m), delta_max).','CODE','FREE_SURFACE_KINETICS','Socle actif de la fermeture liquide x12','B',NULL,NULL,NULL,NULL,'referentiel_jalons_SRC_GPU_SURF_20260905.tex',107);
INSERT INTO "milestones" VALUES('milestone:reference:x10p/x10q','reference:x10p/x10q','x10p/x10q',NULL,'x10-x12 : fermeture cinétique de surface libre','Résolution recouvrements initiaux','Traite particules déjà du mauvais côté; recherche 3x3 puis fallback 7x7 rare si aucun segment trouvé.','CODE','FREE_SURFACE_KINETICS','Actif','B',NULL,NULL,NULL,NULL,'referentiel_jalons_SRC_GPU_SURF_20260905.tex',108);
