INSERT INTO "milestones" VALUES('milestone:reference:x10biq / Q2','reference:x10biq / Q2','x10biq / Q2',NULL,'x10-x12 : fermeture cinétique de surface libre','Reconstruction biquadratique tensorielle','Utilise les 9 valeurs CIC d''un patch 3x3 pour crossing et normale subcellulaires; pas de grille de coefficients supplémentaire.','CODE','FREE_SURFACE_KINETICS','Actif','B',NULL,NULL,NULL,NULL,'referentiel_jalons_SRC_GPU_SURF_20260905.tex',110);
INSERT INTO "milestones" VALUES('milestone:0493x10r','0493x10r','x10r','0493x10r','x10-x12 : fermeture cinétique de surface libre','Vitesses endpoints full-vector','Améliore covariance galiléenne par vitesses vectorielles complètes aux endpoints.','ABLATION','FREE_SURFACE_KINETICS','Ablation rejetée: dripping dégradé','B',NULL,NULL,NULL,NULL,'referentiel_jalons_SRC_GPU_SURF_20260905.tex',111);
INSERT INTO "milestones" VALUES('milestone:0493x10s','0493x10s','x10s','0493x10s','x10-x12 : fermeture cinétique de surface libre','Cinématique normale au segment','Projette la cinématique sur la normale du segment.','ABLATION','FREE_SURFACE_KINETICS','Ablation rejetée/OFF','B',NULL,NULL,NULL,NULL,'referentiel_jalons_SRC_GPU_SURF_20260905.tex',112);
INSERT INTO "milestones" VALUES('milestone:0493x10t','0493x10t','x10t','0493x10t','x10-x12 : fermeture cinétique de surface libre','Cinématique tangentielle rigide','Ajoute une cinématique tangentielle rigide.','ABLATION','FREE_SURFACE_KINETICS','Ablation rejetée; impulse parasite aggravée','B',NULL,NULL,NULL,NULL,'referentiel_jalons_SRC_GPU_SURF_20260905.tex',113);
INSERT INTO "milestones" VALUES('milestone:0493x10u','0493x10u','x10u','0493x10u','x10-x12 : fermeture cinétique de surface libre','Relocalisation one-for-one','Miroire uniquement la position d''une particule sortante; même slot, masse et vitesse, sans kick direct.','CODE','FREE_SURFACE_KINETICS','Actif dans chaîne liquide qualifiée','B',NULL,NULL,NULL,NULL,'referentiel_jalons_SRC_GPU_SURF_20260905.tex',114);
INSERT INTO "milestones" VALUES('milestone:0493x10v','0493x10v','x10v','0493x10v','x10-x12 : fermeture cinétique de surface libre','Swap local full-vector','Échange le vecteur vitesse complet avec un partenaire liquide intérieur de même masse; conserve exactement P et K de la paire.','CODE','FREE_SURFACE_KINETICS','Actif; peut ajouter dispersion/dissipation interfaciale','B',NULL,NULL,NULL,NULL,'referentiel_jalons_SRC_GPU_SURF_20260905.tex',115);
INSERT INTO "milestones" VALUES('milestone:0493x10w','0493x10w','x10w','0493x10w','x10-x12 : fermeture cinétique de surface libre','Limiter thermique pairwise','Réduction thermique locale avec redistribution pairwise conservative P/K.','CODE','FREE_SURFACE_KINETICS','Implémenté mais OFF; exclusif avec x12a','B',NULL,NULL,NULL,NULL,'referentiel_jalons_SRC_GPU_SURF_20260905.tex',116);
INSERT INTO "milestones" VALUES('milestone:0493x11a','0493x11a','x11a','0493x11a','x10-x12 : fermeture cinétique de surface libre','Validation Young-Laplace','Suite de gouttes statiques multi-rayons/multi-sigma utilisant x9e pour comparer Delta p_Q6 à sigma/R_eff.','INFRA','FREE_SURFACE_KINETICS','Tooling de qualification','B',NULL,NULL,NULL,NULL,'referentiel_jalons_SRC_GPU_SURF_20260905.tex',117);
INSERT INTO "milestones" VALUES('milestone:0493x11b','0493x11b','x11b','0493x11b','x10-x12 : fermeture cinétique de surface libre','Dispersion onde capillaire','Suit une interface sinusoïdale et ajuste une oscillation amortie pour mesurer la dispersion capillaire.','INFRA','FREE_SURFACE_KINETICS','Tooling de qualification','B',NULL,NULL,NULL,NULL,'referentiel_jalons_SRC_GPU_SURF_20260905.tex',118);
INSERT INTO "milestones" VALUES('milestone:0493x12a','0493x12a','x12a','0493x12a','x10-x12 : fermeture cinétique de surface libre','Refroidissement thermique local petites structures','Réduit kBT effectif et enveloppe x10o quand l''épaisseur locale L_loc devient inférieure au rayon Rc ~25.3h.','CODE','FREE_SURFACE_KINETICS','Actif dans chaîne liquide qualifiée','B',NULL,NULL,NULL,NULL,'referentiel_jalons_SRC_GPU_SURF_20260905.tex',119);
INSERT INTO "milestones" VALUES('milestone:reference:x12b/x12c','reference:x12b/x12c','x12b/x12c',NULL,'x10-x12 : fermeture cinétique de surface libre','Construction benchmark JFM','Étapes de construction/réduction du domaine splash JFM sans nouvelle physique C++.','BENCHMARK','FREE_SURFACE_KINETICS','Tooling historique','B',NULL,NULL,NULL,NULL,'referentiel_jalons_SRC_GPU_SURF_20260905.tex',120);
INSERT INTO "milestones" VALUES('milestone:0493x12d','0493x12d','x12d','0493x12d','x10-x12 : fermeture cinétique de surface libre','Benchmark JFM 524','Runner de mesure du splash/obstacle d''après Josserand-Lemoyne-Troeger-Zaleski.','BENCHMARK','FREE_SURFACE_KINETICS','Benchmark applicatif; similitude Re encore limitée','B',NULL,NULL,NULL,NULL,'referentiel_jalons_SRC_GPU_SURF_20260905.tex',121);
INSERT INTO "milestones" VALUES('milestone:0493x12cal','0493x12cal','x12cal','0493x12cal','x10-x12 : fermeture cinétique de surface libre','Calibrateur dynamique capillaire','Mesure la dispersion/frequence des ondes et distingue sigma_dyn de la tension mécanique.','CALIBRATOR','FREE_SURFACE_KINETICS','Qualification dynamique','B',NULL,NULL,NULL,NULL,'referentiel_jalons_SRC_GPU_SURF_20260905.tex',122);
