INSERT INTO "milestones" VALUES('milestone:0493x13a','0493x13a','x13a','0493x13a','x13 : propriétés de transport, fluide de référence et campagne Taylor-Culick','Pré-balayage analytique transport','Définit la portée intrinsèque des candidats SRC avant runs coûteux.','PERF','TRANSPORT_SURFACE','Tooling/calibration','B',NULL,NULL,NULL,NULL,'referentiel_jalons_SRC_GPU_SURF_20260905.tex',125);
INSERT INTO "milestones" VALUES('milestone:0493x13b','0493x13b','x13b','0493x13b','x13 : propriétés de transport, fluide de référence et campagne Taylor-Culick','Cisaillement transverse pur','Première métrologie de viscosité transverse; utile pour tendance/localité mais déclassée comme échelle absolue.','DIAGNOSTIC','TRANSPORT_SURFACE','Diagnostic historique','B',NULL,NULL,NULL,NULL,'referentiel_jalons_SRC_GPU_SURF_20260905.tex',126);
INSERT INTO "milestones" VALUES('milestone:0493x13c','0493x13c','x13c','0493x13c','x13 : propriétés de transport, fluide de référence et campagne Taylor-Culick','Choix de gamma','Qualifie l''occupation moyenne et conduit au choix économique gamma=8.','QUALIFICATION','TRANSPORT_SURFACE','Calibration','B',NULL,NULL,NULL,NULL,'referentiel_jalons_SRC_GPU_SURF_20260905.tex',127);
INSERT INTO "milestones" VALUES('milestone:0493x13d','0493x13d','x13d','0493x13d','x13 : propriétés de transport, fluide de référence et campagne Taylor-Culick','Longue longueur d''onde / acoustique','Ajoute grandes longueurs d''onde, corrige le calibrateur longitudinal amorti et qualifie un premier G08.','CALIBRATOR','TRANSPORT_SURFACE','Calibration','B',NULL,NULL,NULL,NULL,'referentiel_jalons_SRC_GPU_SURF_20260905.tex',128);
INSERT INTO "milestones" VALUES('milestone:0493x13e','0493x13e','x13e','0493x13e','x13 : propriétés de transport, fluide de référence et campagne Taylor-Culick','Sweep Mach','Explore la réponse non linéaire compressible et sépare domaine résolu et domaine constitutif sûr.','CODE','TRANSPORT_SURFACE','Calibration','B',NULL,NULL,NULL,NULL,'referentiel_jalons_SRC_GPU_SURF_20260905.tex',129);
INSERT INTO "milestones" VALUES('milestone:0493x13f','0493x13f','x13f','0493x13f','x13 : propriétés de transport, fluide de référence et campagne Taylor-Culick','Optimisation (angle, lambda/h)','Sweep local à gamma=8 pour réduire viscosité/coût tout en conservant propagation acceptable.','PERF','TRANSPORT_SURFACE','Calibration','B',NULL,NULL,NULL,NULL,'referentiel_jalons_SRC_GPU_SURF_20260905.tex',130);
INSERT INTO "milestones" VALUES('milestone:0493x13g','0493x13g','x13g','0493x13g','x13 : propriétés de transport, fluide de référence et campagne Taylor-Culick','Reproductibilité statistique GPU','Montre qu''état initial + seed identiques ne donnent pas une trajectoire GPU bit-à-bit; impose analyses multi-graines.','CODE','TRANSPORT_SURFACE','Règle méthodologique','B',NULL,NULL,NULL,NULL,'referentiel_jalons_SRC_GPU_SURF_20260905.tex',131);
INSERT INTO "milestones" VALUES('milestone:0493x13h-a','0493x13h-a','x13h-A','0493x13h-a','x13 : propriétés de transport, fluide de référence et campagne Taylor-Culick','Acoustique point final lambda/h=0.72','Mesure c_s et viscosité longitudinale du fluide final avec amplitudes multiples et bootstrap.','QUALIFICATION','TRANSPORT_SURFACE','Qualification constitutive','B',NULL,NULL,NULL,NULL,'referentiel_jalons_SRC_GPU_SURF_20260905.tex',132);
INSERT INTO "milestones" VALUES('milestone:0493x13h-b','0493x13h-b','x13h-B','0493x13h-b','x13 : propriétés de transport, fluide de référence et campagne Taylor-Culick','Viscosité vs densité / localité','Cartographie la dépendance à gamma et la frontière de localité; échelle absolue ensuite réauditée par Taylor-Green.','QUALIFICATION','TRANSPORT_SURFACE','Qualification constitutive','B',NULL,NULL,NULL,NULL,'referentiel_jalons_SRC_GPU_SURF_20260905.tex',133);
INSERT INTO "milestones" VALUES('milestone:0493x13h-c','0493x13h-c','x13h-C','0493x13h-c','x13 : propriétés de transport, fluide de référence et campagne Taylor-Culick','Domaine Mach final','Définit l''enveloppe de densité/Mach du fluide G08-0.72.','QUALIFICATION','TRANSPORT_SURFACE','Qualification constitutive','B',NULL,NULL,NULL,NULL,'referentiel_jalons_SRC_GPU_SURF_20260905.tex',134);
INSERT INTO "milestones" VALUES('milestone:0493x13h','0493x13h','x13h','0493x13h','x13 : propriétés de transport, fluide de référence et campagne Taylor-Culick','Point liquide de référence','Fluide économique gamma=8, angle 120 deg, lambda/h=0.72; utilisé pour qualification surface libre finale.','QUALIFICATION','TRANSPORT_SURFACE','Référence liquide qualifiée 31/08/2026','B',NULL,NULL,NULL,NULL,'referentiel_jalons_SRC_GPU_SURF_20260905.tex',135);
INSERT INTO "milestones" VALUES('milestone:0493x13j','0493x13j','x13j','0493x13j','x13 : propriétés de transport, fluide de référence et campagne Taylor-Culick','Young-Laplace x13h smoke','Smoke/qualification mécanique du point x13h; un seul point n''est pas une qualification multi-rayons.','INFRA','TRANSPORT_SURFACE','Tooling','B',NULL,NULL,NULL,NULL,'referentiel_jalons_SRC_GPU_SURF_20260905.tex',136);
INSERT INTO "milestones" VALUES('milestone:0493x13k','0493x13k','x13k','0493x13k','x13 : propriétés de transport, fluide de référence et campagne Taylor-Culick','Goutte oscillante n=2','Validation dynamique capillaire du mode azimutal n=2 sur fluide x13h.','BENCHMARK','TRANSPORT_SURFACE','Qualifié historique','B',NULL,NULL,NULL,NULL,'referentiel_jalons_SRC_GPU_SURF_20260905.tex',137);
INSERT INTO "milestones" VALUES('milestone:0493x13l','0493x13l','x13l','0493x13l','x13 : propriétés de transport, fluide de référence et campagne Taylor-Culick','Goutte oscillante n=3','Validation dynamique capillaire du mode n=3.','BENCHMARK','TRANSPORT_SURFACE','Qualifié historique','B',NULL,NULL,NULL,NULL,'referentiel_jalons_SRC_GPU_SURF_20260905.tex',138);
INSERT INTO "milestones" VALUES('milestone:0493x13m','0493x13m','x13m','0493x13m','x13 : propriétés de transport, fluide de référence et campagne Taylor-Culick','Goutte oscillante n=4','Validation dynamique capillaire du mode n=4.','BENCHMARK','TRANSPORT_SURFACE','Qualifié historique','B',NULL,NULL,NULL,NULL,'referentiel_jalons_SRC_GPU_SURF_20260905.tex',139);
INSERT INTO "milestones" VALUES('milestone:0493x13n','0493x13n','x13n','0493x13n','x13 : propriétés de transport, fluide de référence et campagne Taylor-Culick','Taylor-Culick 2D','Benchmark de rétraction de nappe; révèle une vitesse trop faible malgré traction capillaire locale proche de 2 sigma.','BENCHMARK','TRANSPORT_SURFACE','Limite dynamique connue; référence G_TC ~0.795 au rollback','B',NULL,NULL,NULL,NULL,'referentiel_jalons_SRC_GPU_SURF_20260905.tex',140);
INSERT INTO "milestones" VALUES('milestone:0493x13o','0493x13o','x13o','0493x13o','x13 : propriétés de transport, fluide de référence et campagne Taylor-Culick','Swap normal-only','Ablation de x10v: échange seulement la composante normale locale et laisse tangentielle inchangée.','ABLATION','TRANSPORT_SURFACE','OFF production','B',NULL,NULL,NULL,NULL,'referentiel_jalons_SRC_GPU_SURF_20260905.tex',141);
INSERT INTO "milestones" VALUES('milestone:reference:x13r/x13s','reference:x13r/x13s','x13r/x13s',NULL,'x13 : propriétés de transport, fluide de référence et campagne Taylor-Culick','Refroidissements locaux directs','Tentatives plus agressives de refroidissement interfacial pour accélérer Taylor-Culick.','BENCHMARK','TRANSPORT_SURFACE','Rejetées','B',NULL,NULL,NULL,NULL,'referentiel_jalons_SRC_GPU_SURF_20260905.tex',142);
INSERT INTO "milestones" VALUES('milestone:0493x13t','0493x13t','x13t','0493x13t','x13 : propriétés de transport, fluide de référence et campagne Taylor-Culick','Refroidissement progressif unifié','Loi progressive de refroidissement/rétention fondée sur l''échelle locale.','ABLATION','TRANSPORT_SURFACE','Rejetée comme chemin général','B',NULL,NULL,NULL,NULL,'referentiel_jalons_SRC_GPU_SURF_20260905.tex',143);
INSERT INTO "milestones" VALUES('milestone:reference:x13u/x13v','reference:x13u/x13v','x13u/x13v',NULL,'x13 : propriétés de transport, fluide de référence et campagne Taylor-Culick','Rétention one-for-one sous x13t','Sépare correction de position et swap pour tester la rétention des particules au rim.','ABLATION','TRANSPORT_SURFACE','Expérimental/rejeté','B',NULL,NULL,NULL,NULL,'referentiel_jalons_SRC_GPU_SURF_20260905.tex',144);
INSERT INTO "milestones" VALUES('milestone:0493x13w','0493x13w','x13w','0493x13w','x13 : propriétés de transport, fluide de référence et campagne Taylor-Culick','Escape -> inactive -> reseed','Transforme les sorties en slots inactifs puis réensemence localement côté liquide.','ABLATION','TRANSPORT_SURFACE','Rejeté: contraction artificielle du support','B',NULL,NULL,NULL,NULL,'referentiel_jalons_SRC_GPU_SURF_20260905.tex',145);
INSERT INTO "milestones" VALUES('milestone:0493x13w-fix3','0493x13w-fix3','x13w-fix3','0493x13w-fix3','x13 : propriétés de transport, fluide de référence et campagne Taylor-Culick','Correctif reseed','Version corrigée du choix géométrique de cellule de reseed utilisée dans la validation croisée finale.','FIX','TRANSPORT_SURFACE','Toujours invalidée physiquement','B',NULL,NULL,NULL,NULL,'referentiel_jalons_SRC_GPU_SURF_20260905.tex',146);
INSERT INTO "milestones" VALUES('milestone:0493x13x','0493x13x','x13x','0493x13x','x13 : propriétés de transport, fluide de référence et campagne Taylor-Culick','Rétention probabiliste','Balaye une fraction de rétention pour chercher compromis Taylor-Culick / dynamique de goutte.','BENCHMARK','TRANSPORT_SURFACE','Aucun compromis robuste','B',NULL,NULL,NULL,NULL,'referentiel_jalons_SRC_GPU_SURF_20260905.tex',147);
INSERT INTO "milestones" VALUES('milestone:0493x13z','0493x13z','x13z','0493x13z','x13 : propriétés de transport, fluide de référence et campagne Taylor-Culick','Changements de grille','Explore raffinement de grille et gains Taylor-Culick.','BENCHMARK','TRANSPORT_SURFACE','Non suffisant pour validation','B',NULL,NULL,NULL,NULL,'referentiel_jalons_SRC_GPU_SURF_20260905.tex',148);
INSERT INTO "milestones" VALUES('milestone:0493x13za-x13zc','0493x13za-x13zc','x13za-x13zc','0493x13za-x13zc','x13 : propriétés de transport, fluide de référence et campagne Taylor-Culick','Dépendance de grille de l''interface','Analyse rayon effectif, courbure et métriques Young-Laplace lors du raffinement.','DIAGNOSTIC','TRANSPORT_SURFACE','Diagnostic; révèle forte dépendance de kappa_active à forte sigma','B',NULL,NULL,NULL,NULL,'referentiel_jalons_SRC_GPU_SURF_20260905.tex',149);
INSERT INTO "milestones" VALUES('milestone:0493x13zd','0493x13zd','x13zd','0493x13zd','x13 : propriétés de transport, fluide de référence et campagne Taylor-Culick','Validation croisée décisive','Teste x13t+x13w sur gouttes oscillantes; montre contraction de support et détruit la dynamique modale.','QUALIFICATION','TRANSPORT_SURFACE','Invalide ces fermetures; motive rollback au tag qualifié','B',NULL,NULL,NULL,NULL,'referentiel_jalons_SRC_GPU_SURF_20260905.tex',150);
INSERT INTO "milestones" VALUES('milestone:0493x14a-x14j','0493x14a-x14j','x14a-x14j','0493x14a-x14j','x14 : phase gaz explicite et transfert liquide-gaz','Thermostat séparé par espèce','Ajoute des cibles kBT propres aux espèces après collision SRC commune, sans séparer la collision du mélange.','CODE','LIQUID_GAS','Architecture x14','B',NULL,NULL,NULL,NULL,'referentiel_jalons_SRC_GPU_SURF_20260905.tex',152);
INSERT INTO "milestones" VALUES('milestone:0493x14d','0493x14d','x14d','0493x14d','x14 : phase gaz explicite et transfert liquide-gaz','Collision commune + thermostats séparés','Conserve SRC commun au mélange; seule la remise à température est faite par type.','CODE','LIQUID_GAS','Actif dans x14','B',NULL,NULL,NULL,NULL,'referentiel_jalons_SRC_GPU_SURF_20260905.tex',153);
INSERT INTO "milestones" VALUES('milestone:0493x14g','0493x14g','x14g','0493x14g','x14 : phase gaz explicite et transfert liquide-gaz','Cellules exactes post-stream/grid-shift','Utilise les identifiants de cellule SRC persistants exacts pour thermostat par espèce.','FIX','LIQUID_GAS','Correctif d''intégration actif','B',NULL,NULL,NULL,NULL,'referentiel_jalons_SRC_GPU_SURF_20260905.tex',154);
INSERT INTO "milestones" VALUES('milestone:0493x14j','0493x14j','x14j','0493x14j','x14 : phase gaz explicite et transfert liquide-gaz','Goutte deux températures','Cas d''intégration thermostat liquide/gaz avant fermeture cinétique bilatérale.','BENCHMARK','LIQUID_GAS','Benchmark d''intégration','B',NULL,NULL,NULL,NULL,'referentiel_jalons_SRC_GPU_SURF_20260905.tex',155);
INSERT INTO "milestones" VALUES('milestone:0493x14k','0493x14k','x14k','0493x14k','x14 : phase gaz explicite et transfert liquide-gaz','Géométrie cinétique bilatérale','Autorise le côté gaz à consommer la même géométrie de relocalisation x10 que le liquide, avec sens de phase inversé.','CODE','LIQUID_GAS','Opt-in; change le modèle d''interface','B',NULL,NULL,NULL,NULL,'referentiel_jalons_SRC_GPU_SURF_20260905.tex',156);
INSERT INTO "milestones" VALUES('milestone:0493x14l','0493x14l','x14l','0493x14l','x14 : phase gaz explicite et transfert liquide-gaz','Réflexion spéculaire du gaz','Réfléchit la composante normale relative du gaz à l''interface mobile; tangentielle inchangée.','CODE','LIQUID_GAS','Qualifié pour imperméabilité normale dans cas tests','B',NULL,NULL,NULL,NULL,'referentiel_jalons_SRC_GPU_SURF_20260905.tex',157);
INSERT INTO "milestones" VALUES('milestone:0493x14m','0493x14m','x14m','0493x14m','x14 : phase gaz explicite et transfert liquide-gaz','Assemblage bilatéral + compatibilité x12a','Combine liquide x10/x12, gaz x14l et thermostat séparé; x12a reste côté liquide uniquement.','CODE','LIQUID_GAS','Architecture intégrée','B',NULL,NULL,NULL,NULL,'referentiel_jalons_SRC_GPU_SURF_20260905.tex',158);
INSERT INTO "milestones" VALUES('milestone:0493x14n','0493x14n','x14n','0493x14n','x14 : phase gaz explicite et transfert liquide-gaz','Ablation fermeture gaz OFF','Coupe la fermeture cinétique gazeuse pour séparer pression et imperméabilité.','ABLATION','LIQUID_GAS','Ablation','B',NULL,NULL,NULL,NULL,'referentiel_jalons_SRC_GPU_SURF_20260905.tex',159);
INSERT INTO "milestones" VALUES('milestone:0493x14o','0493x14o','x14o','0493x14o','x14 : phase gaz explicite et transfert liquide-gaz','Ablation pression gaz constante','Utilise une pression gazeuse constante choisie pour annuler la contribution de jauge.','ABLATION','LIQUID_GAS','Ablation','B',NULL,NULL,NULL,NULL,'referentiel_jalons_SRC_GPU_SURF_20260905.tex',160);
INSERT INTO "milestones" VALUES('milestone:0493x14r','0493x14r','x14r','0493x14r','x14 : phase gaz explicite et transfert liquide-gaz','Analyse volume accessible','Analyse offline montrant que p=N kBT/A_cell sous-estime la pression si seule une fraction de cellule est accessible au gaz.','ANALYZER','LIQUID_GAS','Diagnostic conduisant à x14s','B',NULL,NULL,NULL,NULL,'referentiel_jalons_SRC_GPU_SURF_20260905.tex',161);
INSERT INTO "milestones" VALUES('milestone:0493x14s','0493x14s','x14s','0493x14s','x14 : phase gaz explicite et transfert liquide-gaz','EOS gaz volume accessible','Corrige la pression gazeuse par la fraction de volume accessible dérivée de alpha Q6.','CODE','LIQUID_GAS','Actif dans x14 récent','B',NULL,NULL,NULL,NULL,'referentiel_jalons_SRC_GPU_SURF_20260905.tex',162);
INSERT INTO "milestones" VALUES('milestone:0493x14t','0493x14t','x14t','0493x14t','x14 : phase gaz explicite et transfert liquide-gaz','Piston pression thermodynamique','Benchmark plan qui qualifie la transmission moyenne de p_g par x6g/x14s sans terme impulsionnel direct.','BENCHMARK','LIQUID_GAS','Qualification composante thermodynamique','B',NULL,NULL,NULL,NULL,'referentiel_jalons_SRC_GPU_SURF_20260905.tex',163);
INSERT INTO "milestones" VALUES('milestone:0493x14u','0493x14u','x14u','0493x14u','x14 : phase gaz explicite et transfert liquide-gaz','Gaz incident normal','Benchmark de flux de moment dirigé; montre que x14l seul rend imperméable mais ne restitue presque pas le moment perdu au liquide.','BENCHMARK','LIQUID_GAS','Diagnostic conduisant à x14v','B',NULL,NULL,NULL,NULL,'referentiel_jalons_SRC_GPU_SURF_20260905.tex',164);
INSERT INTO "milestones" VALUES('milestone:0493x14v','0493x14v','x14v','0493x14v','x14 : phase gaz explicite et transfert liquide-gaz','Kick cinétique excédentaire','Transfère J_excess = J_raw - J_thermo au liquide afin d''ajouter le flux cinétique hors équilibre sans doubler la pression x6g.','CODE','LIQUID_GAS','Actif dans chaîne x14 candidate','B',NULL,NULL,NULL,NULL,'referentiel_jalons_SRC_GPU_SURF_20260905.tex',165);
INSERT INTO "milestones" VALUES('milestone:0493x14w','0493x14w','x14w','0493x14w','x14 : phase gaz explicite et transfert liquide-gaz','Couette biphasique','Benchmark de transfert tangentiel; teste continuité de contrainte via collisions SRC communes sans frottement interfacial ad hoc.','BENCHMARK','LIQUID_GAS','PASS-like sur contrainte tangentielle','B',NULL,NULL,NULL,NULL,'referentiel_jalons_SRC_GPU_SURF_20260905.tex',166);
INSERT INTO "milestones" VALUES('milestone:0493x14x','0493x14x','x14x','0493x14x','x14 : phase gaz explicite et transfert liquide-gaz','Goutte oscillante diphasique n=2','Runner intégré x6g+x9+x14l+x14v+chaîne liquide; banc pour forme, moment et fréquence.','BENCHMARK','LIQUID_GAS','Qualification intégrée/tooling','B',NULL,NULL,NULL,NULL,'referentiel_jalons_SRC_GPU_SURF_20260905.tex',167);
INSERT INTO "milestones" VALUES('milestone:0493x14y','0493x14y','x14y','0493x14y','x14 : phase gaz explicite et transfert liquide-gaz','Ablation sans soustraction p_g','Transfère J_raw directement et supprime la soustraction thermodynamique.','ABLATION','LIQUID_GAS','Rejeté: double comptage pression équilibre','B',NULL,NULL,NULL,NULL,'referentiel_jalons_SRC_GPU_SURF_20260905.tex',168);
INSERT INTO "milestones" VALUES('milestone:0493x14z','0493x14z','x14z','0493x14z','x14 : phase gaz explicite et transfert liquide-gaz','Fermeture géométrique p_ref','Corrige la résultante du seul p_ref uniforme sur la polyligne x10n.','ABLATION','LIQUID_GAS','Rejeté comme cause du défaut n=1','B',NULL,NULL,NULL,NULL,'referentiel_jalons_SRC_GPU_SURF_20260905.tex',169);
INSERT INTO "milestones" VALUES('milestone:0493x14aa','0493x14aa','x14aa','0493x14aa','x14 : phase gaz explicite et transfert liquide-gaz','Traction thermodynamique absolue sur faces x6g','Déplace toute la traction sur la géométrie de faces Q6.','CODE','LIQUID_GAS','Non retenu: dégrade la géométrie locale de forme','B',NULL,NULL,NULL,NULL,'referentiel_jalons_SRC_GPU_SURF_20260905.tex',170);
INSERT INTO "milestones" VALUES('milestone:0493x14ab','0493x14ab','x14ab','0493x14ab','x14 : phase gaz explicite et transfert liquide-gaz','p_ref sur x10n + jauge sur faces x6g','Sépare référence et jauge mais garde traction variable sur normales axiales Q6.','CODE','LIQUID_GAS','Non retenu','B',NULL,NULL,NULL,NULL,'referentiel_jalons_SRC_GPU_SURF_20260905.tex',171);
INSERT INTO "milestones" VALUES('milestone:0493x14ac','0493x14ac','x14ac','0493x14ac','x14 : phase gaz explicite et transfert liquide-gaz','Projection globale minimum-L2','Garde l''ancien échantillonnage local et corrige uniquement la résultante globale.','CODE','LIQUID_GAS','Principe conservé, local supplanté par x14ad','B',NULL,NULL,NULL,NULL,'referentiel_jalons_SRC_GPU_SURF_20260905.tex',172);
INSERT INTO "milestones" VALUES('milestone:0493x14ad','0493x14ad','x14ad','0493x14ad','x14 : phase gaz explicite et transfert liquide-gaz','Traction locale cohérente avec faces x6g','Échantillonne la pression de jauge des faces représentées qui terminent chaque segment x10n, applique sur normale locale, puis corrige la résultante résiduelle.','CODE','LIQUID_GAS','Retenu pour interfaces courbes x14','B',NULL,NULL,NULL,NULL,'referentiel_jalons_SRC_GPU_SURF_20260905.tex',173);
INSERT INTO "milestones" VALUES('milestone:0493x14ae','0493x14ae','x14ae','0493x14ae','x14 : phase gaz explicite et transfert liquide-gaz','Diagnostic pertes scatter','Compte les kicks x14v qui ne trouvent aucun support liquide après CIC/fallback.','DIAGNOSTIC','LIQUID_GAS','Diagnostic; pertes nulles sur cas discriminant','B',NULL,NULL,NULL,NULL,'referentiel_jalons_SRC_GPU_SURF_20260905.tex',174);
INSERT INTO "milestones" VALUES('milestone:0493x14af','0493x14af','x14af','0493x14af','x14 : phase gaz explicite et transfert liquide-gaz','Diagnostic bilan global','Mesure J_Q6 applique, J_thermo et x14v; identifie le mismatch Q6/B1 - traction reconstruite comme source de dérive.','DIAGNOSTIC','LIQUID_GAS','Diagnostic causal','B',NULL,NULL,NULL,NULL,'referentiel_jalons_SRC_GPU_SURF_20260905.tex',175);
INSERT INTO "milestones" VALUES('milestone:0493x14ag','0493x14ag','x14ag','0493x14ag','x14 : phase gaz explicite et transfert liquide-gaz','Traînée avec inlet/outlet','Premier benchmark de traînée ouvert; évolution du gaz jusqu''à inversion du courant.','BENCHMARK','LIQUID_GAS','Abandonné','B',NULL,NULL,NULL,NULL,'referentiel_jalons_SRC_GPU_SURF_20260905.tex',176);
INSERT INTO "milestones" VALUES('milestone:0493x14ah','0493x14ah','x14ah','0493x14ah','x14 : phase gaz explicite et transfert liquide-gaz','Traînée périodique-x','Canal périodique avec goutte entraînée par un profil gazeux; vérifie que la fermeture ne supprime pas la vraie traînée.','BENCHMARK','LIQUID_GAS','Benchmark intégré','B',NULL,NULL,NULL,NULL,'referentiel_jalons_SRC_GPU_SURF_20260905.tex',177);
INSERT INTO "milestones" VALUES('milestone:0493x14ai','0493x14ai','x14ai','0493x14ai','x14 : phase gaz explicite et transfert liquide-gaz','Fermeture de résultante Q6 appliquée','Utilise la résultante B1/RT0 réellement appliquée comme cible globale de la projection de traction x14ad.','CODE','LIQUID_GAS','Concept retenu mais version initiale supplantée','B',NULL,NULL,NULL,NULL,'referentiel_jalons_SRC_GPU_SURF_20260905.tex',178);
INSERT INTO "milestones" VALUES('milestone:0493x14ai-fix1','0493x14ai-fix1','x14ai-fix1','0493x14ai-fix1','x14 : phase gaz explicite et transfert liquide-gaz','Fermeture B1 exacte post-correction périodique','Corrige la cible x14ai pour inclure la correction uniforme périodique B1; ferme le moment global au roundoff.','CODE','LIQUID_GAS','Seulement composante liquide fermée et isolée des frontières Q6 externes','B',NULL,NULL,NULL,NULL,'referentiel_jalons_SRC_GPU_SURF_20260905.tex',179);
INSERT INTO "milestones" VALUES('milestone:0493x14aj','0493x14aj','x14aj','0493x14aj','x14 : phase gaz explicite et transfert liquide-gaz','Goutte oscillante n=3 avec gaz','Qualification du mode n=3 de la chaîne x14ai-fix1.','BENCHMARK','LIQUID_GAS','REVIEW: fréquence ~12% lente dans campagne actuelle','B',NULL,NULL,NULL,NULL,'referentiel_jalons_SRC_GPU_SURF_20260905.tex',180);
INSERT INTO "milestones" VALUES('milestone:0493x14ak','0493x14ak','x14ak','0493x14ak','x14 : phase gaz explicite et transfert liquide-gaz','Taylor-Culick diphasique - fluide x14','TC avec paramètres liquide x14 (gamma=20, dt=0.002, etc.); comparaison historique confondait changement de fluide et effet gaz.','BENCHMARK','LIQUID_GAS','REVIEW; ne pas utiliser pour isoler effet gaz','B',NULL,NULL,NULL,NULL,'referentiel_jalons_SRC_GPU_SURF_20260905.tex',181);
INSERT INTO "milestones" VALUES('milestone:0493x14al','0493x14al','x14al','0493x14al','x14 : phase gaz explicite et transfert liquide-gaz','Taylor-Culick apparié au point x13h','Deux runs avec liquide initial identique: liquide seul vs même liquide + gaz, pour isoler le couplage gaz.','BENCHMARK','LIQUID_GAS','Contrôle liquide reproduit; branche gaz à relire car EOS global kBT avait été mal aligné dans le premier runner','B',NULL,NULL,NULL,NULL,'referentiel_jalons_SRC_GPU_SURF_20260905.tex',182);
INSERT INTO "milestones" VALUES('milestone:0493x14am','0493x14am','x14am','0493x14am','x14 : phase gaz explicite et transfert liquide-gaz','Young-Laplace diphasique multi-rayons','Screening multi-rayons avec x9e sans baseline sigma=0 longue.','DIAGNOSTIC','LIQUID_GAS','REVIEW/non décisif à sigma=10000: kappa_active et pression sont déjà connus comme métrologie bruyante/non monotone dans ce régime','B',NULL,NULL,NULL,NULL,'referentiel_jalons_SRC_GPU_SURF_20260905.tex',183);
INSERT INTO "milestones" VALUES('milestone:20260907-0414-segmented-xy','20260907-0414-segmented-xy','0414','20260907-0414-segmented-xy','Post-x14 / conditions limites ouvertes','Extension quadriface des open boundaries segmentées','Généralise les entrées/sorties segmentées aux axes x et y sur le chemin CUDA résident; crossing multi-axes chronologique, x8r quadriface, x8t généralisé, x8s séparable 1-D/2-D, gardes de coins/réservoirs et diagnostic low-face corrigé.','CODE','OPEN_BOUNDARY','QUALIFIED','A','2026-09-07',NULL,NULL,'Qualification Q1-Q7 et ablation x8s 2-D consolidées.','SRC_GPU_SURF_0414_final_segmented_xy_cuda_resident.patch',NULL);
