INSERT INTO "raw_milestone_rows" VALUES('referentiel_jalons_SRC_GPU_SURF_20260905.tex',81,'x8 : conditions limites ouvertes et benchmark von Karman','x8k','Inlet segmenté Poiseuille local','Définit une coordonnée locale au segment et impose u_n=4 Umax eta(1-eta) de façon cohérente à l''injection particulaire et à Q6.','Actif','\texttt{x8k} & Inlet segmenté Poiseuille local & Définit une coordonnée locale au segment et impose u\_n=4 Umax eta(1-eta) de façon cohérente à l''injection particulaire et à Q6. & Actif \\');
INSERT INTO "raw_milestone_rows" VALUES('referentiel_jalons_SRC_GPU_SURF_20260905.tex',82,'x8 : conditions limites ouvertes et benchmark von Karman','x8q','Continuation cinétique outlet','Supprime les sortants et reconstruit la demi-distribution entrante depuis les moments de couches intérieures, pondérée par le flux normal.','Actif pour outlet Neumann','\texttt{x8q} & Continuation cinétique outlet & Supprime les sortants et reconstruit la demi-distribution entrante depuis les moments de couches intérieures, pondérée par le flux normal. & Actif pour outlet Neumann \\');
INSERT INTO "raw_milestone_rows" VALUES('referentiel_jalons_SRC_GPU_SURF_20260905.tex',83,'x8 : conditions limites ouvertes et benchmark von Karman','x8r','Outlet pression Neumann','Conserve gradient de vitesse normal nul pour la vitesse tentative mais impose phi_out=0 côté projection; ne réimpose plus UOUT comme cible physique.','Actif','\texttt{x8r} & Outlet pression Neumann & Conserve gradient de vitesse normal nul pour la vitesse tentative mais impose phi\_out=0 côté projection; ne réimpose plus UOUT comme cible physique. & Actif \\');
INSERT INTO "raw_milestone_rows" VALUES('referentiel_jalons_SRC_GPU_SURF_20260905.tex',84,'x8 : conditions limites ouvertes et benchmark von Karman','x8s','Déflation des modes lents du CG','Résout analytiquement les modes longitudinaux les plus lents à l''initialisation du CG pour améliorer le conditionnement du canal long.','Actif dans cas applicable','\texttt{x8s} & Déflation des modes lents du CG & Résout analytiquement les modes longitudinaux les plus lents à l''initialisation du CG pour améliorer le conditionnement du canal long. & Actif dans cas applicable \\');
INSERT INTO "raw_milestone_rows" VALUES('referentiel_jalons_SRC_GPU_SURF_20260905.tex',85,'x8 : conditions limites ouvertes et benchmark von Karman','x8t','Relaxation densité sans mode moyen','Retire uniquement la moyenne spatiale de la cible de relaxation de densité quand outlet pression + fullDomain sont actifs.','Actif dans cas applicable','\texttt{x8t} & Relaxation densité sans mode moyen & Retire uniquement la moyenne spatiale de la cible de relaxation de densité quand outlet pression + fullDomain sont actifs. & Actif dans cas applicable \\');
INSERT INTO "raw_milestone_rows" VALUES('referentiel_jalons_SRC_GPU_SURF_20260905.tex',86,'x8 : conditions limites ouvertes et benchmark von Karman','x8j','Analyse VK POD + sondes','Analyseur de shedding: fréquence POD et probe, phase spatiale, période et comparaison bibliographique.','Tooling/qualification, pas une physique','\texttt{x8j} & Analyse VK POD + sondes & Analyseur de shedding: fréquence POD et probe, phase spatiale, période et comparaison bibliographique. & Tooling/qualification, pas une physique \\');
INSERT INTO "raw_milestone_rows" VALUES('referentiel_jalons_SRC_GPU_SURF_20260905.tex',88,'x9 : tension superficielle, courbure et mouillage','x9a-x9c','Choix de la géométrie de courbure','Compare les constructions de champ de courbure; production retient trois passes binomiales 3x3 + gradient/divergence de Scharr (p3).','Étapes de sélection; p3 retenu','\texttt{x9a-x9c} & Choix de la géométrie de courbure & Compare les constructions de champ de courbure; production retient trois passes binomiales 3x3 + gradient/divergence de Scharr (p3). & Étapes de sélection; p3 retenu \\');
