INSERT INTO "raw_milestone_rows" VALUES('referentiel_jalons_SRC_GPU_SURF_20260905.tex',177,'x14 : phase gaz explicite et transfert liquide-gaz','x14ah','Traînée périodique-x','Canal périodique avec goutte entraînée par un profil gazeux; vérifie que la fermeture ne supprime pas la vraie traînée.','Benchmark intégré','\texttt{x14ah} & Traînée périodique-x & Canal périodique avec goutte entraînée par un profil gazeux; vérifie que la fermeture ne supprime pas la vraie traînée. & Benchmark intégré \\');
