INSERT INTO "raw_milestone_rows" VALUES('referentiel_jalons_SRC_GPU_SURF_20260905.tex',179,'x14 : phase gaz explicite et transfert liquide-gaz','x14ai-fix1','Fermeture B1 exacte post-correction périodique','Corrige la cible x14ai pour inclure la correction uniforme périodique B1; ferme le moment global au roundoff.','Seulement composante liquide fermée et isolée des frontières Q6 externes','\texttt{x14ai-fix1} & Fermeture B1 exacte post-correction périodique & Corrige la cible x14ai pour inclure la correction uniforme périodique B1; ferme le moment global au roundoff. & Seulement composante liquide fermée et isolée des frontières Q6 externes \\');
INSERT INTO "raw_milestone_rows" VALUES('referentiel_jalons_SRC_GPU_SURF_20260905.tex',180,'x14 : phase gaz explicite et transfert liquide-gaz','x14aj','Goutte oscillante n=3 avec gaz','Qualification du mode n=3 de la chaîne x14ai-fix1.','REVIEW: fréquence ~12% lente dans campagne actuelle','\texttt{x14aj} & Goutte oscillante n=3 avec gaz & Qualification du mode n=3 de la chaîne x14ai-fix1. & REVIEW: fréquence \textasciitilde{}12\% lente dans campagne actuelle \\');
INSERT INTO "raw_milestone_rows" VALUES('referentiel_jalons_SRC_GPU_SURF_20260905.tex',181,'x14 : phase gaz explicite et transfert liquide-gaz','x14ak','Taylor-Culick diphasique - fluide x14','TC avec paramètres liquide x14 (gamma=20, dt=0.002, etc.); comparaison historique confondait changement de fluide et effet gaz.','REVIEW; ne pas utiliser pour isoler effet gaz','\texttt{x14ak} & Taylor-Culick diphasique - fluide x14 & TC avec paramètres liquide x14 (gamma=20, dt=0.002, etc.); comparaison historique confondait changement de fluide et effet gaz. & REVIEW; ne pas utiliser pour isoler effet gaz \\');
INSERT INTO "raw_milestone_rows" VALUES('referentiel_jalons_SRC_GPU_SURF_20260905.tex',182,'x14 : phase gaz explicite et transfert liquide-gaz','x14al','Taylor-Culick apparié au point x13h','Deux runs avec liquide initial identique: liquide seul vs même liquide + gaz, pour isoler le couplage gaz.','Contrôle liquide reproduit; branche gaz à relire car EOS global kBT avait été mal aligné dans le premier runner','\texttt{x14al} & Taylor-Culick apparié au point x13h & Deux runs avec liquide initial identique: liquide seul vs même liquide + gaz, pour isoler le couplage gaz. & Contrôle liquide reproduit; branche gaz à relire car EOS global kBT avait été mal aligné dans le premier runner \\');
INSERT INTO "raw_milestone_rows" VALUES('referentiel_jalons_SRC_GPU_SURF_20260905.tex',183,'x14 : phase gaz explicite et transfert liquide-gaz','x14am','Young-Laplace diphasique multi-rayons','Screening multi-rayons avec x9e sans baseline sigma=0 longue.','REVIEW/non décisif à sigma=10000: kappa_active et pression sont déjà connus comme métrologie bruyante/non monotone dans ce régime','\texttt{x14am} & Young-Laplace diphasique multi-rayons & Screening multi-rayons avec x9e sans baseline sigma=0 longue. & REVIEW/non décisif à sigma=10000: kappa\_active et pression sont déjà connus comme métrologie bruyante/non monotone dans ce régime \\');
