INSERT INTO "raw_params_inventory" VALUES('src_mpcd_params_inventory_snapshot_040926_x14ai.csv',76,'openBoundaryOutletForcedLayerCells','params_canonical_field','Entrées/sorties — modes outlet','existant catalogue 0292','entier','1','>= 1','openBoundaryOutletForcedLayerCells','','Épaisseur de la zone d’extraction forcée, en nombre de cellules à partir de la face outlet.','Utilisé en forced_flux/equilibrium_flux pour sélectionner l’épaisseur de couche outlet où la masse/les particules peuvent être extraites. Les scripts de démo peuvent choisir 3 par défaut.','simulation_params.h; params_io_base.cpp; cuda_classic_src_io_resident_0263.cu; patch 0291','src_mpcd_params_catalogue_0292_cuda.csv');
INSERT INTO "raw_params_inventory" VALUES('src_mpcd_params_inventory_snapshot_040926_x14ai.csv',77,'openBoundaryOutletForcedMassFlux','params_canonical_field','Entrées/sorties — modes outlet','existant catalogue 0292','double','0.0','>= 0; unités masse / temps simulation','openBoundaryOutletForcedMassFlux','','Flux de masse sortant imposé par l’utilisateur, découplé du flux inlet.','Utilisé si openBoundaryOutletMode=forced_flux et aucun flux particulaire prioritaire n’est donné. Masse extraite par step = flux * dt.','simulation_params.h; params_io_base.cpp; cuda_classic_src_io_resident_0263.cu; patch 0291','src_mpcd_params_catalogue_0292_cuda.csv');
INSERT INTO "raw_params_inventory" VALUES('src_mpcd_params_inventory_snapshot_040926_x14ai.csv',78,'openBoundaryOutletForcedMassPerStep','params_canonical_field','Entrées/sorties — modes outlet','existant catalogue 0292','double','0.0','>= 0; masse / step','openBoundaryOutletForcedMassPerStep','','Masse cible à extraire à chaque step dans la couche outlet.','Utilisé si openBoundaryOutletMode=forced_flux et si aucun flux particulaire prioritaire n’est donné. Prioritaire sur openBoundaryOutletForcedMassFlux pour la masse.','simulation_params.h; params_io_base.cpp; cuda_classic_src_io_resident_0263.cu; patch 0291','src_mpcd_params_catalogue_0292_cuda.csv');
INSERT INTO "raw_params_inventory" VALUES('src_mpcd_params_inventory_snapshot_040926_x14ai.csv',79,'openBoundaryOutletForcedParticleFlux','params_canonical_field','Entrées/sorties — modes outlet','existant catalogue 0292','double','0.0','>= 0; particules / temps simulation','openBoundaryOutletForcedParticleFlux','','Flux particulaire sortant imposé par l’utilisateur, découplé du flux inlet.','Utilisé si openBoundaryOutletMode=forced_flux. Nombre extrait par step = flux * dt, arrondi selon l’implémentation. Les paramètres particulaires sont prioritaires sur les paramètres massiques.','simulation_params.h; params_io_base.cpp; cuda_classic_src_io_resident_0263.cu; patch 0291','src_mpcd_params_catalogue_0292_cuda.csv');
INSERT INTO "raw_params_inventory" VALUES('src_mpcd_params_inventory_snapshot_040926_x14ai.csv',80,'openBoundaryOutletForcedParticlesPerStep','params_canonical_field','Entrées/sorties — modes outlet','existant catalogue 0292','entier','0','>= 0; particules / step','openBoundaryOutletForcedParticlesPerStep','','Nombre cible de particules à extraire à chaque step dans la couche outlet.','Utilisé si openBoundaryOutletMode=forced_flux. Prioritaire sur openBoundaryOutletForcedParticleFlux et sur les paramètres massiques. 0 désactive l’extraction forcée si aucun autre flux positif n’est donné.','simulation_params.h; params_io_base.cpp; cuda_classic_src_io_resident_0263.cu; patch 0291','src_mpcd_params_catalogue_0292_cuda.csv');
INSERT INTO "raw_params_inventory" VALUES('src_mpcd_params_inventory_snapshot_040926_x14ai.csv',81,'openBoundaryOutletMode','params_canonical_field','Entrées/sorties — modes outlet','existant catalogue 0292 | sémantique Neumann mise à jour 0493x8r-x8t','enum string','balanced_flux historique Q6; utiliser explicitement neumann/equilibrium_flux/forced_flux pour SRC classic 0291+','SRC classic 0291+: neumann; equilibrium_flux; forced_flux. Q6/open-boundary historique: balanced_flux; prescribed_flux; balanced; prescribed; dirichlet; neumann; free; zero_gradient; zero_normal_gradient; hybrid; neumann_feedback; hybrid_feedback.','openBoundaryOutletMode','openOutletBoundaryMode; outletBoundaryMode; q6q9OutletBoundaryMode','Choisit le régime de sortie: sortie passive, extraction équilibrée ou extraction forcée utilisateur pour SRC classic; conserve aussi les politiques Q6 open-boundary historiques.','SRC classic CUDA 0291+: appliqué aux outlets full-face et segmentés. forced_flux est indépendant de l’inlet et nécessite un paramètre openBoundaryOutletForced* positif. equilibrium_flux tente une extraction équilibrante couplée au gain net du step. neumann laisse sortir passivement. Les modes Q6 historiques restent disponibles pour la projection open-boundary. | 0493x8r-x8t: neumann sur Q6-G-F est une sortie pression passive: vitesse prédicteur extrapolée à gradient normal nul, phi=0 à la face ouverte, correction finale de flux libre; le chemin particulaire reconstruit un bain cinétique local côté sortie.','simulation_params.h; params_io_base.cpp; cuda_classic_src_io_resident_0263.cu; patches 0291/0291b; src/cuda_q6_resident_0400.cu; src/cuda_classic_src_io_resident_0263.cu; apply_0493x8r_neumann_pressure_outlet.py; 0493x8q-x8t','src_mpcd_params_catalogue_0292_cuda.csv | cycle_0493x8k_x8t + 0493x9d_x9r_surface_tension_20260819');
INSERT INTO "raw_params_inventory" VALUES('src_mpcd_params_inventory_snapshot_040926_x14ai.csv',82,'inletVelocitySpatialProfile','params_canonical_field','Entrées/sorties — profil spatial','existant catalogue 0292 | étendu 0493x8k entrée segmentée locale','enum string','uniform','uniform; poiseuille_y; poiseuille_y_mean; poiseuille_y_max; flat_taper_y; flat_taper_y_mean','inletVelocitySpatialProfile','inletSpatialProfile; inletProfile; openBoundaryVelocityProfile','Profil spatial de vitesse/flux imposé sur les entrées.','Les tirets sont normalisés en underscores. | 0493x8k: pour une ouverture segmentée, poiseuille_y_max/poiseuille_y_mean sont évalués dans la coordonnée locale du segment; la vitesse normale est nulle aux extrémités et le même profil alimente injection particulaire et flux Q6-G-F.','simulation_params.h; params_io_base.cpp; src/cuda_classic_src_io_resident_0263.cu; src/cuda_q6_resident_0400.cu; scripts/run_0493x8k_segmented_local_poiseuille.sh','src_mpcd_params_catalogue_0292_cuda.csv | cycle_0493x8k_x8t + 0493x9d_x9r_surface_tension_20260819');
