INSERT INTO "raw_params_inventory" VALUES('src_mpcd_params_inventory_snapshot_040926_x14ai.csv',772,'speciesQ6Mode','params_key','Multi-espèces — projection Q6','ajout 0491; étendu 0493w5–0493w8 puis 0493x5a–0493x6g','enum string','common','common; weighted; independent_masked; free_surface_masked.','speciesQ6Mode','','Sélectionne l’opérateur Q6 multi-espèces / surface libre.','common/weighted conservent une projection barycentrique unique; independent_masked résout un problème masqué distinct par espèce. free_surface_masked (0493x5a+) projette le liquide sur un support de remplissage absolu; le chemin actuellement qualifié requiert q6ForceProjectionMode=prestream_single_fused, une boîte fermée statique et exactement une espèce projetée. x6f/x6g séparent ensuite interface alpha=0.5, carrier et valeur de pression interfaciale.','include/simulation_params.h; src/params_io_base.cpp; include/q6_species_distribution_0491a.h; src/q6_species_distribution_0491a.cpp; src/cuda_q6_resident_0400.cu; README_0493W5_INDEPENDENT_MASKED_Q6_STAGE1.md; README_0493W6_INDEPENDENT_MASKED_POSTAPPLY_DIAGNOSTIC.md; README_0493W7_INDEPENDENT_MASKED_Q6_MULTIBC.md; README_0493X5A_PARTIAL_LIQUID_FREE_SURFACE.md; README_0493X5B_LIQUID_GAS_FREE_SURFACE.md; README_0493X6F_PHASE_INTERFACE_STENCIL.md; README_0493X6G_PHASE_GAS_PRESSURE.md','delta params 0491–0493w8 / branche surf commit caa5b6b | mise à jour 0493x5a–0493x6g');
INSERT INTO "raw_params_inventory" VALUES('src_mpcd_params_inventory_snapshot_040926_x14ai.csv',773,'speciesQ6Mode','params_canonical_field','Multi-espèces — projection Q6','ajout 0491; étendu 0493w5–0493w8 puis 0493x5a–0493x6g','enum string','common','common; weighted; independent_masked; free_surface_masked.','speciesQ6Mode','','Sélectionne l’opérateur Q6 multi-espèces / surface libre.','common/weighted conservent une projection barycentrique unique; independent_masked résout un problème masqué distinct par espèce. free_surface_masked (0493x5a+) projette le liquide sur un support de remplissage absolu; le chemin actuellement qualifié requiert q6ForceProjectionMode=prestream_single_fused, une boîte fermée statique et exactement une espèce projetée. x6f/x6g séparent ensuite interface alpha=0.5, carrier et valeur de pression interfaciale.','include/simulation_params.h; src/params_io_base.cpp; include/q6_species_distribution_0491a.h; src/q6_species_distribution_0491a.cpp; src/cuda_q6_resident_0400.cu; README_0493W5_INDEPENDENT_MASKED_Q6_STAGE1.md; README_0493W6_INDEPENDENT_MASKED_POSTAPPLY_DIAGNOSTIC.md; README_0493W7_INDEPENDENT_MASKED_Q6_MULTIBC.md; README_0493X5A_PARTIAL_LIQUID_FREE_SURFACE.md; README_0493X5B_LIQUID_GAS_FREE_SURFACE.md; README_0493X6F_PHASE_INTERFACE_STENCIL.md; README_0493X6G_PHASE_GAS_PRESSURE.md','delta params 0491–0493w8 / branche surf commit caa5b6b | mise à jour 0493x5a–0493x6g');
