INSERT INTO "raw_params_inventory" VALUES('src_mpcd_params_inventory_snapshot_040926_x14ai.csv',782,'speciesQ6MinOccupancyFraction','params_key','Multi-espèces — projection Q6','ajout 0491; étendu 0493w5–w8 puis Q6-g-f jusqu’à 0493x7q','double','0.5','fini dans [0,1].','speciesQ6MinOccupancyFraction','','Seuil de support des modes Q6 masqués; sens dépend du mode.','independent_masked: seuil relatif d’espèce. free_surface_masked: seuil absolu liquide M_liq/M_ref. Le défaut canonique reste 0.5; le profil Q6-g-f final utilise 0.10. x7m distingue explicitement ce support numérique de l’interface alpha=0.5 et supprime l’interface fictive lorsqu’aucun gaz n’est enregistré.','include/simulation_params.h; src/params_io_base.cpp; include/q6_species_distribution_0491a.h; src/q6_species_distribution_0491a.cpp; src/cuda_q6_resident_0400.cu; README_0493W5_INDEPENDENT_MASKED_Q6_STAGE1.md; README_0493W6_INDEPENDENT_MASKED_POSTAPPLY_DIAGNOSTIC.md; README_0493W7_INDEPENDENT_MASKED_Q6_MULTIBC.md; README_0493X5A_PARTIAL_LIQUID_FREE_SURFACE.md; README_0493X6F_PHASE_INTERFACE_STENCIL.md','mise à jour 0493x5a–0493x7q / Q6-g-f');
