INSERT INTO "raw_params_inventory" VALUES('src_mpcd_params_inventory_snapshot_040926_x14ai.csv',812,'q6DensityRelaxationTime','params_key','Projection Q6-g-f / restauration de densité','ajout 0493x7d; entrée physique recommandée; qualifiée signed1/x7q','double','0.0','fini >=0; si >0, q6DensityRelaxationBeta doit être 0 et betaEffectif=dt/tau doit rester dans [0,1]','q6DensityRelaxationTime','densityRelaxationTime; densityRelaxationTau','Constante de temps physique tau_rho de restauration de densité; impose div(u_proj)=(rawFill-1)/tau_rho dans le bulk liquide.','Valeur de production qualifiée tau_rho=0.25. Avec le gate signé, la cible n’est appliquée qu’aux structures de défaut cohérentes; 0 désactive la restauration. Requiert CUDA Q6 actif; incompatible avec q6DensityRelaxationBeta>0.','include/simulation_params.h; src/params_io_base.cpp; src/cuda_q6_resident_0400.cu; scripts/src_mpcd_run_common_0434.sh; scripts/run_0493x7i_q6_g_f_physical_qualification.sh','mise à jour 0493x7c–0493x7q / Q6-g-f');
