INSERT INTO "raw_params_inventory" VALUES('src_mpcd_params_inventory_snapshot_040926_x14ai.csv',830,'surfaceTensionSigma','params_canonical_field','Q6-G-F — tension superficielle / interface','0493x9d actif; calibration mécanique x12yl + calibration dynamique séparée x12cal; utilisé JFM x12d','double fini >= 0','0.0','>=0; 0 = no-op exact','surfaceTensionSigma','q6GfSurfaceTensionSigma','Coefficient de tension superficielle utilisé dans le saut de Laplace p_A-p_B=sigma*kappa sur l’interface Q6-G-F.','0493x9d: saut de Laplace via phiGamma_cap=dt*sigma*kappa/rhoARef, sans force CSF/kick particulaire direct. État x12: distinguer strictement la calibration mécanique/statique x12yl (Young-Laplace apparié sigma>0/sigma=0 avec courbure mesurée) de la dispersion dynamique des ondes x12cal. Le script x12yl définit sigma_eff comme propriété mécanique scalaire; la dispersion capillaire n''est pas à replier automatiquement dans une renormalisation unique de sigma. Le benchmark JFM x12d écrit directement surfaceTensionSigma depuis SIGMA_ACTIVE.','include/simulation_params.h; src/params_io_base.cpp:555,1388-1392; src/cuda_q6_resident_0400.cu; scripts/analyze_0493x12yl_young_laplace_calibrator.py; scripts/run_0493x12cal_capillary_calibrator.sh; scripts/run_0493x12d_jfm524_measurement_case.sh','cycle_0493x8k_x8t + 0493x9d_x9r + 0493x10q_x11c_surface_tension_20260822 + snap_260826_code_audit_20260826');
INSERT INTO "raw_params_inventory" VALUES('src_mpcd_params_inventory_snapshot_040926_x14ai.csv',831,'surfaceTensionSigma','params_key','Q6-G-F — tension superficielle / interface','0493x9d actif; calibration mécanique x12yl + calibration dynamique séparée x12cal; utilisé JFM x12d','double fini >= 0','0.0','>=0; 0 = no-op exact','surfaceTensionSigma','','Coefficient de tension superficielle utilisé dans le saut de Laplace p_A-p_B=sigma*kappa sur l’interface Q6-G-F.','0493x9d: saut de Laplace via phiGamma_cap=dt*sigma*kappa/rhoARef, sans force CSF/kick particulaire direct. État x12: distinguer strictement la calibration mécanique/statique x12yl (Young-Laplace apparié sigma>0/sigma=0 avec courbure mesurée) de la dispersion dynamique des ondes x12cal. Le script x12yl définit sigma_eff comme propriété mécanique scalaire; la dispersion capillaire n''est pas à replier automatiquement dans une renormalisation unique de sigma. Le benchmark JFM x12d écrit directement surfaceTensionSigma depuis SIGMA_ACTIVE.','include/simulation_params.h; src/params_io_base.cpp:555,1388-1392; src/cuda_q6_resident_0400.cu; scripts/analyze_0493x12yl_young_laplace_calibrator.py; scripts/run_0493x12cal_capillary_calibrator.sh; scripts/run_0493x12d_jfm524_measurement_case.sh','cycle_0493x8k_x8t + 0493x9d_x9r + 0493x10q_x11c_surface_tension_20260822 + snap_260826_code_audit_20260826');
INSERT INTO "raw_params_inventory" VALUES('src_mpcd_params_inventory_snapshot_040926_x14ai.csv',832,'q6GfSurfaceTensionSigma','params_key','Q6-G-F — tension superficielle / interface','alias parser accepté de surfaceTensionSigma; actif','double fini >= 0','0.0','>=0; 0 = no-op exact','surfaceTensionSigma','','Coefficient de tension superficielle utilisé dans le saut de Laplace p_A-p_B=sigma*kappa sur l’interface Q6-G-F.','Alias parser exact. Même physique et mêmes distinctions x12yl (mécanique/statique) vs x12cal (dynamique) que surfaceTensionSigma.','src/params_io_base.cpp:555; include/simulation_params.h; src/cuda_q6_resident_0400.cu','cycle_0493x8k_x8t + 0493x9d_x9r_surface_tension_20260819 + snap_260826_code_audit_20260826');
INSERT INTO "raw_params_inventory" VALUES('src_mpcd_params_inventory_snapshot_040926_x14ai.csv',833,'surfaceTensionMinRadiusCells','params_canonical_field','Q6-G-F — tension superficielle / interface','0493x9r actif; choix de campagne x12 (JFM/x12yl=4, x12cal=3)','double fini >= 0','0.0','>=0; 0 = no-op; valeur numérique de résolution, non constante physique universelle','surfaceTensionMinRadiusCells','q6GfSurfaceTensionMinRadiusCells','Rayon minimal résolu en cellules pour la courbure utilisée uniquement dans sigma*kappa.','0493x9r: kappaLimit=1/(N_R*min(dx,dy)); le clip agit sur la courbure utilisée dans sigma*kappa, pas sur le champ brut. Le défaut struct reste 0.0. Il n''existe plus de ''choix 3'' universel: x12b/x12c/x12d JFM et x12yl utilisent 4 par défaut; x12cal dynamique et certains anciens runners splash x12a utilisent 3.','include/simulation_params.h; src/params_io_base.cpp:556,1393-1397; src/cuda_q6_resident_0400.cu; scripts/run_0493x12d_jfm524_measurement_case.sh:61; scripts/run_0493x12yl_young_laplace_calibrator.sh:60; scripts/run_0493x12cal_capillary_calibrator.sh:82','cycle_0493x8k_x8t + 0493x9d_x9r + 0493x10q_x11c_surface_tension_20260822 + snap_260826_code_audit_20260826');
INSERT INTO "raw_params_inventory" VALUES('src_mpcd_params_inventory_snapshot_040926_x14ai.csv',834,'surfaceTensionMinRadiusCells','params_key','Q6-G-F — tension superficielle / interface','0493x9r actif; choix de campagne x12 (JFM/x12yl=4, x12cal=3)','double fini >= 0','0.0','>=0; 0 = no-op; valeur numérique de résolution, non constante physique universelle','surfaceTensionMinRadiusCells','','Rayon minimal résolu en cellules pour la courbure utilisée uniquement dans sigma*kappa.','0493x9r: kappaLimit=1/(N_R*min(dx,dy)); le clip agit sur la courbure utilisée dans sigma*kappa, pas sur le champ brut. Le défaut struct reste 0.0. Il n''existe plus de ''choix 3'' universel: x12b/x12c/x12d JFM et x12yl utilisent 4 par défaut; x12cal dynamique et certains anciens runners splash x12a utilisent 3.','include/simulation_params.h; src/params_io_base.cpp:556,1393-1397; src/cuda_q6_resident_0400.cu; scripts/run_0493x12d_jfm524_measurement_case.sh:61; scripts/run_0493x12yl_young_laplace_calibrator.sh:60; scripts/run_0493x12cal_capillary_calibrator.sh:82','cycle_0493x8k_x8t + 0493x9d_x9r + 0493x10q_x11c_surface_tension_20260822 + snap_260826_code_audit_20260826');
INSERT INTO "raw_params_inventory" VALUES('src_mpcd_params_inventory_snapshot_040926_x14ai.csv',835,'q6GfSurfaceTensionMinRadiusCells','params_key','Q6-G-F — tension superficielle / interface','alias parser accepté; choix de campagne x12','double fini >= 0','0.0','>=0; 0 = no-op; recommandé actuel 3 pour les cas x9r','surfaceTensionMinRadiusCells','','Rayon minimal résolu en cellules pour la courbure utilisée uniquement dans sigma*kappa.','0493x9r: kappaLimit=1/(N_R*min(dx,dy)); le clip agit sur la courbure utilisée dans sigma*kappa, pas sur le champ brut. Le défaut struct reste 0.0. Il n''existe plus de ''choix 3'' universel: x12b/x12c/x12d JFM et x12yl utilisent 4 par défaut; x12cal dynamique et certains anciens runners splash x12a utilisent 3.','src/params_io_base.cpp:556; include/simulation_params.h; src/cuda_q6_resident_0400.cu','cycle_0493x8k_x8t + 0493x9d_x9r_surface_tension_20260819 + snap_260826_code_audit_20260826');
INSERT INTO "raw_params_inventory" VALUES('src_mpcd_params_inventory_snapshot_040926_x14ai.csv',836,'phaseInterfaceASelector','params_canonical_field','Q6-G-F — sélection de phases','0493x9g actif; x14k autorise paire liquide/gaz bilatérale sous gardes stricts','string canonique','family:liquid','family:liquid | family:gas | family:dispersed | family:unspecified | type:<uint32> | vacuum | wall; A ne peut pas être vacuum/wall; A/B ne doivent pas se recouvrir; en x14k bilatéral A doit être type:<id> et correspondre exactement à une espèce liquide projetée','phaseInterfaceASelector','capillaryPhaseASelector','Sélectionne la phase A: côté alpha>=0.5, référence de masse, orientation A->B et espèce(s) projetée(s).','Défaut struct family:liquid. Avec réflexion cinétique >0, la validation exige exactement une espèce A projetée. Les runners x12/JFM écrivent phaseInterfaceASelector=type:$LIQUID_TYPE. | 0493x14k: le mode bilatéral exige des sélecteurs explicites type:<id> pour A et B; A est le liquide projeté unique. | Audit x14ai-fix1 04/09/2026: sémantique params inchangée; aucune nouvelle clé params.kv introduite par x14y--x14ai-fix1.','include/simulation_params.h; src/params_io_base.cpp:559; src/params_io_base.cpp:1408-1432; scripts/run_0493x12d_jfm524_measurement_case.sh:331; snap_040926/include+src audit','cycle_0493x8k_x8t + 0493x9d_x9r + 0493x10q_x11c_surface_tension_20260822 + snap_260826_code_audit_20260826 | extension_x14_snapshot_030926 | audit_snap_040926_x14ai_fix1_20260904');
INSERT INTO "raw_params_inventory" VALUES('src_mpcd_params_inventory_snapshot_040926_x14ai.csv',837,'phaseInterfaceASelector','params_key','Q6-G-F — sélection de phases','0493x9g actif; x14k autorise paire liquide/gaz bilatérale sous gardes stricts','string canonique','family:liquid','family:liquid | family:gas | family:dispersed | family:unspecified | type:<uint32> | vacuum | wall; A ne peut pas être vacuum/wall; A/B ne doivent pas se recouvrir; en x14k bilatéral A doit être type:<id> et correspondre exactement à une espèce liquide projetée','phaseInterfaceASelector','','Sélectionne la phase A: côté alpha>=0.5, référence de masse, orientation A->B et espèce(s) projetée(s).','Défaut struct family:liquid. Avec réflexion cinétique >0, la validation exige exactement une espèce A projetée. Les runners x12/JFM écrivent phaseInterfaceASelector=type:$LIQUID_TYPE. | 0493x14k: le mode bilatéral exige des sélecteurs explicites type:<id> pour A et B; A est le liquide projeté unique. | Audit x14ai-fix1 04/09/2026: sémantique params inchangée; aucune nouvelle clé params.kv introduite par x14y--x14ai-fix1.','include/simulation_params.h; src/params_io_base.cpp:559; src/params_io_base.cpp:1408-1432; scripts/run_0493x12d_jfm524_measurement_case.sh:331; snap_040926/include+src audit','cycle_0493x8k_x8t + 0493x9d_x9r + 0493x10q_x11c_surface_tension_20260822 + snap_260826_code_audit_20260826 | extension_x14_snapshot_030926 | audit_snap_040926_x14ai_fix1_20260904');
INSERT INTO "raw_params_inventory" VALUES('src_mpcd_params_inventory_snapshot_040926_x14ai.csv',838,'capillaryPhaseASelector','params_key','Q6-G-F — sélection de phases','alias accepté | ajout 0493x9g','string canonique','family:liquid','family:liquid | family:gas | family:dispersed | family:unspecified | type:<uint32> | vacuum | wall; A ne peut pas être vacuum/wall; A/B ne doivent pas se recouvrir','phaseInterfaceASelector','','Sélectionne la phase A: côté alpha>=0.5, référence de masse, orientation A->B et espèce(s) projetée(s).','Alias de phaseInterfaceASelector. 0493x9g: phase A doit sélectionner des espèces enregistrées avec masse de référence positive.','include/simulation_params.h; src/params_io_base.cpp; src/cuda_q6_resident_0400.cu; 0493x9g_phase_pair_generalization_review.diff','cycle_0493x8k_x8t + 0493x9d_x9r_surface_tension_20260819');
INSERT INTO "raw_params_inventory" VALUES('src_mpcd_params_inventory_snapshot_040926_x14ai.csv',839,'phaseInterfaceBSelector','params_canonical_field','Q6-G-F — sélection de phases','0493x9g actif; x14k autorise B=type:gaz lorsque phaseInterfaceKineticBilateralRelocation=true','string canonique','family:gas','family:liquid | family:gas | family:dispersed | family:unspecified | type:<uint32> | vacuum | wall; A/B ne doivent pas se recouvrir; avec réflexion cinétique et bilateral=false B reste vacuum; avec bilateral=true B doit être type:<id>, espèce gaz unique non projetée','phaseInterfaceBSelector','capillaryPhaseBSelector','Sélectionne le côté extérieur B de l’interface; peut fournir la pression gaz x6g, être vacuum, ou demander le provider géométrique wall.','Défaut struct family:gas. La garde historique x9t B=vacuum reste vraie lorsque la réflexion cinétique est active et phaseInterfaceKineticBilateralRelocation=false. x14k lève explicitement cette restriction pour une espèce gaz B unique non projetée, avec r=1 et sélecteurs type:<id>. | Audit x14ai-fix1 04/09/2026: sémantique params inchangée; aucune nouvelle clé params.kv introduite par x14y--x14ai-fix1.','include/simulation_params.h; src/params_io_base.cpp:560-561,1408-1421; scripts/run_0493x12d_jfm524_measurement_case.sh:332; snap_040926/include+src audit','cycle_0493x8k_x8t + 0493x9d_x9r + 0493x10q_x11c_surface_tension_20260822 + snap_260826_code_audit_20260826 | extension_x14_snapshot_030926 | audit_snap_040926_x14ai_fix1_20260904');
INSERT INTO "raw_params_inventory" VALUES('src_mpcd_params_inventory_snapshot_040926_x14ai.csv',840,'phaseInterfaceBSelector','params_key','Q6-G-F — sélection de phases','0493x9g actif; x14k autorise B=type:gaz lorsque phaseInterfaceKineticBilateralRelocation=true','string canonique','family:gas','family:liquid | family:gas | family:dispersed | family:unspecified | type:<uint32> | vacuum | wall; A/B ne doivent pas se recouvrir; avec réflexion cinétique et bilateral=false B reste vacuum; avec bilateral=true B doit être type:<id>, espèce gaz unique non projetée','phaseInterfaceBSelector','','Sélectionne le côté extérieur B de l’interface; peut fournir la pression gaz x6g, être vacuum, ou demander le provider géométrique wall.','Défaut struct family:gas. La garde historique x9t B=vacuum reste vraie lorsque la réflexion cinétique est active et phaseInterfaceKineticBilateralRelocation=false. x14k lève explicitement cette restriction pour une espèce gaz B unique non projetée, avec r=1 et sélecteurs type:<id>. | Audit x14ai-fix1 04/09/2026: sémantique params inchangée; aucune nouvelle clé params.kv introduite par x14y--x14ai-fix1.','include/simulation_params.h; src/params_io_base.cpp:560-561,1408-1421; scripts/run_0493x12d_jfm524_measurement_case.sh:332; snap_040926/include+src audit','cycle_0493x8k_x8t + 0493x9d_x9r + 0493x10q_x11c_surface_tension_20260822 + snap_260826_code_audit_20260826 | extension_x14_snapshot_030926 | audit_snap_040926_x14ai_fix1_20260904');
INSERT INTO "raw_params_inventory" VALUES('src_mpcd_params_inventory_snapshot_040926_x14ai.csv',841,'capillaryPhaseBSelector','params_key','Q6-G-F — sélection de phases','alias accepté | ajout 0493x9g; wall opérationnel géométriquement x9h','string canonique','family:gas','family:liquid | family:gas | family:dispersed | family:unspecified | type:<uint32> | vacuum | wall; A ne peut pas être vacuum/wall; A/B ne doivent pas se recouvrir','phaseInterfaceBSelector','','Sélectionne le côté extérieur B de l’interface; peut fournir la pression gaz x6g, être vacuum, ou demander le provider géométrique wall.','Alias de phaseInterfaceBSelector. 0493x9g/x9h: B=vacuum est opérationnel sans particules gaz. B=wall est géométrie seule et ne doit pas être utilisé comme paire capillaire de mouillage; le mur est alors un troisième objet.','include/simulation_params.h; src/params_io_base.cpp; src/cuda_q6_resident_0400.cu; 0493x9g_phase_pair_generalization_review.diff; 0493x9h_wall_geometry_provider_review.diff','cycle_0493x8k_x8t + 0493x9d_x9r_surface_tension_20260819');
INSERT INTO "raw_params_inventory" VALUES('src_mpcd_params_inventory_snapshot_040926_x14ai.csv',842,'phaseInterfaceContactAngleDegrees','params_canonical_field','Q6-G-F — mouillage','0493x9i/x9m actif; x12 splash/JFM=90°, calibrateurs capillaires=-1','double fini','-1.0','-1 désactive; sinon [0,180] degrés; x9m qualifié seulement pour 0<theta<180','phaseInterfaceContactAngleDegrees','contactAngleDegrees; capillaryContactAngleDegrees','Prescrit l’angle de contact mesuré à travers A, avec nAB·nWall=-cos(thetaA).','Défaut struct -1 (désactivé). Les splash/JFM x12 utilisent 90° avec x9m off-support; x12cal et x12yl désactivent le mouillage pour les calibrations capillaires.','include/simulation_params.h; src/params_io_base.cpp; scripts/run_0493x12d_jfm524_measurement_case.sh:62,333; scripts/run_0493x12cal_capillary_calibrator.sh:297; scripts/run_0493x12yl_young_laplace_calibrator.sh:220','cycle_0493x8k_x8t + 0493x9d_x9r + 0493x10q_x11c_surface_tension_20260822 + snap_260826_code_audit_20260826');
INSERT INTO "raw_params_inventory" VALUES('src_mpcd_params_inventory_snapshot_040926_x14ai.csv',843,'phaseInterfaceContactAngleDegrees','params_key','Q6-G-F — mouillage','0493x9i/x9m actif; x12 splash/JFM=90°, calibrateurs capillaires=-1','double fini','-1.0','-1 désactive; sinon [0,180] degrés; x9m qualifié seulement pour 0<theta<180','phaseInterfaceContactAngleDegrees','','Prescrit l’angle de contact mesuré à travers A, avec nAB·nWall=-cos(thetaA).','Défaut struct -1 (désactivé). Les splash/JFM x12 utilisent 90° avec x9m off-support; x12cal et x12yl désactivent le mouillage pour les calibrations capillaires.','include/simulation_params.h; src/params_io_base.cpp; scripts/run_0493x12d_jfm524_measurement_case.sh:62,333; scripts/run_0493x12cal_capillary_calibrator.sh:297; scripts/run_0493x12yl_young_laplace_calibrator.sh:220','cycle_0493x8k_x8t + 0493x9d_x9r + 0493x10q_x11c_surface_tension_20260822 + snap_260826_code_audit_20260826');
INSERT INTO "raw_params_inventory" VALUES('src_mpcd_params_inventory_snapshot_040926_x14ai.csv',844,'contactAngleDegrees','params_key','Q6-G-F — mouillage','alias accepté | ajout 0493x9i; fermeture statique x9m qualifiée','double fini','-1.0','-1 désactive; sinon [0,180] degrés; x9m qualifié seulement pour 0<theta<180','phaseInterfaceContactAngleDegrees','','Prescrit l’angle de contact mesuré à travers A, avec nAB·nWall=-cos(thetaA).','Alias de phaseInterfaceContactAngleDegrees. x9i introduit le contrat. x9m est la fermeture statique préférée actuelle via ancre hors support; dynamique de ligne triple non encore quantitativement qualifiée. La garde actuelle exige surfaceTensionSigma>0 lorsqu’un angle est actif.','include/simulation_params.h; src/params_io_base.cpp; src/cuda_q6_resident_0400.cu; README_0493X9I_CONTACT_ANGLE.md; 0493x9m_offsupport_anchor_review.diff','cycle_0493x8k_x8t + 0493x9d_x9r_surface_tension_20260819');
INSERT INTO "raw_params_inventory" VALUES('src_mpcd_params_inventory_snapshot_040926_x14ai.csv',845,'capillaryContactAngleDegrees','params_key','Q6-G-F — mouillage','alias accepté | ajout 0493x9i; fermeture statique x9m qualifiée','double fini','-1.0','-1 désactive; sinon [0,180] degrés; x9m qualifié seulement pour 0<theta<180','phaseInterfaceContactAngleDegrees','','Prescrit l’angle de contact mesuré à travers A, avec nAB·nWall=-cos(thetaA).','Alias de phaseInterfaceContactAngleDegrees. x9i introduit le contrat. x9m est la fermeture statique préférée actuelle via ancre hors support; dynamique de ligne triple non encore quantitativement qualifiée. La garde actuelle exige surfaceTensionSigma>0 lorsqu’un angle est actif.','include/simulation_params.h; src/params_io_base.cpp; src/cuda_q6_resident_0400.cu; README_0493X9I_CONTACT_ANGLE.md; 0493x9m_offsupport_anchor_review.diff','cycle_0493x8k_x8t + 0493x9d_x9r_surface_tension_20260819');
INSERT INTO "raw_params_inventory" VALUES('src_mpcd_params_inventory_snapshot_040926_x14ai.csv',846,'phaseInterfaceKineticReflectionFraction','params_canonical_field','Q6-G-F — interface cinétique / évaporation','0493x9t actif; production x12 r=1; x14k bilatéral liquide/gaz exige r=1','double fini','0.0 (SimulationParams); runners x12 production fixent 1.0','[0,1]; si >0: speciesQ6Enable, speciesQ6Mode=free_surface_masked, q6ForceProjectionMode=prestream_single_fused, exactement une espèce A projetée; B=vacuum sauf si phaseInterfaceKineticBilateralRelocation=true; en bilatéral r doit valoir 1','phaseInterfaceKineticReflectionFraction','kineticReflectionFraction (alias parser); KINETIC_REFLECTION_FRACTION (alias runner)','Probabilité de réfléchir une tentative de franchissement sortante relative g=(v-uGamma)·n>0; 1-r ouvre la voie de transmission/évaporation.','Correction importante: le défaut du struct est 0.0, pas 1.0. x10o et la chaîne CIC/Q2/x10u/x10v/x12a ne deviennent actifs que dans le chemin cinétique Q6 free_surface_masked; x10o exige en plus r>=1. La production x12 verrouille r=1. | Audit commit 7655b81: alias parser présent et couvert; aucune clé canonique supplémentaire requise. | 0493x14k: B explicite gaz est autorisé uniquement via le gate bilatéral; ce chemin impose r=1 et interdit une cible d’évaporation active. | Audit x14ai-fix1 04/09/2026: sémantique params inchangée; aucune nouvelle clé params.kv introduite par x14y--x14ai-fix1.','include/simulation_params.h:493; src/params_io_base.cpp:557,1398-1435; src/cuda_q6_resident_0400.cu:17728-17918,22329-22345; scripts/run_0493x12d_jfm524_measurement_case.sh:63,329 | include/simulation_params.h; src/params_io_base.cpp; snap_040926/include+src audit','cycle_0493x8k_x8t + 0493x9d_x9r + 0493x10q_x11c_surface_tension_20260822 + snap_260826_code_audit_20260826 | audit_commit_7655b81_20260831 | extension_x14_snapshot_030926 | audit_snap_040926_x14ai_fix1_20260904');
INSERT INTO "raw_params_inventory" VALUES('src_mpcd_params_inventory_snapshot_040926_x14ai.csv',847,'phaseInterfaceKineticReflectionFraction','params_key','Q6-G-F — interface cinétique / évaporation','0493x9t actif; production x12 r=1; x14k bilatéral liquide/gaz exige r=1','double fini','0.0 (SimulationParams); runners x12 production fixent 1.0','[0,1]; si >0: speciesQ6Enable, speciesQ6Mode=free_surface_masked, q6ForceProjectionMode=prestream_single_fused, exactement une espèce A projetée; B=vacuum sauf si phaseInterfaceKineticBilateralRelocation=true; en bilatéral r doit valoir 1','phaseInterfaceKineticReflectionFraction','kineticReflectionFraction (alias parser); KINETIC_REFLECTION_FRACTION (alias runner)','Probabilité de réfléchir une tentative de franchissement sortante relative g=(v-uGamma)·n>0; 1-r ouvre la voie de transmission/évaporation.','Correction importante: le défaut du struct est 0.0, pas 1.0. x10o et la chaîne CIC/Q2/x10u/x10v/x12a ne deviennent actifs que dans le chemin cinétique Q6 free_surface_masked; x10o exige en plus r>=1. La production x12 verrouille r=1. | Audit commit 7655b81: aliases parser kineticReflectionFraction/evaporationTargetType présents et couverts; aucune clé canonique supplémentaire requise. | Audit commit 7655b81: alias parser présent et couvert; aucune clé canonique supplémentaire requise. | 0493x14k: B explicite gaz est autorisé uniquement via le gate bilatéral; ce chemin impose r=1 et interdit une cible d’évaporation active. | Audit x14ai-fix1 04/09/2026: sémantique params inchangée; aucune nouvelle clé params.kv introduite par x14y--x14ai-fix1.','include/simulation_params.h:493; src/params_io_base.cpp:557,1398-1435; src/cuda_q6_resident_0400.cu:17728-17918,22329-22345; scripts/run_0493x12d_jfm524_measurement_case.sh:63,329 | include/simulation_params.h; src/params_io_base.cpp; snap_040926/include+src audit','cycle_0493x8k_x8t + 0493x9d_x9r + 0493x10q_x11c_surface_tension_20260822 + snap_260826_code_audit_20260826 | audit_commit_7655b81_20260831 | extension_x14_snapshot_030926 | audit_snap_040926_x14ai_fix1_20260904');
INSERT INTO "raw_params_inventory" VALUES('src_mpcd_params_inventory_snapshot_040926_x14ai.csv',848,'phaseInterfaceEvaporationTargetType','params_canonical_field','Q6-G-F — interface cinétique / évaporation','0493x9t actif; production x12=-1; transfert r<1 non qualifié thermodynamiquement','entier / identifiant de type particulaire','-1 (SimulationParams et runners x12)','>=-1; si >=0 avec réflexion active: type enregistré, non projeté et distinct de A; incompatible avec phaseInterfaceKineticBilateralRelocation=true','phaseInterfaceEvaporationTargetType','evaporationTargetType (alias parser); EVAPORATION_TARGET_TYPE (alias runner)','Type cible optionnel associé aux particules transmises par la loi cinétique lorsque r<1.','Avec r=1 dans la chaîne x12, ce paramètre n''entraîne aucun changement de phase. Le chemin >=0 appartient au mécanisme historique r<1 et ne constitue pas une loi d''évaporation/condensation thermodynamiquement qualifiée. | Audit commit 7655b81: alias parser présent et couvert; aucune clé canonique supplémentaire requise. | 0493x14k: le couplage bilatéral liquide/gaz courant interdit phaseInterfaceEvaporationTargetType>=0.','include/simulation_params.h:494; src/params_io_base.cpp:558,1404-1454; scripts/run_0493x12d_jfm524_measurement_case.sh:64,330','cycle_0493x8k_x8t + 0493x9d_x9r + 0493x10q_x11c_surface_tension_20260822 + snap_260826_code_audit_20260826 | audit_commit_7655b81_20260831 | extension_x14_snapshot_030926');
INSERT INTO "raw_params_inventory" VALUES('src_mpcd_params_inventory_snapshot_040926_x14ai.csv',849,'phaseInterfaceEvaporationTargetType','params_key','Q6-G-F — interface cinétique / évaporation','0493x9t actif; production x12=-1; transfert r<1 non qualifié thermodynamiquement','entier / identifiant de type particulaire','-1 (SimulationParams et runners x12)','>=-1; si >=0 avec réflexion active: type enregistré, non projeté et distinct de A; incompatible avec phaseInterfaceKineticBilateralRelocation=true','phaseInterfaceEvaporationTargetType','evaporationTargetType (alias parser); EVAPORATION_TARGET_TYPE (alias runner)','Type cible optionnel associé aux particules transmises par la loi cinétique lorsque r<1.','Avec r=1 dans la chaîne x12, ce paramètre n''entraîne aucun changement de phase. Le chemin >=0 appartient au mécanisme historique r<1 et ne constitue pas une loi d''évaporation/condensation thermodynamiquement qualifiée. | Audit commit 7655b81: aliases parser kineticReflectionFraction/evaporationTargetType présents et couverts; aucune clé canonique supplémentaire requise. | Audit commit 7655b81: alias parser présent et couvert; aucune clé canonique supplémentaire requise. | 0493x14k: le couplage bilatéral liquide/gaz courant interdit phaseInterfaceEvaporationTargetType>=0.','include/simulation_params.h:494; src/params_io_base.cpp:558,1404-1454; scripts/run_0493x12d_jfm524_measurement_case.sh:64,330','cycle_0493x8k_x8t + 0493x9d_x9r + 0493x10q_x11c_surface_tension_20260822 + snap_260826_code_audit_20260826 | audit_commit_7655b81_20260831 | extension_x14_snapshot_030926');
INSERT INTO "raw_params_inventory" VALUES('src_mpcd_params_inventory_snapshot_040926_x14ai.csv',850,'speciesThermostatEnable','params_key','Thermostat — multi-espèces x14','ajout 0493x14a; actif dans la chaîne liquide/gaz x14','booléen','false','true requiert thermostatEnable=true, registre d’espèces non vide, speciesRequireRegisteredTypes=true et une cible kBT positive finie résolue pour chaque espèce','speciesThermostatEnable','','Conserve la collision SRC commune au mélange mais applique ensuite une remise à température séparée par type enregistré.','Opt-in; false préserve le chemin thermostat all-fluid historique. En CUDA résident, le workspace cellulaire est réutilisé successivement par espèce. | Audit x14ai-fix1 04/09/2026: sémantique params inchangée; aucune nouvelle clé params.kv introduite par x14y--x14ai-fix1.','include/simulation_params.h; src/params_io_base.cpp; src/src_collision.cpp; src/thermostat.cpp; src/cuda_q6_resident_0400.cu; snap_040926/include+src audit','extension_x14_snapshot_030926 | audit_snap_040926_x14ai_fix1_20260904');
INSERT INTO "raw_params_inventory" VALUES('src_mpcd_params_inventory_snapshot_040926_x14ai.csv',851,'speciesThermostatEnable','params_canonical_field','Thermostat — multi-espèces x14','ajout 0493x14a; actif dans la chaîne liquide/gaz x14','booléen','false','mêmes gardes que la clé params','speciesThermostatEnable','','Champ SimulationParams activant le thermostat séparé par espèce.','Défaut false pour non-régression. | Audit x14ai-fix1 04/09/2026: sémantique params inchangée; aucune nouvelle clé params.kv introduite par x14y--x14ai-fix1.','include/simulation_params.h; src/params_io_base.cpp; snap_040926/include+src audit','extension_x14_snapshot_030926 | audit_snap_040926_x14ai_fix1_20260904');
INSERT INTO "raw_params_inventory" VALUES('src_mpcd_params_inventory_snapshot_040926_x14ai.csv',852,'speciesKThermostatTargetKBT','params_key_pattern','Thermostat — multi-espèces x14','ajout 0493x14a; famille dynamique K=0…speciesCount-1','double','négatif => hérite de thermostatTargetKBT puis kBT','K entier dans [0,speciesCount-1]; valeur résolue finie >0 lorsque speciesThermostatEnable=true; 0 invalide','speciesDefinitions[K].thermostatTargetKBT','species0ThermostatTargetKBT … speciesN-1ThermostatTargetKBT','Cible thermique propre à l’espèce K.','Clé dynamique détectée par parse_species_thermostat_target_key; ne fait pas partie du décompte des clés littérales directes du parseur. | Audit x14ai-fix1 04/09/2026: sémantique params inchangée; aucune nouvelle clé params.kv introduite par x14y--x14ai-fix1.','include/simulation_params.h; include/species_registry.h; src/params_io_base.cpp; snap_040926/include+src audit','extension_x14_snapshot_030926 | audit_snap_040926_x14ai_fix1_20260904');
INSERT INTO "raw_params_inventory" VALUES('src_mpcd_params_inventory_snapshot_040926_x14ai.csv',853,'speciesKResamplingEnable','params_key_pattern','Multi-espèces — registre','famille dynamique existante, explicitée dans l’inventaire x14','booléen','true pour chaque déclaration','K entier dans [0,speciesCount-1]','speciesDefinitions[K].resamplingEnable','species0ResamplingEnable … speciesN-1ResamplingEnable','Active/désactive le resampling pour l’espèce K.','Famille dynamique déjà documentée dans le commentaire de SimulationParams mais auparavant seulement implicite dans la ligne speciesK.','include/simulation_params.h; src/params_io_base.cpp','extension_x14_snapshot_030926');
INSERT INTO "raw_params_inventory" VALUES('src_mpcd_params_inventory_snapshot_040926_x14ai.csv',854,'phaseInterfaceKineticBilateralRelocation','params_key','Q6-G-F — interface cinétique liquide/gaz x14','ajout 0493x14k; actif dans la chaîne liquide/gaz x14','booléen','false','si true: r=1; phaseInterfaceEvaporationTargetType<0; A et B explicites type:<id>; A=espèce liquide projetée unique; B=espèce gaz unique non projetée','phaseInterfaceKineticBilateralRelocation','','Étend la relocalisation positionnelle x10u à une paire liquide/gaz explicite avec sens de phase inversé pour B.','Ne modifie à lui seul ni vitesse, ni masse, ni type. false conserve exactement la garde liquide/vide historique. | Audit x14ai-fix1 04/09/2026: sémantique params inchangée; aucune nouvelle clé params.kv introduite par x14y--x14ai-fix1.','include/simulation_params.h; src/params_io_base.cpp; src/cuda_q6_resident_0400.cu; snap_040926/include+src audit','extension_x14_snapshot_030926 | audit_snap_040926_x14ai_fix1_20260904');
