INSERT INTO "search_fts" VALUES('symbol:env:BIN','SYMBOL','BIN BIN','ENV Alias script / binaire mis à jour 0337 livevis chemin exécutable build/src_mpcd_base_cuda_q6_resident_livevis_0486 dans les runners 0493w4–0493w8 Binaire exécuté par les scripts portables livevis. Peut être surchargé; independent_masked requiert le binaire CUDA Q6 résident 0486 ou un build équivalent.');
INSERT INTO "search_fts" VALUES('symbol:env:AUTO_BUILD','SYMBOL','AUTO_BUILD AUTO_BUILD','ENV Alias script / build mis à jour 0337 livevis booléen 1 Autorise le script à compiler automatiquement le binaire manquant. Dans les scripts livevis, le build automatique passe MPCD_ENABLE_LIVE_VIS=1.');
INSERT INTO "search_fts" VALUES('symbol:env:RUN_MODES','SYMBOL','RUN_MODES RUN_MODES','ENV Alias script / cas de run existant; utilisé scripts portables liste de modes: src; src-q6; src-resampling; src-q6-resampling dépend du runner; src src-q6 pour les comparaisons injection/TG Choisit les branches d’ablation SRC, Q6 et resampling exécutées par les runners. 0493w4–0493w8: Q6 et resampling restent deux axes indépendants; la qualification Q6 initiale garde le resampling désactivé.');
