INSERT INTO "search_fts" VALUES('symbol:env:LIVE_VIS_QUIVER_NX','SYMBOL','LIVE_VIS_QUIVER_NX LIVE_VIS_QUIVER_NX','ENV Alias script livevis quiver ajout 0364 entier >= 1 60 Alias script exportable vers SRC_LIVE_VIS_QUIVER_NX. ');
INSERT INTO "search_fts" VALUES('symbol:env:LIVE_VIS_QUIVER_NY','SYMBOL','LIVE_VIS_QUIVER_NY LIVE_VIS_QUIVER_NY','ENV Alias script livevis quiver ajout 0364 entier >= 1 32 Alias script exportable vers SRC_LIVE_VIS_QUIVER_NY. ');
INSERT INTO "search_fts" VALUES('symbol:env:LIVE_VIS_QUIVER_SCALE','SYMBOL','LIVE_VIS_QUIVER_SCALE LIVE_VIS_QUIVER_SCALE','ENV Alias script livevis quiver ajout 0364 double -1 Alias script exportable vers SRC_LIVE_VIS_QUIVER_SCALE. <0 désactive l’overlay.');
INSERT INTO "search_fts" VALUES('symbol:env:LIVE_VIS_QUIVER_SMOOTH_PASSES','SYMBOL','LIVE_VIS_QUIVER_SMOOTH_PASSES LIVE_VIS_QUIVER_SMOOTH_PASSES','ENV Alias script livevis quiver ajout 0365 entier; -1 ou >=0 -1 Alias script exportable vers SRC_LIVE_VIS_QUIVER_SMOOTH_PASSES. <0 réutilise smoothPasses.');
INSERT INTO "search_fts" VALUES('symbol:env:LIVE_VIS_CONTROL_BASENAME','SYMBOL','LIVE_VIS_CONTROL_BASENAME LIVE_VIS_CONTROL_BASENAME','ENV Alias script livevis runtime control ajout 0341d nom de fichier livevis_control.kv Nom du fichier utilisé avec LIVE_VIS_CONTROL_DIR ou, par défaut, dans le run_root. Permet de distinguer plusieurs contrôles, par exemple vk_io.kv, tg_hole.kv, poiseuille.kv.');
INSERT INTO "search_fts" VALUES('symbol:env:LIVE_VIS_CONTROL_DIR','SYMBOL','LIVE_VIS_CONTROL_DIR LIVE_VIS_CONTROL_DIR','ENV Alias script livevis runtime control ajout 0341d chemin répertoire vide Répertoire dans lequel créer le fichier de contrôle lorsque LIVE_VIS_CONTROL_FILE est vide. Combiné avec LIVE_VIS_CONTROL_BASENAME. Exemple: LIVE_VIS_CONTROL_DIR=. LIVE_VIS_CONTROL_BASENAME=livevis_control.kv.');
INSERT INTO "search_fts" VALUES('symbol:env:LIVE_VIS_CONTROL_ENABLE','SYMBOL','LIVE_VIS_CONTROL_ENABLE LIVE_VIS_CONTROL_ENABLE','ENV Alias script livevis runtime control ajout 0341b; export explicite 0341c booléen shell 1 Active la création/export du fichier de contrôle livevis dans les scripts portables. À 0, aucun fichier de contrôle n’est préparé et SRC_LIVE_VIS_CONTROL_FILE peut rester vide.');
INSERT INTO "search_fts" VALUES('symbol:env:LIVE_VIS_CONTROL_EVERY','SYMBOL','LIVE_VIS_CONTROL_EVERY LIVE_VIS_CONTROL_EVERY','ENV Alias script livevis runtime control ajout 0341b; export explicite 0341c entier >= 1 1 Valeur script exportée en SRC_LIVE_VIS_CONTROL_EVERY. Contrôle la fréquence de relecture côté binaire.');
INSERT INTO "search_fts" VALUES('symbol:env:LIVE_VIS_CONTROL_FILE','SYMBOL','LIVE_VIS_CONTROL_FILE LIVE_VIS_CONTROL_FILE','ENV Alias script livevis runtime control ajout 0341b; clarifié 0341d chemin fichier .kv vide Chemin explicite du fichier de contrôle livevis. Prioritaire sur LIVE_VIS_CONTROL_DIR et le chemin par défaut run_root. Utiliser ce paramètre, et non LIVE_VIS_CONTROL_FILE_EFFECTIVE, pour imposer un fichier tel que ./livevis_control.kv. Recommandé si CLEAN_RUN_ROOT=1 et que l’on veut un fichier persistant hors run_root.');
INSERT INTO "search_fts" VALUES('symbol:env:LIVE_VIS_CONTROL_LOG','SYMBOL','LIVE_VIS_CONTROL_LOG LIVE_VIS_CONTROL_LOG','ENV Alias script livevis runtime control ajout 0341b; export explicite 0341c booléen shell 1 Valeur script exportée en SRC_LIVE_VIS_CONTROL_LOG. Les logs livevis sont dans le .time car le stderr du binaire y est redirigé par le script.');
INSERT INTO "search_fts" VALUES('symbol:env:LIVE_VIS_CONTROL_FILE_EFFECTIVE','SYMBOL','LIVE_VIS_CONTROL_FILE_EFFECTIVE LIVE_VIS_CONTROL_FILE_EFFECTIVE','ENV Alias script livevis runtime control interne ajout 0341b; export explicite 0341c; clarifié 0341d chemin fichier .kv résolu résolu automatiquement Chemin effectivement transmis au binaire via SRC_LIVE_VIS_CONTROL_FILE. Variable interne/résolue: ne pas la fixer manuellement. Ordre de résolution 0341d: LIVE_VIS_CONTROL_FILE, sinon LIVE_VIS_CONTROL_DIR+LIVE_VIS_CONTROL_BASENAME, sinon run_root/LIVE_VIS_CONTROL_BASENAME.');
INSERT INTO "search_fts" VALUES('symbol:env:INACTIVE_SLOTS_RESAMPLING','SYMBOL','INACTIVE_SLOTS_RESAMPLING INACTIVE_SLOTS_RESAMPLING','ENV Alias script livevis/benchmark confirmé 0337 entier 750000 pour certains scripts Nombre de slots inactifs pour les cas resampling. N’affecte pas le SRC classic si RUN_MODES=classic; utile pour réservoir resampling.');
INSERT INTO "search_fts" VALUES('symbol:env:INACTIVE_SLOTS','SYMBOL','INACTIVE_SLOTS INACTIVE_SLOTS INACTIVE_SLOTS','ENV Capacité particulaire | CUDA resampling post-SRC — diagnostics, split-safety et optimisation inactive consolidé 0311-0312 | script/demo/audit entier | alias script utilisateur 50k-120k selon cas; pas de défaut universel | selon script; éviter les millions Nombre de slots Inactive préalloués par les générateurs/scripts. | Nombre de slots Inactive préalloués dans les scripts et audits. La réserve peut être grande sans être écrite dans les dumps si dumpRoleFilter=fluid. | N’est pas une clé params.kv directe universelle; transmis par les générateurs d’état/scripts.');
INSERT INTO "search_fts" VALUES('symbol:param:dumpRoleFilter','SYMBOL','dumpRoleFilter dumpParticleRoleFilter dumpRoleFilter','PARAM Dumps et post-traitement | Sorties compactes — aliases rôle ajout 0314 | alias accepté; complété inventaire 0490p all|fluid | chaîne all dans le cœur; fluid dans scripts visuels | all Contrôle si les dumps .smpcd écrivent tous les slots ou seulement les particules Fluid. | Alias de dumpRoleFilter. fluid accélère visualisation/post-traitement mais ne doit pas être utilisé pour un restart complet. | Ligne ajoutée par comparaison exhaustive du parseur params.kv au commit 36abd23 avec l’inventaire consolidé 0436b.');
INSERT INTO "search_fts" VALUES('symbol:param:summaryRoleFilter','SYMBOL','summaryRoleFilter summaryParticleRoleFilter summaryRoleFilter','PARAM Summaries runtime | Sorties compactes — aliases rôle ajout 0314 | alias accepté; complété inventaire 0490p all|fluid | chaîne all dans le cœur; fluid dans scripts visuels | all Contrôle si les summaries parcourent tous les slots ou un état compact fluide. | Alias de summaryRoleFilter. fluid réduit le coût lorsque INACTIVE_SLOTS est grand. | Ligne ajoutée par comparaison exhaustive du parseur params.kv au commit 36abd23 avec l’inventaire consolidé 0436b.');
INSERT INTO "search_fts" VALUES('symbol:param:srcClassicCudaModeEnable','SYMBOL','srcClassicCudaModeEnable classicSrcCudaMode classicSrcCudaMode classicSrcCudaModeEnable classicSrcCudaModeEnable classicSrcModeEnable classicSrcModeEnable srcClassicCudaModeEnable srcClassicCudaModeEnable','PARAM CUDA — mode SRC classic existant catalogue 0292 | alias accepté | alias accepté | alias accepté | canonique booléen false Sélecteur .kv du chemin SRC/MPCD classic, séparé de la fermeture liquide. | Active le mode SRC classic complet; en CUDA 0286, le chemin classic full CUDA est la voie principale validée. | Active le mode SRC classic complet; en CUDA 0286, le chemin classic full CUDA est la voie principale validée. | Active le mode SRC classic complet; en CUDA 0286, le chemin classic full CUDA est la voie principale validée. | Active le mode SRC classic complet; en CUDA 0286, le chemin classic full CUDA est la voie principale validée. Force le mode SRC classic complet: advection/streaming + shift + collision/rotation + thermostat. Court-circuite les fermetures Q6/resampling/viriel dans le driver; à utiliser pour les démos/validations classic CUDA 0275–0286.');
INSERT INTO "search_fts" VALUES('symbol:param:bcBottom','SYMBOL','bcBottom bcBottom bcBottom boundaryBottom boundaryBottom','PARAM Conditions limites existant catalogue 0292 | canonique | alias accepté enum string periodic Mode de condition limite sur la face basse. Les périodiques doivent être appariés bas/haut.');
