INSERT INTO "search_fts" VALUES('symbol:param:inletSlabCells','SYMBOL','inletSlabCells inletInjectionSlabCells inletInjectionSlabCells inletSlabCells inletSlabCells','PARAM Entrées/sorties — injection existant catalogue 0292 | alias accepté | canonique double 1.0 Épaisseur de la dalle d’injection en nombre de cellules locales. Utilisé dans les modes de recyclage/injection en slab.');
