INSERT INTO "search_fts" VALUES('symbol:env:MPCD_CUDA_ACTIVE_PREFIX_EAGER_HOST_MIRROR_0315D','SYMBOL','MPCD_CUDA_ACTIVE_PREFIX_EAGER_HOST_MIRROR_0315D MPCD_CUDA_ACTIVE_PREFIX_EAGER_HOST_MIRROR_0315D','ENV CUDA état résident / active-prefix — audit et compatibilité présent état 36abd23; inventorié 0490p (0315d) booléen/env truthy false/off Force une synchronisation ou un miroir hôte complet, principalement pour compatibilité et audit. À passer dans l’environnement du shell, pas dans params.kv. Ligne ajoutée par comparaison exhaustive des appels getenv du code courant avec l’inventaire 0436b.');
