INSERT INTO "search_fts" VALUES('symbol:env:SRC_LIVE_VIS_VSYNC','SYMBOL','SRC_LIVE_VIS_VSYNC SRC_LIVE_VIS_VSYNC','ENV Live visualization runtime ajout 0335 booléen/int 0 scripts 0337 Contrôle vsync de la fenêtre GLFW. 0 recommandé pour ne pas brider la simulation; 1 utile si affichage trop rapide.');
