INSERT INTO "search_fts" VALUES('symbol:env:VACUUM_BACKGROUND','SYMBOL','VACUUM_BACKGROUND VACUUM_BACKGROUND','ENV Alias runner — phase extérieure ajout 0493x9q/x9r booléen shell 1 dans les variantes liquide-vide récentes Choisit un domaine initial sans particules gazeuses et phase B=vacuum dans les runners compatibles. Réduit fortement le coût des tests de surface libre lorsque la dynamique gazeuse n’est pas étudiée; ne remplace pas un vrai cas liquide-gaz.');
