INSERT INTO "search_fts" VALUES('artifact:scripts/run_0414_segmented_xy_neumann_qualification.sh','ARTIFACT','scripts/run_0414_segmented_xy_neumann_qualification.sh','RUNNER  Q1-Q7 segmented x/y Neumann qualification runner');
INSERT INTO "search_fts_config" VALUES('version',4);
INSERT INTO "search_fts_content" VALUES(1,'milestone:reference:SRC/MPCD','MILESTONE','SRC/MPCD Collision particulaire SRC/MPCD','Streaming des particules, collision stochastique par cellule, rotation SRD, grid shift et thermostat. C''est le fluide mésoscopique de base. Socle actif CORE CODE');
INSERT INTO "search_fts_content" VALUES(2,'milestone:reference:Q6','MILESTONE','Q6 Projection quasi-incompressible','Projection du champ de vitesse/moment pour réduire la divergence. Les variantes récentes opèrent sur GPU résident. Socle actif selon RUN_MODE CORE CODE');
INSERT INTO "search_fts_content" VALUES(3,'milestone:reference:Q9','MILESTONE','Q9 Relaxation basse fréquence du flux de masse','Ancienne projection complémentaire du flux de masse à grande longueur d''onde. Historique / séparée du chemin Q6-g-f actuel CORE CODE');
INSERT INTO "search_fts_content" VALUES(4,'milestone:reference:Resampling','MILESTONE','Resampling Contrôle du support particulaire','Rééchantillonnage local conservatif pour maintenir population et masse cellulaire; distinct de Q6 et opt-in. Module séparé, OFF dans les qualifications surface libre récentes CORE QUALIFICATION');
INSERT INTO "search_fts_content" VALUES(5,'milestone:reference:Q6 multi-espèces','MILESTONE','Q6 multi-espèces Projection sélective par espèce','Registre d''espèces; mode independent_masked pour projeter le liquide sans projeter directement le gaz. Socle multi-espèces CORE INFRA');
INSERT INTO "search_fts_content" VALUES(6,'milestone:reference:Q6-g','MILESTONE','Q6-g Q6 force-aware','Inclut la force dans la vitesse tentative avant le streaming afin que la projection corrige la vitesse réellement utilisée pour transporter les particules. Introduit par x3, base de Q6-g-f CORE CODE');
INSERT INTO "search_fts_content" VALUES(7,'milestone:reference:Q6-g-f','MILESTONE','Q6-g-f Q6 force-aware + interface + face-particule + densité','Chaîne: vitesse tentative forcée, interface physique alpha=0.5, condition de pression, reconstruction face-particule B1/RT0 et relaxation lente de densité dans le même solveur CG. Chaîne de projection de référence CORE CODE');
INSERT INTO "search_fts_content" VALUES(8,'milestone:0493x1','MILESTONE','x1 Jalon ancien non individualisé dans le rapport consolidé','Le rapport consolidé actuel ne donne pas une définition séparée et fiable de x1. À retrouver dans l''historique Git si nécessaire CORE CODE');
INSERT INTO "search_fts_content" VALUES(9,'milestone:0493x2','MILESTONE','x2 Test Q6 liquide seul / gravité','Campagne liquide seul qui a montré que le kick gravitaire appliqué avant une projection trop tardive pouvait court-circuiter l''objectif de Q6. Historique; mène à x3 CORE CODE');
INSERT INTO "search_fts_content" VALUES(10,'milestone:0493x3','MILESTONE','x3 Q6-g force-aware - preuve de concept','Projette une vitesse tentative incluant la force avant streaming; première version avec double projection pour démontrer la cause de la sédimentation parasite. Supplanté par x4a/x4b Q6_GF CODE');
INSERT INTO "search_fts_content" VALUES(11,'milestone:0493x4a','MILESTONE','x4a prestream_single','Une seule projection avant transport; évite le double solve tout en supprimant la dérive gravitaire. Supplanté par x4b Q6_GF CODE');
INSERT INTO "search_fts_content" VALUES(12,'milestone:0493x4b','MILESTONE','x4b prestream_single_fused','Fusionne dépôt de v+a dt, projection Q6, puis application force+Q6 sans passage particulaire dédié au kick. Séquençage de référence Q6-g-f Q6_GF CODE');
INSERT INTO "search_fts_content" VALUES(13,'milestone:0493x5a','MILESTONE','x5a free_surface_masked initial','Masque Q6 du liquide partiellement rempli; bord du support traité comme pression de jauge nulle à demi-maille. Étape historique Q6_GF CODE');
INSERT INTO "search_fts_content" VALUES(14,'milestone:0493x5a2','MILESTONE','x5a2 Dam-break vide','Validation du masque surface libre sur dam-break sans gaz; robuste avant impact mais révèle que bord du support != interface physique. Historique / discriminant Q6_GF QUALIFICATION');
INSERT INTO "search_fts_content" VALUES(15,'milestone:0493x5b','MILESTONE','x5b Gaz explicite compressible','Ajoute une espèce gaz q6Strength=0 qui collisionne avec le liquide sans être projetée incompressible. Base du couplage gaz Q6_GF CODE');
INSERT INTO "search_fts_content" VALUES(16,'milestone:0493x6a','MILESTONE','x6a Diagnostic EOS gaz','Reconstruit une pression gazeuse EOS sans modifier la physique afin d''auditer le futur couplage de pression. Diagnostic historique Q6_GF DIAGNOSTIC');
INSERT INTO "search_fts_content" VALUES(17,'milestone:0493x6b','MILESTONE','x6b Audit support vs interface','Compare seuil de support Q6 et isovaleur physique alpha=0.5. Diagnostic historique Q6_GF DIAGNOSTIC');
INSERT INTO "search_fts_content" VALUES(18,'milestone:0493x6c','MILESTONE','x6c Alpha physique résident','Construit sur GPU un champ alpha du liquide, filtré par stencil cinq points, distinct du simple carrier Q6. Actif, base géométrique Q6/capillarité Q6_GF CODE');
INSERT INTO "search_fts_content" VALUES(19,'milestone:0493x6d','MILESTONE','x6d Distance sous-maille 1/theta','Utilise la position locale de l''isovaleur pour corriger la distance de frontière au lieu du facteur demi-maille. Supplanté par x6f Q6_GF CODE');
INSERT INTO "search_fts_content" VALUES(20,'milestone:0493x6e','MILESTONE','x6e Audit topologique des crossings','Montre que l''interface alpha=0.5 traverse souvent des paires de cellules qui sont encore toutes deux dans le carrier numérique. Diagnostic architectural Q6_GF DIAGNOSTIC');
INSERT INTO "search_fts_content" VALUES(21,'milestone:0493x6f','MILESTONE','x6f Stencil physique d''interface','Sépare pressureMask et carrierMask; prépare les coefficients de face sur les crossings alpha=0.5 et la distance sous-maille theta. Actif Q6_GF CODE');
INSERT INTO "search_fts_content" VALUES(22,'milestone:0493x6g','MILESTONE','x6g Pression gazeuse interfaciale','Fournit p_g sur les faces d''interface et impose p_L|Gamma=p_g dans le Dirichlet Q6; plus tard composé avec sigma*kappa. Actif quand gaz explicite Q6_GF CODE');
INSERT INTO "search_fts_content" VALUES(23,'milestone:0493x6h-a','MILESTONE','x6h-A Reconstruction faces basses','Reconstruit les corrections ouest/sud sur frontières physiques basses absentes du stockage east/north. Actif dans Q6-g-f Q6_GF CODE');
INSERT INTO "search_fts_content" VALUES(24,'milestone:0493x6h-b0','MILESTONE','x6h-B0 Diagnostic post-application','Sépare bulk/interface/paroi/zones mixtes pour localiser la divergence après application aux particules. Diagnostic OFF production Q6_GF DIAGNOSTIC');
INSERT INTO "search_fts_content" VALUES(25,'milestone:0493x6h-b1','MILESTONE','x6h-B1 Reconstruction face-particule RT0','Remplace une correction constante par cellule par une reconstruction affine entre corrections de faces, cohérente avec la divergence FV projetée. Actif dans Q6-g-f Q6_GF CODE');
INSERT INTO "search_fts_content" VALUES(26,'milestone:reference:x7a/x7b','MILESTONE','x7a/x7b Kick viriel de densité','Tentatives de restauration de densité par kick post-projection de type ressort/viriel. Rejeté dans Q6-g-f; mutuellement exclusif avec x7d Q6_GF ABLATION');
INSERT INTO "search_fts_content" VALUES(27,'milestone:0493x7d','MILESTONE','x7d Relaxation de densité dans le RHS','Ajoute (f-1)/tau_rho dans le second membre Q6 pour restaurer lentement la densité sans resampling ni kick post-projection. Actif; tau_rho=0.25 dans profil qualifié Q6_GF CODE');
INSERT INTO "search_fts_content" VALUES(28,'milestone:0493x7e','MILESTONE','x7e Qualification x6g+x7d','Valide la coexistence pression gaz + relaxation de densité dans le même RHS, y compris runs longs/coarse-fine. Qualification historique Q6_GF QUALIFICATION');
INSERT INTO "search_fts_content" VALUES(29,'milestone:0493x7f','MILESTONE','x7f Extension multi-topologies','Étend Q6-g-f aux topologies statiques supportées: périodique, canal, boîte fermée, inlet/outlet, segments. Actif Q6_GF CODE');
INSERT INTO "search_fts_content" VALUES(30,'milestone:0493x7f-fix2','MILESTONE','x7f-fix2 Garde wall-simple','Autorise une face specular simple sans imposer artificiellement wallVP. Correctif actif Q6_GF FIX');
INSERT INTO "search_fts_content" VALUES(31,'milestone:0493x7g','MILESTONE','x7g Darcy avant projection','Place le kick Darcy-Brinkman dans la vitesse tentative avant Q6-g-f, sans le rejouer après collision. Actif selon mode Darcy Q6_GF CODE');
INSERT INTO "search_fts_content" VALUES(32,'milestone:0493x7h','MILESTONE','x7h Factorisation run_ok','Rassemble dans les runners le profil src-q6-g-f: x4b, B1, x6f, registre espèces et relaxation densité. Infrastructure runner Q6_GF INFRA');
INSERT INTO "search_fts_content" VALUES(33,'milestone:0493x7i','MILESTONE','x7i Qualification multi-conditions-limites','Campagne commune Taylor-Green, Poiseuille, bend-pipe Darcy et same-face IO pour comparer SRC/Q6/Q6-g-f. Benchmark de référence Q6_GF BENCHMARK');
INSERT INTO "search_fts_content" VALUES(34,'milestone:0493x7j','MILESTONE','x7j CG coopératif CUDA résident','Remplace les réductions/synchronisations host à chaque itération par un unique CG coopératif entièrement GPU. Actif; optimisation majeure coût Q6_GF PERF');
INSERT INTO "search_fts_content" VALUES(35,'milestone:reference:x7k/x7l','MILESTONE','x7k/x7l Réduction de télémétrie','Calcule audits Q6-g-f et réductions host thermostat uniquement au premier pas / cadence summary, sans changer la physique. Actif Q6_GF DIAGNOSTIC');
INSERT INTO "search_fts_content" VALUES(36,'milestone:0493x7m','MILESTONE','x7m Correction topologie monophase','Empêche une fluctuation alpha<0.5 de créer une fausse interface interne dans un fluide monophase complet. Actif automatiquement Q6_GF CODE');
INSERT INTO "search_fts_content" VALUES(37,'milestone:0493x7o','MILESTONE','x7o Symétrisation Q6 indépendant','Supprime le biais est/nord dans la reconstruction des faces pour le domaine complet independent_masked. Actif Q6_GF CODE');
INSERT INTO "search_fts_content" VALUES(38,'milestone:0493x7p','MILESTONE','x7p Symétrisation Q6 commun','Applique la même convention symétrique au Q6 commun. Actif Q6_GF CODE');
INSERT INTO "search_fts_content" VALUES(39,'milestone:0493x7q','MILESTONE','x7q Fermeture exacte du moment périodique','Mesure le moment B1/RT0 réellement appliqué aux particules et enlève le résidu uniforme k=0 dans les directions périodiques fullDomain. Actif automatiquement seulement dans son domaine; pas sur dam-break partiel Q6_GF CODE');
INSERT INTO "search_fts_content" VALUES(40,'milestone:0493x8k','MILESTONE','x8k Inlet segmenté Poiseuille local','Définit une coordonnée locale au segment et impose u_n=4 Umax eta(1-eta) de façon cohérente à l''injection particulaire et à Q6. Actif OPEN_BOUNDARY CODE');
INSERT INTO "search_fts_content" VALUES(41,'milestone:0493x8q','MILESTONE','x8q Continuation cinétique outlet','Supprime les sortants et reconstruit la demi-distribution entrante depuis les moments de couches intérieures, pondérée par le flux normal. Actif pour outlet Neumann OPEN_BOUNDARY CODE');
INSERT INTO "search_fts_content" VALUES(42,'milestone:0493x8r','MILESTONE','x8r Outlet pression Neumann','Conserve gradient de vitesse normal nul pour la vitesse tentative mais impose phi_out=0 côté projection; ne réimpose plus UOUT comme cible physique. Actif OPEN_BOUNDARY CODE');
INSERT INTO "search_fts_content" VALUES(43,'milestone:0493x8s','MILESTONE','x8s Déflation des modes lents du CG','Résout analytiquement les modes longitudinaux les plus lents à l''initialisation du CG pour améliorer le conditionnement du canal long. Actif dans cas applicable OPEN_BOUNDARY PERF');
INSERT INTO "search_fts_content" VALUES(44,'milestone:0493x8t','MILESTONE','x8t Relaxation densité sans mode moyen','Retire uniquement la moyenne spatiale de la cible de relaxation de densité quand outlet pression + fullDomain sont actifs. Actif dans cas applicable OPEN_BOUNDARY CODE');
INSERT INTO "search_fts_content" VALUES(45,'milestone:0493x8j','MILESTONE','x8j Analyse VK POD + sondes','Analyseur de shedding: fréquence POD et probe, phase spatiale, période et comparaison bibliographique. Tooling/qualification, pas une physique OPEN_BOUNDARY ANALYZER');
INSERT INTO "search_fts_content" VALUES(46,'milestone:0493x9a-x9c','MILESTONE','x9a-x9c Choix de la géométrie de courbure','Compare les constructions de champ de courbure; production retient trois passes binomiales 3x3 + gradient/divergence de Scharr (p3). Étapes de sélection; p3 retenu SURFACE_TENSION CODE');
INSERT INTO "search_fts_content" VALUES(47,'milestone:0493x9d','MILESTONE','x9d Activation du saut de Laplace','Ajoute sigma*kappa au potentiel de Dirichlet Q6-g-f; pas de force CSF ni kick particulaire direct. Actif; coeur de la tension superficielle SURFACE_TENSION CODE');
INSERT INTO "search_fts_content" VALUES(48,'milestone:0493x9e','MILESTONE','x9e Diagnostic pression goutte statique','Mesure le saut de pression reconstruit dans la solution Q6 et les grandeurs géométriques des gouttes. Diagnostic/qualification SURFACE_TENSION DIAGNOSTIC');
INSERT INTO "search_fts_content" VALUES(49,'milestone:0493x9f','MILESTONE','x9f Diagnostic quadrupole signé','Observable de forme pour suivre les modes d''oscillation des gouttes. Diagnostic/qualification SURFACE_TENSION DIAGNOSTIC');
INSERT INTO "search_fts_content" VALUES(50,'milestone:0493x9g','MILESTONE','x9g Sélecteurs de phases A/B','Généralise les côtés de l''interface: family:liquid/gas, type:N, vacuum, wall, etc. Actif SURFACE_TENSION CODE');
INSERT INTO "search_fts_content" VALUES(51,'milestone:0493x9h','MILESTONE','x9h Géométrie de paroi pour mouillage','Traite wall comme troisième objet géométrique, distinct des deux phases capillaires. Actif dans mouillage SURFACE_TENSION CODE');
INSERT INTO "search_fts_content" VALUES(52,'milestone:0493x9i-x9l','MILESTONE','x9i-x9l Prototypes angle de contact','Teste remplacement de normale, ghost alpha et reconstructions pariétales; révèle biais de courbure malgré angle local correct. Ablations/supplantés SURFACE_TENSION ABLATION');
INSERT INTO "search_fts_content" VALUES(53,'milestone:0493x9m','MILESTONE','x9m Fermeture statique de mouillage','Construit la courbure de contact à partir d''une normale imposée au mur et d''une normale p3 hors support pariétal. Bonne statique; dynamique ligne triple non fermée SURFACE_TENSION CODE');
INSERT INTO "search_fts_content" VALUES(54,'milestone:0493x9r','MILESTONE','x9r Cutoff de petite courbure résolue','Borne uniquement kappa utilisé dans sigma*kappa par un rayon minimal en cellules; ne modifie pas alpha ni le champ kappa brut. Actif selon benchmark; paramètre de résolution SURFACE_TENSION BENCHMARK');
INSERT INTO "search_fts_content" VALUES(55,'milestone:0493x9s','MILESTONE','x9s Impact/splash paramétrable','Runners goutte -> paroi sèche ou flaque pour changements de topologie et splash. Démonstration/qualification qualitative SURFACE_TENSION BENCHMARK');
INSERT INTO "search_fts_content" VALUES(56,'milestone:0493x10a-x10e','MILESTONE','x10a-x10e Premières barrières / seals / réactions','Premières géométries de crossing et réactions locales pour empêcher les sorties de support. Historique, supplanté FREE_SURFACE_KINETICS CODE');
INSERT INTO "search_fts_content" VALUES(57,'milestone:0493x10f-x10g','MILESTONE','x10f-x10g Réaction conservative globale','Réduction globale des grandeurs de réaction pour éviter des receivers cellule par cellule. Code conservé sans call-site actif FREE_SURFACE_KINETICS CODE');
INSERT INTO "search_fts_content" VALUES(58,'milestone:0493x10h-x10i','MILESTONE','x10h-x10i Critère relatif et réaction par blocs','Utilise (v-u_Gamma).n et une réaction mésoscopique; x10i sert de fallback hard r=1 legacy. Legacy; bypassé par x10o dans runners récents FREE_SURFACE_KINETICS RUNNER');
INSERT INTO "search_fts_content" VALUES(59,'milestone:0493x10j','MILESTONE','x10j Réflexion spéculaire labo','Réfléchit la vitesse dans le repère laboratoire. Ablation rejetée: bloque fortement le dripping FREE_SURFACE_KINETICS ABLATION');
INSERT INTO "search_fts_content" VALUES(60,'milestone:0493x10k','MILESTONE','x10k Réflexion spéculaire repère interface','Réflexion dans le repère local mobile de l''interface. Ablation rejetée FREE_SURFACE_KINETICS ABLATION');
INSERT INTO "search_fts_content" VALUES(61,'milestone:0493x10l','MILESTONE','x10l Diagnostic pré-mur cinétique','Mesure l''état juste avant fermeture et montre que Q6/B1 garde un mouvement normal sortant avant le traitement cinétique. Diagnostic passif FREE_SURFACE_KINETICS DIAGNOSTIC');
INSERT INTO "search_fts_content" VALUES(62,'milestone:0493x10m','MILESTONE','x10m Paroi implicite mobile / scratch','Étape architecturale; buffers cellulaires ensuite réutilisés par x10v et autres briques. Ablation/infrastructure FREE_SURFACE_KINETICS ABLATION');
INSERT INTO "search_fts_content" VALUES(63,'milestone:0493x10n','MILESTONE','x10n Polyligne continue marching-squares','Construit segments, normales et primitives continues réutilisées par x10o, Q2, x12a et plus tard x14. Infrastructure active FREE_SURFACE_KINETICS INFRA');
INSERT INTO "search_fts_content" VALUES(64,'milestone:0493x10o','MILESTONE','x10o Paroi thermique / enveloppe locale','Interface continue Q6 avec enveloppe thermique delta_th=min(C_T dt sqrt(kBT/m), delta_max). Socle actif de la fermeture liquide x12 FREE_SURFACE_KINETICS CODE');
INSERT INTO "search_fts_content" VALUES(65,'milestone:reference:x10p/x10q','MILESTONE','x10p/x10q Résolution recouvrements initiaux','Traite particules déjà du mauvais côté; recherche 3x3 puis fallback 7x7 rare si aucun segment trouvé. Actif FREE_SURFACE_KINETICS CODE');
INSERT INTO "search_fts_content" VALUES(66,'milestone:0493x10cic','MILESTONE','x10cic Alpha cinétique CIC dédié','Champ alpha réservé à la cinétique, distinct du x6c utilisé par Q6/capillarité. Actif; orchestration encore liée à Q6 FREE_SURFACE_KINETICS CODE');
INSERT INTO "search_fts_content" VALUES(67,'milestone:reference:x10biq / Q2','MILESTONE','x10biq / Q2 Reconstruction biquadratique tensorielle','Utilise les 9 valeurs CIC d''un patch 3x3 pour crossing et normale subcellulaires; pas de grille de coefficients supplémentaire. Actif FREE_SURFACE_KINETICS CODE');
INSERT INTO "search_fts_content" VALUES(68,'milestone:0493x10r','MILESTONE','x10r Vitesses endpoints full-vector','Améliore covariance galiléenne par vitesses vectorielles complètes aux endpoints. Ablation rejetée: dripping dégradé FREE_SURFACE_KINETICS ABLATION');
INSERT INTO "search_fts_content" VALUES(69,'milestone:0493x10s','MILESTONE','x10s Cinématique normale au segment','Projette la cinématique sur la normale du segment. Ablation rejetée/OFF FREE_SURFACE_KINETICS ABLATION');
INSERT INTO "search_fts_content" VALUES(70,'milestone:0493x10t','MILESTONE','x10t Cinématique tangentielle rigide','Ajoute une cinématique tangentielle rigide. Ablation rejetée; impulse parasite aggravée FREE_SURFACE_KINETICS ABLATION');
INSERT INTO "search_fts_content" VALUES(71,'milestone:0493x10u','MILESTONE','x10u Relocalisation one-for-one','Miroire uniquement la position d''une particule sortante; même slot, masse et vitesse, sans kick direct. Actif dans chaîne liquide qualifiée FREE_SURFACE_KINETICS CODE');
INSERT INTO "search_fts_content" VALUES(72,'milestone:0493x10v','MILESTONE','x10v Swap local full-vector','Échange le vecteur vitesse complet avec un partenaire liquide intérieur de même masse; conserve exactement P et K de la paire. Actif; peut ajouter dispersion/dissipation interfaciale FREE_SURFACE_KINETICS CODE');
INSERT INTO "search_fts_content" VALUES(73,'milestone:0493x10w','MILESTONE','x10w Limiter thermique pairwise','Réduction thermique locale avec redistribution pairwise conservative P/K. Implémenté mais OFF; exclusif avec x12a FREE_SURFACE_KINETICS CODE');
INSERT INTO "search_fts_content" VALUES(74,'milestone:0493x11a','MILESTONE','x11a Validation Young-Laplace','Suite de gouttes statiques multi-rayons/multi-sigma utilisant x9e pour comparer Delta p_Q6 à sigma/R_eff. Tooling de qualification FREE_SURFACE_KINETICS INFRA');
INSERT INTO "search_fts_content" VALUES(75,'milestone:0493x11b','MILESTONE','x11b Dispersion onde capillaire','Suit une interface sinusoïdale et ajuste une oscillation amortie pour mesurer la dispersion capillaire. Tooling de qualification FREE_SURFACE_KINETICS INFRA');
INSERT INTO "search_fts_content" VALUES(76,'milestone:0493x12a','MILESTONE','x12a Refroidissement thermique local petites structures','Réduit kBT effectif et enveloppe x10o quand l''épaisseur locale L_loc devient inférieure au rayon Rc ~25.3h. Actif dans chaîne liquide qualifiée FREE_SURFACE_KINETICS CODE');
INSERT INTO "search_fts_content" VALUES(77,'milestone:reference:x12b/x12c','MILESTONE','x12b/x12c Construction benchmark JFM','Étapes de construction/réduction du domaine splash JFM sans nouvelle physique C++. Tooling historique FREE_SURFACE_KINETICS BENCHMARK');
INSERT INTO "search_fts_content" VALUES(78,'milestone:0493x12d','MILESTONE','x12d Benchmark JFM 524','Runner de mesure du splash/obstacle d''après Josserand-Lemoyne-Troeger-Zaleski. Benchmark applicatif; similitude Re encore limitée FREE_SURFACE_KINETICS BENCHMARK');
INSERT INTO "search_fts_content" VALUES(79,'milestone:0493x12cal','MILESTONE','x12cal Calibrateur dynamique capillaire','Mesure la dispersion/frequence des ondes et distingue sigma_dyn de la tension mécanique. Qualification dynamique FREE_SURFACE_KINETICS CALIBRATOR');
INSERT INTO "search_fts_content" VALUES(80,'milestone:0493x12yl','MILESTONE','x12yl Calibrateur mécanique de sigma','Gouttes statiques appariées pour extraire sigma_eff via Delta p_cap = sigma_eff <kappa>. Qualification mécanique historique FREE_SURFACE_KINETICS CALIBRATOR');
INSERT INTO "search_fts_content" VALUES(81,'milestone:0493x13a','MILESTONE','x13a Pré-balayage analytique transport','Définit la portée intrinsèque des candidats SRC avant runs coûteux. Tooling/calibration TRANSPORT_SURFACE PERF');
INSERT INTO "search_fts_content" VALUES(82,'milestone:0493x13b','MILESTONE','x13b Cisaillement transverse pur','Première métrologie de viscosité transverse; utile pour tendance/localité mais déclassée comme échelle absolue. Diagnostic historique TRANSPORT_SURFACE DIAGNOSTIC');
INSERT INTO "search_fts_content" VALUES(83,'milestone:0493x13c','MILESTONE','x13c Choix de gamma','Qualifie l''occupation moyenne et conduit au choix économique gamma=8. Calibration TRANSPORT_SURFACE QUALIFICATION');
INSERT INTO "search_fts_content" VALUES(84,'milestone:0493x13d','MILESTONE','x13d Longue longueur d''onde / acoustique','Ajoute grandes longueurs d''onde, corrige le calibrateur longitudinal amorti et qualifie un premier G08. Calibration TRANSPORT_SURFACE CALIBRATOR');
INSERT INTO "search_fts_content" VALUES(85,'milestone:0493x13e','MILESTONE','x13e Sweep Mach','Explore la réponse non linéaire compressible et sépare domaine résolu et domaine constitutif sûr. Calibration TRANSPORT_SURFACE CODE');
INSERT INTO "search_fts_content" VALUES(86,'milestone:0493x13f','MILESTONE','x13f Optimisation (angle, lambda/h)','Sweep local à gamma=8 pour réduire viscosité/coût tout en conservant propagation acceptable. Calibration TRANSPORT_SURFACE PERF');
INSERT INTO "search_fts_content" VALUES(87,'milestone:0493x13g','MILESTONE','x13g Reproductibilité statistique GPU','Montre qu''état initial + seed identiques ne donnent pas une trajectoire GPU bit-à-bit; impose analyses multi-graines. Règle méthodologique TRANSPORT_SURFACE CODE');
INSERT INTO "search_fts_content" VALUES(88,'milestone:0493x13h-a','MILESTONE','x13h-A Acoustique point final lambda/h=0.72','Mesure c_s et viscosité longitudinale du fluide final avec amplitudes multiples et bootstrap. Qualification constitutive TRANSPORT_SURFACE QUALIFICATION');
INSERT INTO "search_fts_content" VALUES(89,'milestone:0493x13h-b','MILESTONE','x13h-B Viscosité vs densité / localité','Cartographie la dépendance à gamma et la frontière de localité; échelle absolue ensuite réauditée par Taylor-Green. Qualification constitutive TRANSPORT_SURFACE QUALIFICATION');
INSERT INTO "search_fts_content" VALUES(90,'milestone:0493x13h-c','MILESTONE','x13h-C Domaine Mach final','Définit l''enveloppe de densité/Mach du fluide G08-0.72. Qualification constitutive TRANSPORT_SURFACE QUALIFICATION');
INSERT INTO "search_fts_content" VALUES(91,'milestone:0493x13h','MILESTONE','x13h Point liquide de référence','Fluide économique gamma=8, angle 120 deg, lambda/h=0.72; utilisé pour qualification surface libre finale. Référence liquide qualifiée 31/08/2026 TRANSPORT_SURFACE QUALIFICATION');
INSERT INTO "search_fts_content" VALUES(92,'milestone:0493x13j','MILESTONE','x13j Young-Laplace x13h smoke','Smoke/qualification mécanique du point x13h; un seul point n''est pas une qualification multi-rayons. Tooling TRANSPORT_SURFACE INFRA');
INSERT INTO "search_fts_content" VALUES(93,'milestone:0493x13k','MILESTONE','x13k Goutte oscillante n=2','Validation dynamique capillaire du mode azimutal n=2 sur fluide x13h. Qualifié historique TRANSPORT_SURFACE BENCHMARK');
INSERT INTO "search_fts_content" VALUES(94,'milestone:0493x13l','MILESTONE','x13l Goutte oscillante n=3','Validation dynamique capillaire du mode n=3. Qualifié historique TRANSPORT_SURFACE BENCHMARK');
INSERT INTO "search_fts_content" VALUES(95,'milestone:0493x13m','MILESTONE','x13m Goutte oscillante n=4','Validation dynamique capillaire du mode n=4. Qualifié historique TRANSPORT_SURFACE BENCHMARK');
INSERT INTO "search_fts_content" VALUES(96,'milestone:0493x13n','MILESTONE','x13n Taylor-Culick 2D','Benchmark de rétraction de nappe; révèle une vitesse trop faible malgré traction capillaire locale proche de 2 sigma. Limite dynamique connue; référence G_TC ~0.795 au rollback TRANSPORT_SURFACE BENCHMARK');
INSERT INTO "search_fts_content" VALUES(97,'milestone:0493x13o','MILESTONE','x13o Swap normal-only','Ablation de x10v: échange seulement la composante normale locale et laisse tangentielle inchangée. OFF production TRANSPORT_SURFACE ABLATION');
INSERT INTO "search_fts_content" VALUES(98,'milestone:reference:x13r/x13s','MILESTONE','x13r/x13s Refroidissements locaux directs','Tentatives plus agressives de refroidissement interfacial pour accélérer Taylor-Culick. Rejetées TRANSPORT_SURFACE BENCHMARK');
INSERT INTO "search_fts_content" VALUES(99,'milestone:0493x13t','MILESTONE','x13t Refroidissement progressif unifié','Loi progressive de refroidissement/rétention fondée sur l''échelle locale. Rejetée comme chemin général TRANSPORT_SURFACE ABLATION');
INSERT INTO "search_fts_content" VALUES(100,'milestone:reference:x13u/x13v','MILESTONE','x13u/x13v Rétention one-for-one sous x13t','Sépare correction de position et swap pour tester la rétention des particules au rim. Expérimental/rejeté TRANSPORT_SURFACE ABLATION');
INSERT INTO "search_fts_content" VALUES(101,'milestone:0493x13w','MILESTONE','x13w Escape -> inactive -> reseed','Transforme les sorties en slots inactifs puis réensemence localement côté liquide. Rejeté: contraction artificielle du support TRANSPORT_SURFACE ABLATION');
INSERT INTO "search_fts_content" VALUES(102,'milestone:0493x13w-fix3','MILESTONE','x13w-fix3 Correctif reseed','Version corrigée du choix géométrique de cellule de reseed utilisée dans la validation croisée finale. Toujours invalidée physiquement TRANSPORT_SURFACE FIX');
INSERT INTO "search_fts_content" VALUES(103,'milestone:0493x13x','MILESTONE','x13x Rétention probabiliste','Balaye une fraction de rétention pour chercher compromis Taylor-Culick / dynamique de goutte. Aucun compromis robuste TRANSPORT_SURFACE BENCHMARK');
INSERT INTO "search_fts_content" VALUES(104,'milestone:0493x13z','MILESTONE','x13z Changements de grille','Explore raffinement de grille et gains Taylor-Culick. Non suffisant pour validation TRANSPORT_SURFACE BENCHMARK');
INSERT INTO "search_fts_content" VALUES(105,'milestone:0493x13za-x13zc','MILESTONE','x13za-x13zc Dépendance de grille de l''interface','Analyse rayon effectif, courbure et métriques Young-Laplace lors du raffinement. Diagnostic; révèle forte dépendance de kappa_active à forte sigma TRANSPORT_SURFACE DIAGNOSTIC');
INSERT INTO "search_fts_content" VALUES(106,'milestone:0493x13zd','MILESTONE','x13zd Validation croisée décisive','Teste x13t+x13w sur gouttes oscillantes; montre contraction de support et détruit la dynamique modale. Invalide ces fermetures; motive rollback au tag qualifié TRANSPORT_SURFACE QUALIFICATION');
INSERT INTO "search_fts_content" VALUES(107,'milestone:0493x14a-x14j','MILESTONE','x14a-x14j Thermostat séparé par espèce','Ajoute des cibles kBT propres aux espèces après collision SRC commune, sans séparer la collision du mélange. Architecture x14 LIQUID_GAS CODE');
INSERT INTO "search_fts_content" VALUES(108,'milestone:0493x14d','MILESTONE','x14d Collision commune + thermostats séparés','Conserve SRC commun au mélange; seule la remise à température est faite par type. Actif dans x14 LIQUID_GAS CODE');
INSERT INTO "search_fts_content" VALUES(109,'milestone:0493x14g','MILESTONE','x14g Cellules exactes post-stream/grid-shift','Utilise les identifiants de cellule SRC persistants exacts pour thermostat par espèce. Correctif d''intégration actif LIQUID_GAS FIX');
INSERT INTO "search_fts_content" VALUES(110,'milestone:0493x14j','MILESTONE','x14j Goutte deux températures','Cas d''intégration thermostat liquide/gaz avant fermeture cinétique bilatérale. Benchmark d''intégration LIQUID_GAS BENCHMARK');
INSERT INTO "search_fts_content" VALUES(111,'milestone:0493x14k','MILESTONE','x14k Géométrie cinétique bilatérale','Autorise le côté gaz à consommer la même géométrie de relocalisation x10 que le liquide, avec sens de phase inversé. Opt-in; change le modèle d''interface LIQUID_GAS CODE');
INSERT INTO "search_fts_content" VALUES(112,'milestone:0493x14l','MILESTONE','x14l Réflexion spéculaire du gaz','Réfléchit la composante normale relative du gaz à l''interface mobile; tangentielle inchangée. Qualifié pour imperméabilité normale dans cas tests LIQUID_GAS CODE');
INSERT INTO "search_fts_content" VALUES(113,'milestone:0493x14m','MILESTONE','x14m Assemblage bilatéral + compatibilité x12a','Combine liquide x10/x12, gaz x14l et thermostat séparé; x12a reste côté liquide uniquement. Architecture intégrée LIQUID_GAS CODE');
INSERT INTO "search_fts_content" VALUES(114,'milestone:0493x14n','MILESTONE','x14n Ablation fermeture gaz OFF','Coupe la fermeture cinétique gazeuse pour séparer pression et imperméabilité. Ablation LIQUID_GAS ABLATION');
INSERT INTO "search_fts_content" VALUES(115,'milestone:0493x14o','MILESTONE','x14o Ablation pression gaz constante','Utilise une pression gazeuse constante choisie pour annuler la contribution de jauge. Ablation LIQUID_GAS ABLATION');
INSERT INTO "search_fts_content" VALUES(116,'milestone:0493x14r','MILESTONE','x14r Analyse volume accessible','Analyse offline montrant que p=N kBT/A_cell sous-estime la pression si seule une fraction de cellule est accessible au gaz. Diagnostic conduisant à x14s LIQUID_GAS ANALYZER');
INSERT INTO "search_fts_content" VALUES(117,'milestone:0493x14s','MILESTONE','x14s EOS gaz volume accessible','Corrige la pression gazeuse par la fraction de volume accessible dérivée de alpha Q6. Actif dans x14 récent LIQUID_GAS CODE');
INSERT INTO "search_fts_content" VALUES(118,'milestone:0493x14t','MILESTONE','x14t Piston pression thermodynamique','Benchmark plan qui qualifie la transmission moyenne de p_g par x6g/x14s sans terme impulsionnel direct. Qualification composante thermodynamique LIQUID_GAS BENCHMARK');
INSERT INTO "search_fts_content" VALUES(119,'milestone:0493x14u','MILESTONE','x14u Gaz incident normal','Benchmark de flux de moment dirigé; montre que x14l seul rend imperméable mais ne restitue presque pas le moment perdu au liquide. Diagnostic conduisant à x14v LIQUID_GAS BENCHMARK');
INSERT INTO "search_fts_content" VALUES(120,'milestone:0493x14v','MILESTONE','x14v Kick cinétique excédentaire','Transfère J_excess = J_raw - J_thermo au liquide afin d''ajouter le flux cinétique hors équilibre sans doubler la pression x6g. Actif dans chaîne x14 candidate LIQUID_GAS CODE');
INSERT INTO "search_fts_content" VALUES(121,'milestone:0493x14w','MILESTONE','x14w Couette biphasique','Benchmark de transfert tangentiel; teste continuité de contrainte via collisions SRC communes sans frottement interfacial ad hoc. PASS-like sur contrainte tangentielle LIQUID_GAS BENCHMARK');
INSERT INTO "search_fts_content" VALUES(122,'milestone:0493x14x','MILESTONE','x14x Goutte oscillante diphasique n=2','Runner intégré x6g+x9+x14l+x14v+chaîne liquide; banc pour forme, moment et fréquence. Qualification intégrée/tooling LIQUID_GAS BENCHMARK');
INSERT INTO "search_fts_content" VALUES(123,'milestone:0493x14y','MILESTONE','x14y Ablation sans soustraction p_g','Transfère J_raw directement et supprime la soustraction thermodynamique. Rejeté: double comptage pression équilibre LIQUID_GAS ABLATION');
INSERT INTO "search_fts_content" VALUES(124,'milestone:0493x14z','MILESTONE','x14z Fermeture géométrique p_ref','Corrige la résultante du seul p_ref uniforme sur la polyligne x10n. Rejeté comme cause du défaut n=1 LIQUID_GAS ABLATION');
INSERT INTO "search_fts_content" VALUES(125,'milestone:0493x14aa','MILESTONE','x14aa Traction thermodynamique absolue sur faces x6g','Déplace toute la traction sur la géométrie de faces Q6. Non retenu: dégrade la géométrie locale de forme LIQUID_GAS CODE');
INSERT INTO "search_fts_content" VALUES(126,'milestone:0493x14ab','MILESTONE','x14ab p_ref sur x10n + jauge sur faces x6g','Sépare référence et jauge mais garde traction variable sur normales axiales Q6. Non retenu LIQUID_GAS CODE');
INSERT INTO "search_fts_content" VALUES(127,'milestone:0493x14ac','MILESTONE','x14ac Projection globale minimum-L2','Garde l''ancien échantillonnage local et corrige uniquement la résultante globale. Principe conservé, local supplanté par x14ad LIQUID_GAS CODE');
INSERT INTO "search_fts_content" VALUES(128,'milestone:0493x14ad','MILESTONE','x14ad Traction locale cohérente avec faces x6g','Échantillonne la pression de jauge des faces représentées qui terminent chaque segment x10n, applique sur normale locale, puis corrige la résultante résiduelle. Retenu pour interfaces courbes x14 LIQUID_GAS CODE');
INSERT INTO "search_fts_content" VALUES(129,'milestone:0493x14ae','MILESTONE','x14ae Diagnostic pertes scatter','Compte les kicks x14v qui ne trouvent aucun support liquide après CIC/fallback. Diagnostic; pertes nulles sur cas discriminant LIQUID_GAS DIAGNOSTIC');
INSERT INTO "search_fts_content" VALUES(130,'milestone:0493x14af','MILESTONE','x14af Diagnostic bilan global','Mesure J_Q6 applique, J_thermo et x14v; identifie le mismatch Q6/B1 - traction reconstruite comme source de dérive. Diagnostic causal LIQUID_GAS DIAGNOSTIC');
INSERT INTO "search_fts_content" VALUES(131,'milestone:0493x14ag','MILESTONE','x14ag Traînée avec inlet/outlet','Premier benchmark de traînée ouvert; évolution du gaz jusqu''à inversion du courant. Abandonné LIQUID_GAS BENCHMARK');
INSERT INTO "search_fts_content" VALUES(132,'milestone:0493x14ah','MILESTONE','x14ah Traînée périodique-x','Canal périodique avec goutte entraînée par un profil gazeux; vérifie que la fermeture ne supprime pas la vraie traînée. Benchmark intégré LIQUID_GAS BENCHMARK');
INSERT INTO "search_fts_content" VALUES(133,'milestone:0493x14ai','MILESTONE','x14ai Fermeture de résultante Q6 appliquée','Utilise la résultante B1/RT0 réellement appliquée comme cible globale de la projection de traction x14ad. Concept retenu mais version initiale supplantée LIQUID_GAS CODE');
INSERT INTO "search_fts_content" VALUES(134,'milestone:0493x14ai-fix1','MILESTONE','x14ai-fix1 Fermeture B1 exacte post-correction périodique','Corrige la cible x14ai pour inclure la correction uniforme périodique B1; ferme le moment global au roundoff. Seulement composante liquide fermée et isolée des frontières Q6 externes LIQUID_GAS CODE');
INSERT INTO "search_fts_content" VALUES(135,'milestone:0493x14aj','MILESTONE','x14aj Goutte oscillante n=3 avec gaz','Qualification du mode n=3 de la chaîne x14ai-fix1. REVIEW: fréquence ~12% lente dans campagne actuelle LIQUID_GAS BENCHMARK');
INSERT INTO "search_fts_content" VALUES(136,'milestone:0493x14ak','MILESTONE','x14ak Taylor-Culick diphasique - fluide x14','TC avec paramètres liquide x14 (gamma=20, dt=0.002, etc.); comparaison historique confondait changement de fluide et effet gaz. REVIEW; ne pas utiliser pour isoler effet gaz LIQUID_GAS BENCHMARK');
INSERT INTO "search_fts_content" VALUES(137,'milestone:0493x14al','MILESTONE','x14al Taylor-Culick apparié au point x13h','Deux runs avec liquide initial identique: liquide seul vs même liquide + gaz, pour isoler le couplage gaz. Contrôle liquide reproduit; branche gaz à relire car EOS global kBT avait été mal aligné dans le premier runner LIQUID_GAS BENCHMARK');
INSERT INTO "search_fts_content" VALUES(138,'milestone:0493x14am','MILESTONE','x14am Young-Laplace diphasique multi-rayons','Screening multi-rayons avec x9e sans baseline sigma=0 longue. REVIEW/non décisif à sigma=10000: kappa_active et pression sont déjà connus comme métrologie bruyante/non monotone dans ce régime LIQUID_GAS DIAGNOSTIC');
INSERT INTO "search_fts_content" VALUES(139,'milestone:20260907-0414-segmented-xy','MILESTONE','0414 Extension quadriface des open boundaries segmentées','Généralise les entrées/sorties segmentées aux axes x et y sur le chemin CUDA résident; crossing multi-axes chronologique, x8r quadriface, x8t généralisé, x8s séparable 1-D/2-D, gardes de coins/réservoirs et diagnostic low-face corrigé. QUALIFIED OPEN_BOUNDARY CODE');
INSERT INTO "search_fts_content" VALUES(140,'symbol:control:livevis_control.kv:clip','SYMBOL','livevis_control.kv:clip livevis_control.kv:clip','CONTROL Clé fichier contrôle livevis ajout 0341a double; <=0 active comportement auto/default selon renderer initialisé depuis LIVE_VIS_CLIP Change à chaud l’échelle de saturation/clip du champ affiché. Pour le renderer CUDA, clip<=0 utilise le défaut interne dépendant du champ.');
INSERT INTO "search_fts_content" VALUES(141,'symbol:control:livevis_control.kv:colormap','SYMBOL','livevis_control.kv:colormap livevis_control.kv:colormap','CONTROL Clé fichier contrôle livevis ajout 0342a blue_red | gray | thermal initialisé depuis LIVE_VIS_COLORMAP Change à chaud le colormap utilisé pour convertir le champ scalaire en RGBA. N’affecte que la visualisation. Alias: grey/grayscale/greyscale -> gray; heat/hot -> thermal.');
INSERT INTO "search_fts_content" VALUES(142,'symbol:control:livevis_control.kv:field','SYMBOL','livevis_control.kv:field livevis_control.kv:field','CONTROL Clé fichier contrôle livevis ajout 0341a | mis à jour 0361 | étendu 0493x9d courbure p3 ux | uy | vx | vy | speed | density | mass | N | n | count | population | particle_count | cell_count | vorticity | omega | curl | chi | topo_chi | alpha | darcy_alpha | darcy_power | darcy | brinkman_power | curvature | kappa | curvature_x9b | kappa_x9b | curvature_p1 | kappa_p1 | curvature_x9c | kappa_x9c | curvature_p3 | kappa_p3 initialisé depuis LIVE_VIS_FIELD/SRC_LIVE_VIS_FIELD Change à chaud le champ scalaire affiché. omega et curl sont des alias de vorticity dans le renderer CUDA 0341a. | N/count affiche le nombre de particules fluides par cellule live. | 0493x9d: curvature/kappa affichent le champ p3 de production; les alias x9b/p1 conservent le baseline une passe et x9c/p3 le champ trois passes. Le cutoff x9r ne modifie pas le champ LiveVis brut.');
INSERT INTO "search_fts_content" VALUES(143,'symbol:control:livevis_control.kv:gain','SYMBOL','livevis_control.kv:gain livevis_control.kv:gain','CONTROL Clé fichier contrôle livevis ajout 0341a double > 0 initialisé depuis LIVE_VIS_GAIN Change à chaud le gain multiplicatif de visualisation. Borné côté binaire à un minimum numérique positif.');
INSERT INTO "search_fts_content" VALUES(144,'symbol:control:livevis_control.kv:quiverMinSpeed','SYMBOL','livevis_control.kv:quiverMinSpeed livevis_control.kv:quiverMinSpeed','CONTROL Clé fichier contrôle livevis ajout 0364 double >= 0 0 Change à chaud le seuil minimal de vitesse pour dessiner les segments. ');
INSERT INTO "search_fts_content" VALUES(145,'symbol:control:livevis_control.kv:quiverNx','SYMBOL','livevis_control.kv:quiverNx livevis_control.kv:quiverNx','CONTROL Clé fichier contrôle livevis ajout 0364 entier >= 1 60 Change à chaud le nombre de colonnes de la grille quiver. ');
INSERT INTO "search_fts_content" VALUES(146,'symbol:control:livevis_control.kv:quiverNy','SYMBOL','livevis_control.kv:quiverNy livevis_control.kv:quiverNy','CONTROL Clé fichier contrôle livevis ajout 0364 entier >= 1 32 Change à chaud le nombre de lignes de la grille quiver. ');
INSERT INTO "search_fts_content" VALUES(147,'symbol:control:livevis_control.kv:quiverScale','SYMBOL','livevis_control.kv:quiverScale livevis_control.kv:quiverScale','CONTROL Clé fichier contrôle livevis ajout 0364 double -1 Change à chaud le gain manuel des segments vitesse. <0 désactive l’overlay; >=0 l’active.');
INSERT INTO "search_fts_content" VALUES(148,'symbol:control:livevis_control.kv:quiverSmoothPasses','SYMBOL','livevis_control.kv:quiverSmoothPasses livevis_control.kv:quiverSmoothPasses','CONTROL Clé fichier contrôle livevis ajout 0365 entier; -1 ou >=0 -1 Change à chaud le lissage des vecteurs quiver. <0 réutilise smoothPasses; utile pour field=N non lissé avec vecteurs lissés.');
INSERT INTO "search_fts_content" VALUES(149,'symbol:control:livevis_control.kv:smoothPasses','SYMBOL','livevis_control.kv:smoothPasses livevis_control.kv:smoothPasses','CONTROL Clé fichier contrôle livevis ajout 0341a entier >= 0 initialisé depuis LIVE_VIS_SMOOTH_PASSES Change à chaud le nombre de passes de lissage du champ affiché. Augmenter fortement cette valeur peut augmenter le coût du renderer livevis.');
INSERT INTO "search_fts_content" VALUES(150,'symbol:env:DUMP_ROLE_FILTER','SYMBOL','DUMP_ROLE_FILTER DUMP_ROLE_FILTER DUMP_ROLE_FILTER','ENV Alias script | CUDA resampling post-SRC — diagnostics, split-safety et optimisation inactive ajout 0314 | script 0314 all|fluid | alias script utilisateur fluid dans scripts visual 0309+ | fluid dans scripts visuels 0309+ Alias exporté par les scripts vers dumpRoleFilter. | Alias script vers dumpRoleFilter. Paramètre de script, pas toujours une clé directe. | fluid produit des dumps compacts de visualisation; all reste restart-compatible.');
INSERT INTO "search_fts_content" VALUES(151,'symbol:env:SUMMARY_ROLE_FILTER','SYMBOL','SUMMARY_ROLE_FILTER SUMMARY_ROLE_FILTER SUMMARY_ROLE_FILTER','ENV Alias script | CUDA resampling post-SRC — diagnostics, split-safety et optimisation inactive ajout 0314 | script 0314 all|fluid | alias script utilisateur fluid dans scripts visual 0309+ | fluid dans scripts visuels 0309+ Alias exporté par les scripts vers summaryRoleFilter. | Alias script vers summaryRoleFilter. Paramètre de script, pas toujours une clé directe. | fluid évite de résumer inutilement les slots Inactive.');
INSERT INTO "search_fts_content" VALUES(152,'symbol:env:BIN','SYMBOL','BIN BIN','ENV Alias script / binaire mis à jour 0337 livevis chemin exécutable build/src_mpcd_base_cuda_q6_resident_livevis_0486 dans les runners 0493w4–0493w8 Binaire exécuté par les scripts portables livevis. Peut être surchargé; independent_masked requiert le binaire CUDA Q6 résident 0486 ou un build équivalent.');
INSERT INTO "search_fts_content" VALUES(153,'symbol:env:AUTO_BUILD','SYMBOL','AUTO_BUILD AUTO_BUILD','ENV Alias script / build mis à jour 0337 livevis booléen 1 Autorise le script à compiler automatiquement le binaire manquant. Dans les scripts livevis, le build automatique passe MPCD_ENABLE_LIVE_VIS=1.');
INSERT INTO "search_fts_content" VALUES(154,'symbol:env:RUN_MODES','SYMBOL','RUN_MODES RUN_MODES','ENV Alias script / cas de run existant; utilisé scripts portables liste de modes: src; src-q6; src-resampling; src-q6-resampling dépend du runner; src src-q6 pour les comparaisons injection/TG Choisit les branches d’ablation SRC, Q6 et resampling exécutées par les runners. 0493w4–0493w8: Q6 et resampling restent deux axes indépendants; la qualification Q6 initiale garde le resampling désactivé.');
INSERT INTO "search_fts_content" VALUES(155,'symbol:env:LIVE_VIS_ALPHA','SYMBOL','LIVE_VIS_ALPHA LIVE_VIS_ALPHA','ENV Alias script livevis 0337 ajout 0337 | précisé 0436b double 0.08 Lissage temporel visuel. Principalement utile au fallback CPU. | 0436b: alpha est une persistance temporelle de displayScalar indépendante de smoothPasses; un changement de field ou particleTypeFilter force un reset d’une frame si le correctif 0436b est appliqué.');
INSERT INTO "search_fts_content" VALUES(156,'symbol:env:LIVE_VIS_CLIP','SYMBOL','LIVE_VIS_CLIP LIVE_VIS_CLIP','ENV Alias script livevis 0337 ajout 0337 double; <=0 auto -1 Échelle de saturation couleur. Exemples: ux clip 0.2–0.5; vorticity clip 5–20 selon cas. | 0341b/0341d: sert aussi à initialiser le fichier livevis_control.kv généré par les scripts. | Exemples: ux clip 0.2–0.5; vorticity clip 5–20 selon cas.');
INSERT INTO "search_fts_content" VALUES(157,'symbol:env:LIVE_VIS_CUDA_FIELD','SYMBOL','LIVE_VIS_CUDA_FIELD LIVE_VIS_CUDA_FIELD','ENV Alias script livevis 0337 ajout 0337a booléen 1 Active le renderer CUDA de champ. Mode recommandé par défaut pour classic et resampling livevis. | 0339a: Défaut conservé : renderer CUDA field actif. | Mode recommandé par défaut pour classic et resampling livevis.');
INSERT INTO "search_fts_content" VALUES(158,'symbol:env:LIVE_VIS_CUDA_SNAPSHOT','SYMBOL','LIVE_VIS_CUDA_SNAPSHOT LIVE_VIS_CUDA_SNAPSHOT','ENV Alias script livevis 0337 ajout 0336/0337 booléen 0 Active le snapshot compact expérimental. Non fiable après resampling; garder à 0 sauf diagnostic.');
INSERT INTO "search_fts_content" VALUES(159,'symbol:env:LIVE_VIS_ENABLE','SYMBOL','LIVE_VIS_ENABLE LIVE_VIS_ENABLE LIVE_VIS_ENABLE','ENV Alias script livevis 0337 | Alias script LiveVis / runners 0493x ajout 0337 | documenté/fix runner 0493x6g-fix3 booléen | booléen/int 0|1 1 | 0 dans le runner final x6g Active la visualisation dans les scripts portables livevis. | Contrôle l’activation de la fenêtre LiveVis au niveau des runners 0493x. Exporté vers SRC_LIVE_VIS_ENABLE. Mettre 0 pour exécuter sans fenêtre. | 0493x6g-fix3 corrige le runner final pour respecter la valeur fournie par l’appelant au lieu de forcer 0.');
INSERT INTO "search_fts_content" VALUES(160,'symbol:env:LIVE_VIS_EVERY','SYMBOL','LIVE_VIS_EVERY LIVE_VIS_EVERY','ENV Alias script livevis 0337 ajout 0337 | mis à jour 0339a | mis à jour 0433a | ajout 0337 | mis à jour 0433a entier >0 25 | 20 Cadence de visualisation live : une frame toutes les N étapes. | Depuis 0433a, cette cadence est aussi la valeur suivie par recordEvery quand recordEvery est absent ou <=0. | Cadence de rendu livevis. | Depuis 0433a, cette cadence est aussi la valeur suivie par recordEvery quand recordEvery est absent ou <=0. Exporté vers SRC_LIVE_VIS_EVERY. | 0339a: défaut réduit à 25 pour limiter le coût livevis; mesures indicatives 500 steps: every1≈45.4s, every25≈32.8–38.7s selon bruit. Override possible par environnement. | 0433a: initialise SRC_LIVE_VIS_EVERY au démarrage; peut ensuite être remplacé à chaud par livevis_control.kv:liveEvery/every/visualEvery. | Exporté vers SRC_LIVE_VIS_EVERY. | 0433a: initialise SRC_LIVE_VIS_EVERY au démarrage; peut ensuite être remplacé à chaud par livevis_control.kv:liveEvery/every/visualEvery.');
INSERT INTO "search_fts_content" VALUES(161,'symbol:env:LIVE_VIS_FIELD','SYMBOL','LIVE_VIS_FIELD LIVE_VIS_FIELD','ENV Alias script livevis 0337 ajout 0337 ux|uy|speed|vorticity|mass|density dépend du script Champ affiché par défaut dans la fenêtre live. Par défaut: VK/TG=vorticity, Poiseuille=ux, backward-step/box=speed. | 0341b/0341d: sert aussi à initialiser le fichier livevis_control.kv généré par les scripts. | Par défaut: VK/TG=vorticity, Poiseuille=ux, backward-step/box=speed.');
INSERT INTO "search_fts_content" VALUES(162,'symbol:env:LIVE_VIS_FORCE_HOST_MIRROR','SYMBOL','LIVE_VIS_FORCE_HOST_MIRROR LIVE_VIS_FORCE_HOST_MIRROR','ENV Alias script livevis 0337 ajout 0335c booléen 0 Force le miroir hôte pour visualisation. Debug seulement. | 0339a: Défaut conservé : éviter le host mirror forcé livevis. | Debug seulement.');
INSERT INTO "search_fts_content" VALUES(163,'symbol:env:LIVE_VIS_GAIN','SYMBOL','LIVE_VIS_GAIN LIVE_VIS_GAIN','ENV Alias script livevis 0337 ajout 0337 double >0 1.0 Gain couleur. Réduire si la colormap est saturée; augmenter si le contraste est faible. | 0341b/0341d: sert aussi à initialiser le fichier livevis_control.kv généré par les scripts. | Réduire si la colormap est saturée; augmenter si le contraste est faible.');
INSERT INTO "search_fts_content" VALUES(164,'symbol:env:LIVE_VIS_LOG_SOURCE','SYMBOL','LIVE_VIS_LOG_SOURCE LIVE_VIS_LOG_SOURCE','ENV Alias script livevis 0337 ajout 0337d | mis à jour 0339a | ajout 0337d booléen 0 Contrôle le log de source/fallback livevis. | Affiche le statut source livevis sur une ligne. Exporté vers SRC_LIVE_VIS_LOG_SOURCE; depuis 0337d ne spamme plus le terminal. | 0339a: défaut réduit à 0 pour éviter le bruit de logs; remettre à 1 pour debug. | Exporté vers SRC_LIVE_VIS_LOG_SOURCE; depuis 0337d ne spamme plus le terminal.');
INSERT INTO "search_fts_content" VALUES(165,'symbol:env:LIVE_VIS_NX','SYMBOL','LIVE_VIS_NX LIVE_VIS_NX','ENV Alias script livevis 0337 ajout 0337 entier 300 Résolution x du champ livevis. Exporté vers SRC_LIVE_VIS_NX.');
INSERT INTO "search_fts_content" VALUES(166,'symbol:env:LIVE_VIS_NY','SYMBOL','LIVE_VIS_NY LIVE_VIS_NY','ENV Alias script livevis 0337 ajout 0337 entier 80 Résolution y du champ livevis. Exporté vers SRC_LIVE_VIS_NY.');
INSERT INTO "search_fts_content" VALUES(167,'symbol:env:LIVE_VIS_QUANTILE','SYMBOL','LIVE_VIS_QUANTILE LIVE_VIS_QUANTILE','ENV Alias script livevis 0337 ajout 0337 double dans (0,1] 0.995 Quantile auto de mise à l’échelle. Limiter les outliers dans le fallback CPU.');
INSERT INTO "search_fts_content" VALUES(168,'symbol:env:LIVE_VIS_RESAMPLING_HOST_MIRROR','SYMBOL','LIVE_VIS_RESAMPLING_HOST_MIRROR LIVE_VIS_RESAMPLING_HOST_MIRROR','ENV Alias script livevis 0337 ajout 0335d/0337 booléen 0 Force le fallback hôte en resampling. Fiable mais lent; garder à 0 avec CUDA_FIELD=1. | 0339a: Défaut conservé : éviter le host mirror resampling livevis. | Fiable mais lent; garder à 0 avec CUDA_FIELD=1.');
INSERT INTO "search_fts_content" VALUES(169,'symbol:env:LIVE_VIS_SMOOTH_PASSES','SYMBOL','LIVE_VIS_SMOOTH_PASSES LIVE_VIS_SMOOTH_PASSES','ENV Alias script livevis 0337 ajout 0337 entier >=0 1 Lissage spatial du rendu. Vorticity utilise souvent 1–2 passes. | 0341b/0341d: sert aussi à initialiser le fichier livevis_control.kv généré par les scripts. | Vorticity utilise souvent 1–2 passes.');
INSERT INTO "search_fts_content" VALUES(170,'symbol:env:LIVE_VIS_VSYNC','SYMBOL','LIVE_VIS_VSYNC LIVE_VIS_VSYNC','ENV Alias script livevis 0337 ajout 0337 booléen/int 0 Vsync GLFW. 0 recommandé pour ne pas brider le calcul.');
INSERT INTO "search_fts_content" VALUES(171,'symbol:env:LIVE_VIS_WINDOW_SCALE','SYMBOL','LIVE_VIS_WINDOW_SCALE LIVE_VIS_WINDOW_SCALE','ENV Alias script livevis 0337 ajout 0337 entier >=1 1 Facteur d’échelle de la fenêtre. N’affecte pas la simulation.');
INSERT INTO "search_fts_content" VALUES(172,'symbol:env:LIVE_VIS_COLORMAP','SYMBOL','LIVE_VIS_COLORMAP LIVE_VIS_COLORMAP','ENV Alias script livevis colormap ajout 0342a enum: blue_red | gray | thermal blue_red Colormap initial exporté en SRC_LIVE_VIS_COLORMAP et écrit dans le fichier livevis_control.kv créé par les scripts. Peut ensuite être changé à chaud via la clé colormap du fichier de contrôle.');
INSERT INTO "search_fts_content" VALUES(173,'symbol:env:LIVE_VIS_QUIVER_MIN_SPEED','SYMBOL','LIVE_VIS_QUIVER_MIN_SPEED LIVE_VIS_QUIVER_MIN_SPEED','ENV Alias script livevis quiver ajout 0364 double >= 0 0 Alias script exportable vers SRC_LIVE_VIS_QUIVER_MIN_SPEED. ');
INSERT INTO "search_fts_content" VALUES(174,'symbol:env:LIVE_VIS_QUIVER_NX','SYMBOL','LIVE_VIS_QUIVER_NX LIVE_VIS_QUIVER_NX','ENV Alias script livevis quiver ajout 0364 entier >= 1 60 Alias script exportable vers SRC_LIVE_VIS_QUIVER_NX. ');
INSERT INTO "search_fts_content" VALUES(175,'symbol:env:LIVE_VIS_QUIVER_NY','SYMBOL','LIVE_VIS_QUIVER_NY LIVE_VIS_QUIVER_NY','ENV Alias script livevis quiver ajout 0364 entier >= 1 32 Alias script exportable vers SRC_LIVE_VIS_QUIVER_NY. ');
INSERT INTO "search_fts_content" VALUES(176,'symbol:env:LIVE_VIS_QUIVER_SCALE','SYMBOL','LIVE_VIS_QUIVER_SCALE LIVE_VIS_QUIVER_SCALE','ENV Alias script livevis quiver ajout 0364 double -1 Alias script exportable vers SRC_LIVE_VIS_QUIVER_SCALE. <0 désactive l’overlay.');
INSERT INTO "search_fts_content" VALUES(177,'symbol:env:LIVE_VIS_QUIVER_SMOOTH_PASSES','SYMBOL','LIVE_VIS_QUIVER_SMOOTH_PASSES LIVE_VIS_QUIVER_SMOOTH_PASSES','ENV Alias script livevis quiver ajout 0365 entier; -1 ou >=0 -1 Alias script exportable vers SRC_LIVE_VIS_QUIVER_SMOOTH_PASSES. <0 réutilise smoothPasses.');
INSERT INTO "search_fts_content" VALUES(178,'symbol:env:LIVE_VIS_CONTROL_BASENAME','SYMBOL','LIVE_VIS_CONTROL_BASENAME LIVE_VIS_CONTROL_BASENAME','ENV Alias script livevis runtime control ajout 0341d nom de fichier livevis_control.kv Nom du fichier utilisé avec LIVE_VIS_CONTROL_DIR ou, par défaut, dans le run_root. Permet de distinguer plusieurs contrôles, par exemple vk_io.kv, tg_hole.kv, poiseuille.kv.');
INSERT INTO "search_fts_content" VALUES(179,'symbol:env:LIVE_VIS_CONTROL_DIR','SYMBOL','LIVE_VIS_CONTROL_DIR LIVE_VIS_CONTROL_DIR','ENV Alias script livevis runtime control ajout 0341d chemin répertoire vide Répertoire dans lequel créer le fichier de contrôle lorsque LIVE_VIS_CONTROL_FILE est vide. Combiné avec LIVE_VIS_CONTROL_BASENAME. Exemple: LIVE_VIS_CONTROL_DIR=. LIVE_VIS_CONTROL_BASENAME=livevis_control.kv.');
INSERT INTO "search_fts_content" VALUES(180,'symbol:env:LIVE_VIS_CONTROL_ENABLE','SYMBOL','LIVE_VIS_CONTROL_ENABLE LIVE_VIS_CONTROL_ENABLE','ENV Alias script livevis runtime control ajout 0341b; export explicite 0341c booléen shell 1 Active la création/export du fichier de contrôle livevis dans les scripts portables. À 0, aucun fichier de contrôle n’est préparé et SRC_LIVE_VIS_CONTROL_FILE peut rester vide.');
INSERT INTO "search_fts_content" VALUES(181,'symbol:env:LIVE_VIS_CONTROL_EVERY','SYMBOL','LIVE_VIS_CONTROL_EVERY LIVE_VIS_CONTROL_EVERY','ENV Alias script livevis runtime control ajout 0341b; export explicite 0341c entier >= 1 1 Valeur script exportée en SRC_LIVE_VIS_CONTROL_EVERY. Contrôle la fréquence de relecture côté binaire.');
INSERT INTO "search_fts_content" VALUES(182,'symbol:env:LIVE_VIS_CONTROL_FILE','SYMBOL','LIVE_VIS_CONTROL_FILE LIVE_VIS_CONTROL_FILE','ENV Alias script livevis runtime control ajout 0341b; clarifié 0341d chemin fichier .kv vide Chemin explicite du fichier de contrôle livevis. Prioritaire sur LIVE_VIS_CONTROL_DIR et le chemin par défaut run_root. Utiliser ce paramètre, et non LIVE_VIS_CONTROL_FILE_EFFECTIVE, pour imposer un fichier tel que ./livevis_control.kv. Recommandé si CLEAN_RUN_ROOT=1 et que l’on veut un fichier persistant hors run_root.');
INSERT INTO "search_fts_content" VALUES(183,'symbol:env:LIVE_VIS_CONTROL_LOG','SYMBOL','LIVE_VIS_CONTROL_LOG LIVE_VIS_CONTROL_LOG','ENV Alias script livevis runtime control ajout 0341b; export explicite 0341c booléen shell 1 Valeur script exportée en SRC_LIVE_VIS_CONTROL_LOG. Les logs livevis sont dans le .time car le stderr du binaire y est redirigé par le script.');
INSERT INTO "search_fts_content" VALUES(184,'symbol:env:LIVE_VIS_CONTROL_FILE_EFFECTIVE','SYMBOL','LIVE_VIS_CONTROL_FILE_EFFECTIVE LIVE_VIS_CONTROL_FILE_EFFECTIVE','ENV Alias script livevis runtime control interne ajout 0341b; export explicite 0341c; clarifié 0341d chemin fichier .kv résolu résolu automatiquement Chemin effectivement transmis au binaire via SRC_LIVE_VIS_CONTROL_FILE. Variable interne/résolue: ne pas la fixer manuellement. Ordre de résolution 0341d: LIVE_VIS_CONTROL_FILE, sinon LIVE_VIS_CONTROL_DIR+LIVE_VIS_CONTROL_BASENAME, sinon run_root/LIVE_VIS_CONTROL_BASENAME.');
INSERT INTO "search_fts_content" VALUES(185,'symbol:env:INACTIVE_SLOTS_RESAMPLING','SYMBOL','INACTIVE_SLOTS_RESAMPLING INACTIVE_SLOTS_RESAMPLING','ENV Alias script livevis/benchmark confirmé 0337 entier 750000 pour certains scripts Nombre de slots inactifs pour les cas resampling. N’affecte pas le SRC classic si RUN_MODES=classic; utile pour réservoir resampling.');
INSERT INTO "search_fts_content" VALUES(186,'symbol:env:INACTIVE_SLOTS','SYMBOL','INACTIVE_SLOTS INACTIVE_SLOTS INACTIVE_SLOTS','ENV Capacité particulaire | CUDA resampling post-SRC — diagnostics, split-safety et optimisation inactive consolidé 0311-0312 | script/demo/audit entier | alias script utilisateur 50k-120k selon cas; pas de défaut universel | selon script; éviter les millions Nombre de slots Inactive préalloués par les générateurs/scripts. | Nombre de slots Inactive préalloués dans les scripts et audits. La réserve peut être grande sans être écrite dans les dumps si dumpRoleFilter=fluid. | N’est pas une clé params.kv directe universelle; transmis par les générateurs d’état/scripts.');
INSERT INTO "search_fts_content" VALUES(187,'symbol:param:dumpRoleFilter','SYMBOL','dumpRoleFilter dumpParticleRoleFilter dumpRoleFilter','PARAM Dumps et post-traitement | Sorties compactes — aliases rôle ajout 0314 | alias accepté; complété inventaire 0490p all|fluid | chaîne all dans le cœur; fluid dans scripts visuels | all Contrôle si les dumps .smpcd écrivent tous les slots ou seulement les particules Fluid. | Alias de dumpRoleFilter. fluid accélère visualisation/post-traitement mais ne doit pas être utilisé pour un restart complet. | Ligne ajoutée par comparaison exhaustive du parseur params.kv au commit 36abd23 avec l’inventaire consolidé 0436b.');
INSERT INTO "search_fts_content" VALUES(188,'symbol:param:summaryRoleFilter','SYMBOL','summaryRoleFilter summaryParticleRoleFilter summaryRoleFilter','PARAM Summaries runtime | Sorties compactes — aliases rôle ajout 0314 | alias accepté; complété inventaire 0490p all|fluid | chaîne all dans le cœur; fluid dans scripts visuels | all Contrôle si les summaries parcourent tous les slots ou un état compact fluide. | Alias de summaryRoleFilter. fluid réduit le coût lorsque INACTIVE_SLOTS est grand. | Ligne ajoutée par comparaison exhaustive du parseur params.kv au commit 36abd23 avec l’inventaire consolidé 0436b.');
INSERT INTO "search_fts_content" VALUES(189,'symbol:param:srcClassicCudaModeEnable','SYMBOL','srcClassicCudaModeEnable classicSrcCudaMode classicSrcCudaMode classicSrcCudaModeEnable classicSrcCudaModeEnable classicSrcModeEnable classicSrcModeEnable srcClassicCudaModeEnable srcClassicCudaModeEnable','PARAM CUDA — mode SRC classic existant catalogue 0292 | alias accepté | alias accepté | alias accepté | canonique booléen false Sélecteur .kv du chemin SRC/MPCD classic, séparé de la fermeture liquide. | Active le mode SRC classic complet; en CUDA 0286, le chemin classic full CUDA est la voie principale validée. | Active le mode SRC classic complet; en CUDA 0286, le chemin classic full CUDA est la voie principale validée. | Active le mode SRC classic complet; en CUDA 0286, le chemin classic full CUDA est la voie principale validée. | Active le mode SRC classic complet; en CUDA 0286, le chemin classic full CUDA est la voie principale validée. Force le mode SRC classic complet: advection/streaming + shift + collision/rotation + thermostat. Court-circuite les fermetures Q6/resampling/viriel dans le driver; à utiliser pour les démos/validations classic CUDA 0275–0286.');
