INSERT INTO "search_fts_content" VALUES(544,'symbol:param:speciesQ6Enable','SYMBOL','speciesQ6Enable speciesQ6Enable speciesQ6Enable','PARAM Multi-espèces — projection Q6 ajout 0491; étendu 0493w5–0493w8 booléen false Active la distribution ou les solveurs Q6 sensibles aux espèces. Exige speciesRegistryEnable=true et une projection Q6 active; n’active ni Q6 ni le resampling implicitement.');
INSERT INTO "search_fts_content" VALUES(545,'symbol:param:speciesQ6Mode','SYMBOL','speciesQ6Mode speciesQ6Mode speciesQ6Mode','PARAM Multi-espèces — projection Q6 ajout 0491; étendu 0493w5–0493w8 puis 0493x5a–0493x6g enum string common Sélectionne l’opérateur Q6 multi-espèces / surface libre. common/weighted conservent une projection barycentrique unique; independent_masked résout un problème masqué distinct par espèce. free_surface_masked (0493x5a+) projette le liquide sur un support de remplissage absolu; le chemin actuellement qualifié requiert q6ForceProjectionMode=prestream_single_fused, une boîte fermée statique et exactement une espèce projetée. x6f/x6g séparent ensuite interface alpha=0.5, carrier et valeur de pression interfaciale.');
INSERT INTO "search_fts_content" VALUES(546,'symbol:param:speciesQ6Sensitivity','SYMBOL','speciesQ6Sensitivity speciesQ6Sensitivity speciesQ6Sensitivity','PARAM Multi-espèces — projection Q6 ajout 0491; étendu 0493w5–0493w8 double 0.0 Règle l’intensité de la différenciation des poids du mode weighted. Sans effet sur independent_masked; eta=0 redonne common.');
INSERT INTO "search_fts_content" VALUES(547,'symbol:param:speciesQ6AlphaEpsilon','SYMBOL','speciesQ6AlphaEpsilon speciesQ6AlphaEpsilon speciesQ6AlphaEpsilon','PARAM Multi-espèces — projection Q6 ajout 0491; étendu 0493w5–0493w8 double 1.0e-14 Seuil de dégénérescence de la moyenne de force Q6 dans le mode weighted. Utilisé avec speciesQ6FallbackMode; ne définit pas le support independent_masked.');
INSERT INTO "search_fts_content" VALUES(548,'symbol:param:speciesQ6FallbackMode','SYMBOL','speciesQ6FallbackMode speciesQ6FallbackMode speciesQ6FallbackMode','PARAM Multi-espèces — projection Q6 ajout 0491; étendu 0493w5–0493w8 enum string common Choisit le repli du mode weighted lorsque la normalisation est dégénérée. Legacy weighted uniquement; independent_masked n’utilise aucun fallback=common.');
INSERT INTO "search_fts_content" VALUES(549,'symbol:param:speciesQ6ComparisonTolerance','SYMBOL','speciesQ6ComparisonTolerance speciesQ6ComparisonTolerance speciesQ6ComparisonTolerance','PARAM Multi-espèces — projection Q6 ajout 0491; étendu 0493w5–0493w8 double 1.0e-11 Tolérance des comparaisons CPU/CUDA et des contrats de qualification Q6 par espèce. Ne modifie pas le solveur physique.');
INSERT INTO "search_fts_content" VALUES(550,'symbol:param:speciesQ6MinOccupancyFraction','SYMBOL','speciesQ6MinOccupancyFraction speciesQ6MinOccupancyFraction speciesQ6MinOccupancyFraction','PARAM Multi-espèces — projection Q6 ajout 0491; étendu 0493w5–w8 puis Q6-g-f jusqu’à 0493x7q double 0.5 Seuil de support des modes Q6 masqués; sens dépend du mode. independent_masked: seuil relatif d’espèce. free_surface_masked: seuil absolu liquide M_liq/M_ref. Le défaut canonique reste 0.5; le profil Q6-g-f final utilise 0.10. x7m distingue explicitement ce support numérique de l’interface alpha=0.5 et supprime l’interface fictive lorsqu’aucun gaz n’est enregistré.');
INSERT INTO "search_fts_content" VALUES(551,'symbol:env:SPECIES_Q6_ENABLE','SYMBOL','SPECIES_Q6_ENABLE SPECIES_Q6_ENABLE','ENV Alias runner / Q6 multi-espèces ajout/normalisé 0493w4–0493w8 booléen true dans le runner injection; selon scénario TG Active speciesQ6Enable dans params.kv pour les modes contenant Q6. N’active pas projectionEnable à lui seul.');
INSERT INTO "search_fts_content" VALUES(552,'symbol:env:SPECIES_Q6_MODE','SYMBOL','SPECIES_Q6_MODE SPECIES_Q6_MODE','ENV Alias runner / Q6 multi-espèces ajout/normalisé 0493w4–0493w8 common|weighted|independent_masked weighted dans le runner partagé historique; independent_masked par override/qualification Écrit speciesQ6Mode dans params.kv. Utiliser independent_masked pour liquide incompressible/gaz compressible; weighted reste reproductible.');
INSERT INTO "search_fts_content" VALUES(553,'symbol:env:SPECIES_Q6_SENSITIVITY','SYMBOL','SPECIES_Q6_SENSITIVITY SPECIES_Q6_SENSITIVITY','ENV Alias runner / Q6 multi-espèces ajout/normalisé 0493w4–0493w8 double dans [0,1] 1.0 dans le runner injection Écrit speciesQ6Sensitivity. Pertinent pour weighted, sans effet sur independent_masked.');
INSERT INTO "search_fts_content" VALUES(554,'symbol:env:SPECIES_Q6_FALLBACK_MODE','SYMBOL','SPECIES_Q6_FALLBACK_MODE SPECIES_Q6_FALLBACK_MODE','ENV Alias runner / Q6 multi-espèces ajout/normalisé 0493w4–0493w8 common|fatal common Écrit speciesQ6FallbackMode. Legacy weighted uniquement.');
INSERT INTO "search_fts_content" VALUES(555,'symbol:env:SPECIES_Q6_COMPARISON_TOLERANCE','SYMBOL','SPECIES_Q6_COMPARISON_TOLERANCE SPECIES_Q6_COMPARISON_TOLERANCE','ENV Alias runner / Q6 multi-espèces ajout/normalisé 0493w4–0493w8 double >0 1.0e-11 Écrit speciesQ6ComparisonTolerance. Tolérance de qualification; ne modifie pas la physique.');
INSERT INTO "search_fts_content" VALUES(556,'symbol:env:SPECIES_Q6_MIN_OCCUPANCY_FRACTION','SYMBOL','SPECIES_Q6_MIN_OCCUPANCY_FRACTION SPECIES_Q6_MIN_OCCUPANCY_FRACTION','ENV Alias runner / Q6 multi-espèces ajout/normalisé 0493w4–0493w8 double dans [0,1] 0.5 injection/smokes; 0.0 dual_identical Écrit speciesQ6MinOccupancyFraction. Le seuil 0.5 est un défaut de test; 0.0 projette chaque type partout où sa masse locale est positive.');
INSERT INTO "search_fts_content" VALUES(557,'symbol:env:INJECT_PHASE','SYMBOL','INJECT_PHASE INJECT_PHASE','ENV Alias runner / injection multi-espèces ajout/normalisé 0493w4–0493w8 liquid|gas liquid pour le wrapper type1_into_type2 Sélectionne la famille physique et les défauts Q6/fermeture de l’espèce injectée. Indépendant de l’identifiant numérique INJECT_TYPE.');
INSERT INTO "search_fts_content" VALUES(558,'symbol:env:BACKGROUND_PHASE','SYMBOL','BACKGROUND_PHASE BACKGROUND_PHASE','ENV Alias runner / injection multi-espèces ajout/normalisé 0493w4–0493w8 liquid|gas gas Sélectionne la famille physique de l’espèce de fond. Indépendant de BACKGROUND_TYPE.');
INSERT INTO "search_fts_content" VALUES(559,'symbol:env:INJECT_Q6_STRENGTH','SYMBOL','INJECT_Q6_STRENGTH INJECT_Q6_STRENGTH','ENV Alias runner / injection multi-espèces ajout/normalisé 0493w4–0493w8 double 1.0 pour liquid; 0.0 pour gas Définit q6StrengthDeclared de l’espèce injectée. En independent_masked, zéro garantit aucune correction directe.');
INSERT INTO "search_fts_content" VALUES(560,'symbol:env:BACKGROUND_Q6_STRENGTH','SYMBOL','BACKGROUND_Q6_STRENGTH BACKGROUND_Q6_STRENGTH','ENV Alias runner / injection multi-espèces ajout/normalisé 0493w4–0493w8 double 0.0 pour gas; 1.0 pour liquid Définit q6StrengthDeclared de l’espèce de fond. Le cas liquide->gaz qualifié utilise 1/0.');
INSERT INTO "search_fts_content" VALUES(561,'symbol:env:INJECT_MASS_CLOSURE_STRENGTH','SYMBOL','INJECT_MASS_CLOSURE_STRENGTH INJECT_MASS_CLOSURE_STRENGTH','ENV Alias runner / injection multi-espèces ajout/normalisé 0493w4–0493w8 double 1.0 pour liquid; 0.0 pour gas Définit massClosureStrengthDeclared de l’espèce injectée. Concerne le resampling; sans effet si resampling désactivé.');
INSERT INTO "search_fts_content" VALUES(562,'symbol:env:BACKGROUND_MASS_CLOSURE_STRENGTH','SYMBOL','BACKGROUND_MASS_CLOSURE_STRENGTH BACKGROUND_MASS_CLOSURE_STRENGTH','ENV Alias runner / injection multi-espèces ajout/normalisé 0493w4–0493w8 double 0.0 pour gas; 1.0 pour liquid Définit massClosureStrengthDeclared de l’espèce de fond. Concerne le resampling; sans effet si resampling désactivé.');
INSERT INTO "search_fts_content" VALUES(563,'symbol:env:INJECT_TO_BACKGROUND_MASS_RATIO','SYMBOL','INJECT_TO_BACKGROUND_MASS_RATIO INJECT_TO_BACKGROUND_MASS_RATIO','ENV Alias runner / injection multi-espèces ajout/normalisé 0493w4–0493w8 double >0 100 liquid->gas; 0.01 gas->liquid; 10 sinon Fixe le rapport de masses particulaires injectée/fond et les masses cellulaires de référence dérivées. Ne pas confondre avec la fraction volumique; le masque Q6 utilise mass/referenceCellMass.');
INSERT INTO "search_fts_content" VALUES(564,'symbol:env:SCENARIO_EXPECTATION','SYMBOL','SCENARIO_EXPECTATION SCENARIO_EXPECTATION','ENV Alias runner / validation injection ajout/normalisé 0493w4–0493w8 empty|two_species cohérent avec INITIAL_DOMAIN_MODE Sélectionne le contrat du checker d’état et de diagnostic par espèce. ');
INSERT INTO "search_fts_content" VALUES(565,'symbol:env:POSTCHECK_SPECIES_ENABLE','SYMBOL','POSTCHECK_SPECIES_ENABLE POSTCHECK_SPECIES_ENABLE','ENV Alias runner / validation injection ajout/normalisé 0493w4–0493w8 booléen true Active le checker runtime par espèce après le run. Exige speciesDiagnosticsEnable=true.');
INSERT INTO "search_fts_content" VALUES(566,'symbol:env:REQUIRE_MIXED_CELL_AT_END','SYMBOL','REQUIRE_MIXED_CELL_AT_END REQUIRE_MIXED_CELL_AT_END','ENV Alias runner / validation injection ajout/normalisé 0493w4–0493w8 booléen false Exige au moins une cellule contenant les deux types à la fin. Exige speciesCellDiagnosticsEnable=true.');
INSERT INTO "search_fts_content" VALUES(567,'symbol:env:LIVE_PROGRESS','SYMBOL','LIVE_PROGRESS LIVE_PROGRESS LIVE_PROGRESS','ENV Alias runner / ergonomie | Runner qualification 0493x7i / progression ajout/normalisé 0493w4–0493w8 | profil final x7q/x7i booléen/int | booléen 1 Active l’affichage d’avancement des runs lorsque le runner commun le permet. | Contrôle le runner de qualification physique sans ajouter de clé backend propre. Modalité de travail recommandée pour les campagnes longues. | Variable de script x7i; le runner transmet ensuite les paramètres/gates canoniques appropriés par mode. Profil gelé pour éviter le retour à des cas Poiseuille pathologiques.');
INSERT INTO "search_fts_content" VALUES(568,'symbol:env:PREFLIGHT_ONLY','SYMBOL','PREFLIGHT_ONLY PREFLIGHT_ONLY PREFLIGHT_ONLY','ENV Alias runner / validation | Runner qualification 0493x7i / préflight ajout/normalisé 0493w4–0493w8 | profil final x7q/x7i booléen/int | booléen 0 Génère et valide les six branches sans exécuter les pas physiques. | Contrôle le runner de qualification physique sans ajouter de clé backend propre. Variable de script x7i; le runner transmet ensuite les paramètres/gates canoniques appropriés par mode. Profil gelé pour éviter le retour à des cas Poiseuille pathologiques.');
INSERT INTO "search_fts_content" VALUES(569,'symbol:env:CLEAN_RUN_ROOT','SYMBOL','CLEAN_RUN_ROOT CLEAN_RUN_ROOT CLEAN_RUN_ROOT','ENV Alias runner / gestion des résultats | Runner qualification 0493x7i / nettoyage campagne ajout/normalisé 0493w4–0493w8 | profil final x7q/x7i booléen/int | booléen 1 Supprime le run root avant une nouvelle campagne. | Contrôle le runner de qualification physique sans ajouter de clé backend propre. Mettre 0 pour ajouter des graines sans effacer les résultats existants. | Variable de script x7i; le runner transmet ensuite les paramètres/gates canoniques appropriés par mode. Profil gelé pour éviter le retour à des cas Poiseuille pathologiques.');
INSERT INTO "search_fts_content" VALUES(570,'symbol:env:ANALYZE_ONLY','SYMBOL','ANALYZE_ONLY ANALYZE_ONLY','ENV Alias runner / analyse ajout/normalisé 0493w4–0493w8 booléen/int 0 Réutilise les résultats existants et lance uniquement l’analyseur. Évite de recalculer les six branches après une correction du checker.');
INSERT INTO "search_fts_content" VALUES(571,'symbol:env:SEEDS','SYMBOL','SEEDS SEEDS','ENV Alias runner / ensemble statistique ajout/normalisé 0493w4–0493w8 liste d’entiers 493801 Liste des graines TG à exécuter ou analyser. Qualification finale: 493801 493802 493803.');
INSERT INTO "search_fts_content" VALUES(572,'symbol:env:SCENARIOS','SYMBOL','SCENARIOS SCENARIOS','ENV Alias runner / matrice TG ajout/normalisé 0493w4–0493w8 liste de noms mono_legacy mono_independent dual_identical Sélectionne les scénarios de qualification TG. ');
INSERT INTO "search_fts_content" VALUES(573,'symbol:env:PROJECTION_MOMENTUM_CORRECTION_ENABLE','SYMBOL','PROJECTION_MOMENTUM_CORRECTION_ENABLE PROJECTION_MOMENTUM_CORRECTION_ENABLE','ENV Alias runner / projection Q6 documenté 0493w8 booléen false dans 0493w8 Écrit projectionMomentumCorrectionEnable dans params.kv. Désactivé dans les branches Q6 historique et independent_masked afin de comparer le même opérateur sans patch uniforme de moment.');
INSERT INTO "search_fts_content" VALUES(574,'symbol:param:q6ForceProjectionMode','SYMBOL','q6ForceProjectionMode q6ForceProjectionMode q6ForceProjectionMode','PARAM Projection Q6 / séquencement du forçage ajout 0493x3; étendu x4; chemin Q6-g-f qualifié jusqu’à 0493x7q enum string legacy Choisit l’ordre force/Q6/streaming; prestream_single_fused projette la vitesse tentative incluant la force avant transport avec un seul solveur Q6 et fusion CUDA. legacy conserve l’ordre historique. prestream_single_fused est le chemin Q6-g-f qualifié sur TG, Poiseuille, bend/IO et dam-break; il inclut les sources déterministes (body/TG et, x7g, Darcy moyen) dans la vitesse tentative avant projection.');
INSERT INTO "search_fts_content" VALUES(575,'symbol:param:q6DensityRelaxationBeta','SYMBOL','q6DensityRelaxationBeta densityRelaxationBeta q6DensityRelaxationBeta q6DensityRelaxationBeta','PARAM Projection Q6-g-f / restauration de densité ajout 0493x7c; entrée legacy conservée; production x7q utilise tau_rho double 0.0 Coefficient de relaxation de densité par pas; impose div(u_proj)=beta*(rawFill-1)/dt dans le bulk liquide. Entrée par pas conservée pour ablation/compatibilité. La chaîne signed1/x7q utilise q6DensityRelaxationTime=0.25 et beta=0.');
INSERT INTO "search_fts_content" VALUES(576,'symbol:param:q6DensityRelaxationTime','SYMBOL','q6DensityRelaxationTime densityRelaxationTau densityRelaxationTime q6DensityRelaxationTime q6DensityRelaxationTime','PARAM Projection Q6-g-f / restauration de densité ajout 0493x7d; entrée physique recommandée; qualifiée signed1/x7q double 0.0 Constante de temps physique tau_rho de restauration de densité; impose div(u_proj)=(rawFill-1)/tau_rho dans le bulk liquide. Valeur de production qualifiée tau_rho=0.25. Avec le gate signé, la cible n’est appliquée qu’aux structures de défaut cohérentes; 0 désactive la restauration. Requiert CUDA Q6 actif; incompatible avec q6DensityRelaxationBeta>0.');
INSERT INTO "search_fts_content" VALUES(577,'symbol:param:q6DensityRelaxationCompressionGateEnable','SYMBOL','q6DensityRelaxationCompressionGateEnable densityRelaxationCompressionGateEnable q6DensityRelaxationCompressionGateEnable q6DensityRelaxationCompressionGateEnable','PARAM Projection Q6-g-f / restauration de densité signée ajout 0493x7d-v2; qualifié signed1/x7q booléen false Active l’admission cohérente de la branche positive: cellule et au moins un voisin de face au-dessus du seuil. Le gate ne soustrait pas le seuil après admission: le défaut complet rawFill-1 alimente la cible. Profil final x7i: true.');
INSERT INTO "search_fts_content" VALUES(578,'symbol:param:q6DensityRelaxationCompressionThresholdFill','SYMBOL','q6DensityRelaxationCompressionThresholdFill densityRelaxationCompressionThresholdFill q6DensityRelaxationCompressionThresholdFill q6DensityRelaxationCompressionThresholdFill','PARAM Projection Q6-g-f / restauration de densité signée ajout 0493x7d-v2; qualifié signed1/x7q double 0.0 Seuil du défaut positif de remplissage utilisé par le gate cohérent de compression. Les runners expriment le seuil en particules et écrivent thresholdParticles/gamma. Profil final: 3/gamma, soit 0.15 à gamma=20 et 0.30 à gamma=10.');
INSERT INTO "search_fts_content" VALUES(579,'symbol:param:q6DensityRelaxationTractionThresholdFill','SYMBOL','q6DensityRelaxationTractionThresholdFill densityRelaxationTractionThresholdFill q6DensityRelaxationTractionThresholdFill q6DensityRelaxationTractionThresholdFill','PARAM Projection Q6-g-f / restauration de densité signée ajout 0493x7d-v2-signed1; qualifié x7q double 0.0 Seuil en valeur absolue du défaut négatif pour la branche cohérente de traction/déplétion. Profil final: 6/gamma, soit 0.30 à gamma=20 et 0.60 à gamma=10.');
INSERT INTO "search_fts_content" VALUES(580,'symbol:param:q6DensityRelaxationTractionGain','SYMBOL','q6DensityRelaxationTractionGain densityRelaxationTractionGain q6DensityRelaxationTractionGain q6DensityRelaxationTractionGain','PARAM Projection Q6-g-f / restauration de densité signée ajout 0493x7d-v2-signed1; qualifié x7q double 0.0 Multiplie la cible négative admise par le gate de traction; 0 est un no-op exact de cette branche. Profil signed1/x7q qualifié: 1.0.');
INSERT INTO "search_fts_content" VALUES(581,'symbol:param:virialDensityKickEnable','SYMBOL','virialDensityKickEnable virialDensityKickEnable virialDensityKickEnable virialEnable','PARAM Projection Q6-g-f / fermeture virielle continuum 0493x7a–x7b ajout 0493x7a/x7b; omission d’inventaire corrigée 0493x7q booléen false Active le kick de densité viriel continuum avant/avec le chemin de projection Q6. Fermeture opt-in distincte de la restauration signed1. x7q est volontairement inactif lorsque ce kick est demandé.');
INSERT INTO "search_fts_content" VALUES(582,'symbol:param:kVirial','SYMBOL','kVirial Kvirial kVirial kVirial','PARAM Projection Q6-g-f / fermeture virielle continuum 0493x7a–x7b ajout 0493x7a/x7b; omission d’inventaire corrigée 0493x7q double 0.10666666666666667 Module continuum du terme de pression/accélération virielle associé au défaut de remplissage. Grandeur physique à ne pas rescaler avec Nx/Ny lors d’un raffinement à domaine physique fixé.');
INSERT INTO "search_fts_content" VALUES(583,'symbol:param:betaEOS','SYMBOL','betaEOS betaEOS betaEOS virialBeta','PARAM Projection Q6-g-f / fermeture virielle continuum 0493x7a–x7b ajout 0493x7a/x7b; omission d’inventaire corrigée 0493x7q double 0.05 Gain sans dimension de la fermeture EOS virielle continuum. Paramètre 0493x7b, désactivé physiquement tant que virialDensityKickEnable=false.');
INSERT INTO "search_fts_content" VALUES(584,'symbol:param:virialMomentumCorrectionEnable','SYMBOL','virialMomentumCorrectionEnable virialMomentumCorrectionEnable virialMomentumCorrectionEnable','PARAM Projection Q6-g-f / fermeture virielle continuum 0493x7a–x7b ajout 0493x7a/x7b; omission d’inventaire corrigée 0493x7q booléen true Active la correction globale de moment associée au kick viriel explicite. Distincte de la fermeture périodique x7q; x7q exclut le chemin virialDensityKickEnable.');
INSERT INTO "search_fts_content" VALUES(585,'symbol:param:surfaceTensionSigma','SYMBOL','surfaceTensionSigma q6GfSurfaceTensionSigma q6GfSurfaceTensionSigma surfaceTensionSigma surfaceTensionSigma','PARAM Q6-G-F — tension superficielle / interface 0493x9d actif; calibration mécanique x12yl + calibration dynamique séparée x12cal; utilisé JFM x12d | alias parser accepté de surfaceTensionSigma; actif double fini >= 0 0.0 Coefficient de tension superficielle utilisé dans le saut de Laplace p_A-p_B=sigma*kappa sur l’interface Q6-G-F. 0493x9d: saut de Laplace via phiGamma_cap=dt*sigma*kappa/rhoARef, sans force CSF/kick particulaire direct. État x12: distinguer strictement la calibration mécanique/statique x12yl (Young-Laplace apparié sigma>0/sigma=0 avec courbure mesurée) de la dispersion dynamique des ondes x12cal. Le script x12yl définit sigma_eff comme propriété mécanique scalaire; la dispersion capillaire n''est pas à replier automatiquement dans une renormalisation unique de sigma. Le benchmark JFM x12d écrit directement surfaceTensionSigma depuis SIGMA_ACTIVE. | Alias parser exact. Même physique et mêmes distinctions x12yl (mécanique/statique) vs x12cal (dynamique) que surfaceTensionSigma.');
INSERT INTO "search_fts_content" VALUES(586,'symbol:param:surfaceTensionMinRadiusCells','SYMBOL','surfaceTensionMinRadiusCells q6GfSurfaceTensionMinRadiusCells q6GfSurfaceTensionMinRadiusCells surfaceTensionMinRadiusCells surfaceTensionMinRadiusCells','PARAM Q6-G-F — tension superficielle / interface 0493x9r actif; choix de campagne x12 (JFM/x12yl=4, x12cal=3) | alias parser accepté; choix de campagne x12 double fini >= 0 0.0 Rayon minimal résolu en cellules pour la courbure utilisée uniquement dans sigma*kappa. 0493x9r: kappaLimit=1/(N_R*min(dx,dy)); le clip agit sur la courbure utilisée dans sigma*kappa, pas sur le champ brut. Le défaut struct reste 0.0. Il n''existe plus de ''choix 3'' universel: x12b/x12c/x12d JFM et x12yl utilisent 4 par défaut; x12cal dynamique et certains anciens runners splash x12a utilisent 3.');
INSERT INTO "search_fts_content" VALUES(587,'symbol:param:phaseInterfaceASelector','SYMBOL','phaseInterfaceASelector capillaryPhaseASelector capillaryPhaseASelector phaseInterfaceASelector phaseInterfaceASelector','PARAM Q6-G-F — sélection de phases 0493x9g actif; x14k autorise paire liquide/gaz bilatérale sous gardes stricts | alias accepté | ajout 0493x9g string canonique family:liquid Sélectionne la phase A: côté alpha>=0.5, référence de masse, orientation A->B et espèce(s) projetée(s). Défaut struct family:liquid. Avec réflexion cinétique >0, la validation exige exactement une espèce A projetée. Les runners x12/JFM écrivent phaseInterfaceASelector=type:$LIQUID_TYPE. | 0493x14k: le mode bilatéral exige des sélecteurs explicites type:<id> pour A et B; A est le liquide projeté unique. | Audit x14ai-fix1 04/09/2026: sémantique params inchangée; aucune nouvelle clé params.kv introduite par x14y--x14ai-fix1. | Alias de phaseInterfaceASelector. 0493x9g: phase A doit sélectionner des espèces enregistrées avec masse de référence positive.');
INSERT INTO "search_fts_content" VALUES(588,'symbol:param:phaseInterfaceBSelector','SYMBOL','phaseInterfaceBSelector capillaryPhaseBSelector capillaryPhaseBSelector phaseInterfaceBSelector phaseInterfaceBSelector','PARAM Q6-G-F — sélection de phases 0493x9g actif; x14k autorise B=type:gaz lorsque phaseInterfaceKineticBilateralRelocation=true | alias accepté | ajout 0493x9g; wall opérationnel géométriquement x9h string canonique family:gas Sélectionne le côté extérieur B de l’interface; peut fournir la pression gaz x6g, être vacuum, ou demander le provider géométrique wall. Défaut struct family:gas. La garde historique x9t B=vacuum reste vraie lorsque la réflexion cinétique est active et phaseInterfaceKineticBilateralRelocation=false. x14k lève explicitement cette restriction pour une espèce gaz B unique non projetée, avec r=1 et sélecteurs type:<id>. | Audit x14ai-fix1 04/09/2026: sémantique params inchangée; aucune nouvelle clé params.kv introduite par x14y--x14ai-fix1. | Alias de phaseInterfaceBSelector. 0493x9g/x9h: B=vacuum est opérationnel sans particules gaz. B=wall est géométrie seule et ne doit pas être utilisé comme paire capillaire de mouillage; le mur est alors un troisième objet.');
INSERT INTO "search_fts_content" VALUES(589,'symbol:param:phaseInterfaceContactAngleDegrees','SYMBOL','phaseInterfaceContactAngleDegrees capillaryContactAngleDegrees capillaryContactAngleDegrees contactAngleDegrees contactAngleDegrees phaseInterfaceContactAngleDegrees phaseInterfaceContactAngleDegrees','PARAM Q6-G-F — mouillage 0493x9i/x9m actif; x12 splash/JFM=90°, calibrateurs capillaires=-1 | alias accepté | ajout 0493x9i; fermeture statique x9m qualifiée | alias accepté | ajout 0493x9i; fermeture statique x9m qualifiée double fini -1.0 Prescrit l’angle de contact mesuré à travers A, avec nAB·nWall=-cos(thetaA). Défaut struct -1 (désactivé). Les splash/JFM x12 utilisent 90° avec x9m off-support; x12cal et x12yl désactivent le mouillage pour les calibrations capillaires. | Alias de phaseInterfaceContactAngleDegrees. x9i introduit le contrat. x9m est la fermeture statique préférée actuelle via ancre hors support; dynamique de ligne triple non encore quantitativement qualifiée. La garde actuelle exige surfaceTensionSigma>0 lorsqu’un angle est actif. | Alias de phaseInterfaceContactAngleDegrees. x9i introduit le contrat. x9m est la fermeture statique préférée actuelle via ancre hors support; dynamique de ligne triple non encore quantitativement qualifiée. La garde actuelle exige surfaceTensionSigma>0 lorsqu’un angle est actif.');
INSERT INTO "search_fts_content" VALUES(590,'symbol:param:phaseInterfaceKineticReflectionFraction','SYMBOL','phaseInterfaceKineticReflectionFraction KINETIC_REFLECTION_FRACTION (alias runner) kineticReflectionFraction (alias parser) phaseInterfaceKineticReflectionFraction phaseInterfaceKineticReflectionFraction','PARAM Q6-G-F — interface cinétique / évaporation 0493x9t actif; production x12 r=1; x14k bilatéral liquide/gaz exige r=1 double fini 0.0 (SimulationParams); runners x12 production fixent 1.0 Probabilité de réfléchir une tentative de franchissement sortante relative g=(v-uGamma)·n>0; 1-r ouvre la voie de transmission/évaporation. Correction importante: le défaut du struct est 0.0, pas 1.0. x10o et la chaîne CIC/Q2/x10u/x10v/x12a ne deviennent actifs que dans le chemin cinétique Q6 free_surface_masked; x10o exige en plus r>=1. La production x12 verrouille r=1. | Audit commit 7655b81: alias parser présent et couvert; aucune clé canonique supplémentaire requise. | 0493x14k: B explicite gaz est autorisé uniquement via le gate bilatéral; ce chemin impose r=1 et interdit une cible d’évaporation active. | Audit x14ai-fix1 04/09/2026: sémantique params inchangée; aucune nouvelle clé params.kv introduite par x14y--x14ai-fix1. | Correction importante: le défaut du struct est 0.0, pas 1.0. x10o et la chaîne CIC/Q2/x10u/x10v/x12a ne deviennent actifs que dans le chemin cinétique Q6 free_surface_masked; x10o exige en plus r>=1. La production x12 verrouille r=1. | Audit commit 7655b81: aliases parser kineticReflectionFraction/evaporationTargetType présents et couverts; aucune clé canonique supplémentaire requise. | Audit commit 7655b81: alias parser présent et couvert; aucune clé canonique supplémentaire requise. | 0493x14k: B explicite gaz est autorisé uniquement via le gate bilatéral; ce chemin impose r=1 et interdit une cible d’évaporation active. | Audit x14ai-fix1 04/09/2026: sémantique params inchangée; aucune nouvelle clé params.kv introduite par x14y--x14ai-fix1.');
INSERT INTO "search_fts_content" VALUES(591,'symbol:param:phaseInterfaceEvaporationTargetType','SYMBOL','phaseInterfaceEvaporationTargetType EVAPORATION_TARGET_TYPE (alias runner) evaporationTargetType (alias parser) phaseInterfaceEvaporationTargetType phaseInterfaceEvaporationTargetType','PARAM Q6-G-F — interface cinétique / évaporation 0493x9t actif; production x12=-1; transfert r<1 non qualifié thermodynamiquement entier / identifiant de type particulaire -1 (SimulationParams et runners x12) Type cible optionnel associé aux particules transmises par la loi cinétique lorsque r<1. Avec r=1 dans la chaîne x12, ce paramètre n''entraîne aucun changement de phase. Le chemin >=0 appartient au mécanisme historique r<1 et ne constitue pas une loi d''évaporation/condensation thermodynamiquement qualifiée. | Audit commit 7655b81: alias parser présent et couvert; aucune clé canonique supplémentaire requise. | 0493x14k: le couplage bilatéral liquide/gaz courant interdit phaseInterfaceEvaporationTargetType>=0. | Avec r=1 dans la chaîne x12, ce paramètre n''entraîne aucun changement de phase. Le chemin >=0 appartient au mécanisme historique r<1 et ne constitue pas une loi d''évaporation/condensation thermodynamiquement qualifiée. | Audit commit 7655b81: aliases parser kineticReflectionFraction/evaporationTargetType présents et couverts; aucune clé canonique supplémentaire requise. | Audit commit 7655b81: alias parser présent et couvert; aucune clé canonique supplémentaire requise. | 0493x14k: le couplage bilatéral liquide/gaz courant interdit phaseInterfaceEvaporationTargetType>=0.');
INSERT INTO "search_fts_content" VALUES(592,'symbol:param:speciesThermostatEnable','SYMBOL','speciesThermostatEnable speciesThermostatEnable speciesThermostatEnable','PARAM Thermostat — multi-espèces x14 ajout 0493x14a; actif dans la chaîne liquide/gaz x14 booléen false Conserve la collision SRC commune au mélange mais applique ensuite une remise à température séparée par type enregistré. | Champ SimulationParams activant le thermostat séparé par espèce. Opt-in; false préserve le chemin thermostat all-fluid historique. En CUDA résident, le workspace cellulaire est réutilisé successivement par espèce. | Audit x14ai-fix1 04/09/2026: sémantique params inchangée; aucune nouvelle clé params.kv introduite par x14y--x14ai-fix1. | Défaut false pour non-régression. | Audit x14ai-fix1 04/09/2026: sémantique params inchangée; aucune nouvelle clé params.kv introduite par x14y--x14ai-fix1.');
INSERT INTO "search_fts_content" VALUES(593,'symbol:param:speciesDefinitions[K].thermostatTargetKBT','SYMBOL','speciesDefinitions[K].thermostatTargetKBT species0ThermostatTargetKBT … speciesN-1ThermostatTargetKBT speciesKThermostatTargetKBT','PARAM Thermostat — multi-espèces x14 ajout 0493x14a; famille dynamique K=0…speciesCount-1 double négatif => hérite de thermostatTargetKBT puis kBT Cible thermique propre à l’espèce K. Clé dynamique détectée par parse_species_thermostat_target_key; ne fait pas partie du décompte des clés littérales directes du parseur. | Audit x14ai-fix1 04/09/2026: sémantique params inchangée; aucune nouvelle clé params.kv introduite par x14y--x14ai-fix1.');
INSERT INTO "search_fts_content" VALUES(594,'symbol:param:speciesDefinitions[K].resamplingEnable','SYMBOL','speciesDefinitions[K].resamplingEnable species0ResamplingEnable … speciesN-1ResamplingEnable speciesKResamplingEnable','PARAM Multi-espèces — registre famille dynamique existante, explicitée dans l’inventaire x14 booléen true pour chaque déclaration Active/désactive le resampling pour l’espèce K. Famille dynamique déjà documentée dans le commentaire de SimulationParams mais auparavant seulement implicite dans la ligne speciesK.');
INSERT INTO "search_fts_content" VALUES(595,'symbol:param:phaseInterfaceKineticBilateralRelocation','SYMBOL','phaseInterfaceKineticBilateralRelocation phaseInterfaceKineticBilateralRelocation phaseInterfaceKineticBilateralRelocation','PARAM Q6-G-F — interface cinétique liquide/gaz x14 ajout 0493x14k; actif dans la chaîne liquide/gaz x14 | ajout 0493x14k booléen false Étend la relocalisation positionnelle x10u à une paire liquide/gaz explicite avec sens de phase inversé pour B. | Champ SimulationParams du gate bilatéral x14k. Ne modifie à lui seul ni vitesse, ni masse, ni type. false conserve exactement la garde liquide/vide historique. | Audit x14ai-fix1 04/09/2026: sémantique params inchangée; aucune nouvelle clé params.kv introduite par x14y--x14ai-fix1. | Défaut false pour préserver le chemin liquide/vide. | Audit x14ai-fix1 04/09/2026: sémantique params inchangée; aucune nouvelle clé params.kv introduite par x14y--x14ai-fix1.');
INSERT INTO "search_fts_content" VALUES(596,'symbol:env:CASES','SYMBOL','CASES CASES','ENV Runner qualification 0493x7i / sélection de cas profil final x7q/x7i liste/chaîne tg poiseuille bend_pipe io_box Contrôle le runner de qualification physique sans ajouter de clé backend propre. Variable de script x7i; le runner transmet ensuite les paramètres/gates canoniques appropriés par mode. Profil gelé pour éviter le retour à des cas Poiseuille pathologiques.');
INSERT INTO "search_fts_content" VALUES(597,'symbol:env:DENSITY_RELAXATION_TIME','SYMBOL','DENSITY_RELAXATION_TIME DENSITY_RELAXATION_TIME','ENV Alias runner de qualification 0493x7d/x7e historique x7d/x7e; valeur reprise dans profil x7q double >0 0.25 Contrôle tau_rho des anciens runners de raffinement. Variable de script historique; la qualification x7i utilise X7I_Q6_GF_DENSITY_RELAXATION_TIME et le helper Q6_GF_DENSITY_RELAXATION_TIME.');
INSERT INTO "search_fts_content" VALUES(598,'symbol:env:DROP_CENTER_X','SYMBOL','DROP_CENTER_X DROP_CENTER_X','ENV Alias runner — splash x9s ajout 0493x9s double dans domaine centre du domaine en x Position initiale x du centre de goutte. Doit laisser une marge compatible avec le rayon et l’étalement attendu.');
INSERT INTO "search_fts_content" VALUES(599,'symbol:env:DROP_CENTER_Y','SYMBOL','DROP_CENTER_Y DROP_CENTER_Y','ENV Alias runner — splash x9s ajout 0493x9s double dans domaine 1.25 pour le domaine x9s par défaut Position initiale y du centre de goutte. Doit placer la goutte au-dessus de la cible sans intersection initiale non désirée.');
INSERT INTO "search_fts_content" VALUES(600,'symbol:env:DROP_RADIUS_CELLS','SYMBOL','DROP_RADIUS_CELLS DROP_RADIUS_CELLS','ENV Alias runner — splash x9s ajout 0493x9s double >0 40 Rayon initial de la goutte en nombre de cellules. Avec h=1/256, le default donne R=40h.');
INSERT INTO "search_fts_content" VALUES(601,'symbol:env:DROP_VX','SYMBOL','DROP_VX DROP_VX','ENV Alias runner — splash x9s ajout 0493x9s double 0 Vitesse initiale horizontale de la goutte. Paramètre cinématique du cas initial.');
INSERT INTO "search_fts_content" VALUES(602,'symbol:env:DROP_VY','SYMBOL','DROP_VY DROP_VY','ENV Alias runner — splash x9s ajout 0493x9s double -0.35 Vitesse initiale verticale de la goutte. Contrôle principalement l’inertie d’impact et le nombre de Weber du cas x9s.');
INSERT INTO "search_fts_content" VALUES(603,'symbol:env:EVAPORATION_TARGET_TYPE','SYMBOL','EVAPORATION_TARGET_TYPE EVAPORATION_TARGET_TYPE','ENV Alias runner — interface cinétique / évaporation runner alias courant; production x12 = -1 entier -1 (runners x12 et SimulationParams) Surcharge phaseInterfaceEvaporationTargetType. Avec r=1 dans la chaîne x12 actuelle, aucun passage d''évaporation n''est utilisé. Si >=0 avec r>0, le type doit être enregistré, non projeté et distinct de A.');
INSERT INTO "search_fts_content" VALUES(604,'symbol:env:GAMMA','SYMBOL','GAMMA GAMMA','ENV Validateurs CUDA resampling — population lecture C++ directe dans validateurs shadow; également variable shell courante des runners entier >0 20 Occupation moyenne gamma utilisée par les exécutables de validation CUDA resampling shadow. La lecture getenv directe identifiée dans le C++ est limitée aux exécutables de validation CUDA resampling shadow. Le même nom est aussi utilisé comme variable shell par de nombreux runners qui l''écrivent ensuite dans les paramètres; ne pas le confondre avec un getenv du binaire de production.');
INSERT INTO "search_fts_content" VALUES(605,'symbol:env:GAS_PRESSURE_CONSTANT','SYMBOL','GAS_PRESSURE_CONSTANT GAS_PRESSURE_CONSTANT','ENV Alias script 0493x6g ajout runner 0493x6g double fini GAS_PRESSURE_REFERENCE Alias du runner vers MPCD_Q6_PHASE_GAS_PRESSURE_CONSTANT_0493X6G. Utilisé principalement dans le test de jauge à pression uniforme.');
INSERT INTO "search_fts_content" VALUES(606,'symbol:env:GAS_PRESSURE_MODE','SYMBOL','GAS_PRESSURE_MODE GAS_PRESSURE_MODE','ENV Alias script 0493x6g ajout runner 0493x6g enum string eos Alias du runner vers MPCD_Q6_PHASE_GAS_PRESSURE_MODE_0493X6G. eos pour le cas physique; constant pour validation de jauge.');
INSERT INTO "search_fts_content" VALUES(607,'symbol:env:GAS_PRESSURE_REFERENCE','SYMBOL','GAS_PRESSURE_REFERENCE GAS_PRESSURE_REFERENCE','ENV Alias script 0493x6g ajout runner 0493x6g double fini pression EOS uniforme initiale Alias du runner vers MPCD_Q6_PHASE_GAS_PRESSURE_REFERENCE_0493X6G. Le runner calcule par défaut gamma*kBT/Acell.');
INSERT INTO "search_fts_content" VALUES(608,'symbol:env:GAS_PRESSURE_SCALE','SYMBOL','GAS_PRESSURE_SCALE GAS_PRESSURE_SCALE','ENV Alias script 0493x6g ajout runner 0493x6g double >= 0 1.0 Alias du runner vers MPCD_Q6_PHASE_GAS_PRESSURE_SCALE_0493X6G. 0 active le null-path de validation; 1 mode nominal.');
INSERT INTO "search_fts_content" VALUES(609,'symbol:env:GRID_CASES','SYMBOL','GRID_CASES GRID_CASES','ENV Validateurs CUDA resampling — entrée de test présent code; ajouté consolidation 0493w8 liste/chaîne de cas défini par le validateur Sélectionne les cas de grille exécutés par plusieurs binaires de validation du resampling CUDA. Variable de validateur, pas une option du solveur de production et ne se place pas dans params.kv.');
INSERT INTO "search_fts_content" VALUES(610,'symbol:env:KINETIC_REFLECTION_FRACTION','SYMBOL','KINETIC_REFLECTION_FRACTION KINETIC_REFLECTION_FRACTION','ENV Alias runner — interface cinétique / évaporation runner alias courant; production x12 = 1.0 double [0,1] 1.0 dans runners x12 de production; défaut SimulationParams=0.0 Surcharge phaseInterfaceKineticReflectionFraction. Avec r>0, la validation Params impose speciesQ6Mode=free_surface_masked, q6ForceProjectionMode=prestream_single_fused, B=vacuum et exactement une espèce A projetée. x10o n''est actif que pour r>=1; r<1 bascule sur le chemin cinétique historique.');
INSERT INTO "search_fts_content" VALUES(611,'symbol:env:MPCD_BACKEND','SYMBOL','MPCD_BACKEND MPCD_BACKEND','ENV Backend principal principal utilisateur string cuda dans scripts/run_src_mpcd_cuda_primary_0275.sh; openmp si demandé explicitement Choisit le lanceur primaire cuda/openmp. Ne se place pas dans params.kv; à passer dans l’environnement du shell ou dans les scripts de validation/démo.');
INSERT INTO "search_fts_content" VALUES(612,'symbol:env:MPCD_CUDA_ACTIVE_PREFIX_ASSUME_NO_HOST_CONSUMERS_0315D','SYMBOL','MPCD_CUDA_ACTIVE_PREFIX_ASSUME_NO_HOST_CONSUMERS_0315D MPCD_CUDA_ACTIVE_PREFIX_ASSUME_NO_HOST_CONSUMERS_0315D','ENV CUDA état résident / active-prefix — audit et compatibilité présent état 36abd23; inventorié 0490p (0315d) booléen/env truthy false/off Déclare qu’aucun consommateur hôte n’exige l’état complet; option experte potentiellement unsafe. À passer dans l’environnement du shell, pas dans params.kv. Ligne ajoutée par comparaison exhaustive des appels getenv du code courant avec l’inventaire 0436b.');
