INSERT INTO "search_fts_content" VALUES(649,'symbol:env:MPCD_CUDA_CLASSIC_SRC_RESIDENT_0271_ASYNC_STREAM','SYMBOL','MPCD_CUDA_CLASSIC_SRC_RESIDENT_0271_ASYNC_STREAM MPCD_CUDA_CLASSIC_SRC_RESIDENT_0271_ASYNC_STREAM','ENV Autres variables internes réglage performance/interne | propagé scripts Darcy 0426 booléen/env truthy sauf mention contraire false/off sauf activation par scripts validés Variable interne de contrôle du backend CUDA. Ne se place pas dans params.kv; à passer dans l’environnement du shell ou dans les scripts de validation/démo. | 0426 : intégré au bloc fastflags Darcy pour éviter le backend collision/thermostat lent dans les cas chi/segments.');
