INSERT INTO "search_fts_content" VALUES(1006,'symbol:env:RUN_ROOT','SYMBOL','RUN_ROOT RUN_ROOT','ENV Runner qualification 0493x7i / racine de sortie profil final x7q/x7i chaîne chemin runs/0493x7q_q6_g_f_physical_qualification Contrôle le runner de qualification physique sans ajouter de clé backend propre. Variable de script x7i; le runner transmet ensuite les paramètres/gates canoniques appropriés par mode. Profil gelé pour éviter le retour à des cas Poiseuille pathologiques.');
INSERT INTO "search_fts_content" VALUES(1007,'symbol:env:RUN_ZERO_REFERENCE','SYMBOL','RUN_ZERO_REFERENCE RUN_ZERO_REFERENCE','ENV Alias script 0493x6g final ajout runner 0493x6g booléen/int 0|1 1 Contrôle l’exécution de la référence appariée pGamma=0 dans le runner dam-break final. Mettre 0 pour relancer seulement le cas EOS, notamment lors d’une inspection LiveVis après qu’une référence existe déjà.');
INSERT INTO "search_fts_content" VALUES(1008,'symbol:env:SEED','SYMBOL','SEED SEED','ENV Validateurs CUDA resampling — reproductibilité lecture C++ directe dans validateurs shadow; également variable shell courante des runners uint64 1628638 Seed des exécutables de validation CUDA resampling shadow. La lecture getenv directe identifiée dans le C++ est limitée aux exécutables de validation CUDA resampling shadow. Le même nom est aussi utilisé comme variable shell par de nombreux runners qui l''écrivent ensuite dans les paramètres; ne pas le confondre avec un getenv du binaire de production.');
INSERT INTO "search_fts_content" VALUES(1009,'symbol:env:SIGMA_ACTIVE','SYMBOL','SIGMA_ACTIVE SIGMA_ACTIVE','ENV Alias runner — tension superficielle runner alias courant; x12 splash/JFM double >=0 dépend du runner; x12b/x12c/x12d JFM: 392.149185; x12a splash: campagne-dépendant Surcharge surfaceTensionSigma dans les runners capillaires/splash/JFM. Alias de runner, pas un champ C++ autonome. Dans le cas JFM x12d, la valeur par défaut est 392.149185 (campagne We≈514). Les calibrateurs x12cal/x12yl utilisent plutôt SIGMA_DECLARED et écrivent surfaceTensionSigma.');
INSERT INTO "search_fts_content" VALUES(1010,'symbol:env:SPECIES_Q6_MIN_FILL_FRACTION','SYMBOL','SPECIES_Q6_MIN_FILL_FRACTION SPECIES_Q6_MIN_FILL_FRACTION','ENV Alias script 0493x surface libre ajout runner 0493x5a; réutilisé x5b–x7e double [0,1] 0.25 dans les premiers runners x5/x6; 0.10 dans les qualifications Q6-g-f x7d/x7e Alias shell écrit speciesQ6MinOccupancyFraction dans params.kv. Alias shell écrit speciesQ6MinOccupancyFraction dans params.kv. Pour free_surface_masked, seuil de support absolu liquide; distinct de l’interface physique alpha=0.5.');
INSERT INTO "search_fts_content" VALUES(1011,'symbol:env:SRC_FILTERED_FIELD_RECORDING_0432','SYMBOL','SRC_FILTERED_FIELD_RECORDING_0432 SRC_FILTERED_FIELD_RECORDING_0432','ENV Filtered field recording 0432a ajout 0432a booléen/env truthy false/off Alias SRC_* pour activer le recorder observation-only de champs filtrés. Même rôle que MPCD_FILTERED_FIELD_RECORDING_0432; utile dans les scripts livevis SRC.');
INSERT INTO "search_fts_content" VALUES(1012,'symbol:env:SRC_FILTERED_FIELD_RECORD_EVERY','SYMBOL','SRC_FILTERED_FIELD_RECORD_EVERY SRC_FILTERED_FIELD_RECORD_EVERY','ENV Filtered field recording 0432a ajout 0432a | mis à jour 0433a entier > 0 si présent absent par défaut; sinon override explicite Override expert de la cadence d’écriture des dumps filtrés. Si absent, recordEvery suit liveEvery. 0433a: n’est plus nécessaire pour obtenir une cadence d’enregistrement; le comportement par défaut est WYSIWYR avec recordEvery=liveEvery. Une valeur env >0 force recordEverySource=override.');
INSERT INTO "search_fts_content" VALUES(1013,'symbol:env:SRC_FILTERED_FIELD_RECORD_FIELDS','SYMBOL','SRC_FILTERED_FIELD_RECORD_FIELDS SRC_FILTERED_FIELD_RECORD_FIELDS','ENV Filtered field recording 0432a ajout 0432a liste CSV de champs current Initialise la liste des champs à enregistrer. Exemples: current,ux,uy,rho,Y1. La clé control-file recordFields peut surcharger avant session.');
