INSERT INTO "search_fts_content" VALUES(1017,'symbol:env:SRC_GPU_WALL_CIRCLE_RESIDENT_0318','SYMBOL','SRC_GPU_WALL_CIRCLE_RESIDENT_0318 SRC_GPU_WALL_CIRCLE_RESIDENT_0318','ENV Alias script / sécurité VK ajout scripts 0331 booléen/env truthy false/off Alias de script pour documenter/désactiver le chemin 0318. Ne remplace pas le garde UNSAFE. Préférer MPCD_CUDA_CLASSIC_SRC_WALL_CIRCLE_RESIDENT_0318=0 dans les scripts. | 0338c: le chemin performant validé est 0318 + MPCD_CUDA_CLASSIC_SRC_WALL_CIRCLE_RESIDENT_MINIMAL_DOWNLOAD_0338=1; 0318 seul reste à traiter comme chemin historique/quarantainé selon scripts.');
