INSERT INTO "search_fts_content" VALUES(1086,'symbol:env:MPCD_X14L_GAS_SPECULAR_REFLECTION','SYMBOL','MPCD_X14L_GAS_SPECULAR_REFLECTION MPCD_X14L_GAS_SPECULAR_REFLECTION','ENV Interface liquide/gaz x14 ajout 0493x14l; actif dans la chaîne x14m+ booléen entier 0/1 0 Active la réflexion spéculaire du gaz B sur la paroi cinétique liquide; composante normale relative réfléchie, tangentielle inchangée. Requiert phaseInterfaceKineticBilateralRelocation=true. Le liquide A conserve x10u; le chemin gaz préserve la vitesse spéculaire au lieu de la faire écraser par la relocalisation positionnelle.');
INSERT INTO "search_fts_content" VALUES(1087,'symbol:env:MPCD_X14V_GAS_KINETIC_EXCESS_KICK','SYMBOL','MPCD_X14V_GAS_KINETIC_EXCESS_KICK MPCD_X14V_GAS_KINETIC_EXCESS_KICK','ENV Interface liquide/gaz x14 ajout 0493x14v; qualifié sur impact normal et actif dans x14w booléen entier 0/1 0 Transfère collectivement au liquide l’impulsion normale réelle des réflexions gazeuses moins la traction thermodynamique déjà représentée par x6g. Requiert x6g actif, x10o+CIC+Q2+x10u+x10v, géométrie bilatérale et x14l. Réutilise les stockages x9t/x10m, aucun buffer résident permanent et aucune nouvelle passe O(Np); lois liquides inchangées.');
INSERT INTO "search_fts_content" VALUES(1088,'symbol:env:SPECIES_THERMOSTAT_ENABLE','SYMBOL','SPECIES_THERMOSTAT_ENABLE SPECIES_THERMOSTAT_ENABLE','ENV Runner x14 — thermostat alias de runner x14 booléen 0/1 ou true/false 1 dans les runners biphasés x14 Écrit speciesThermostatEnable dans params.kv. Alias de script; la physique canonique est le paramètre params.kv speciesThermostatEnable.');
INSERT INTO "search_fts_content" VALUES(1089,'symbol:env:LIQUID_KBT','SYMBOL','LIQUID_KBT LIQUID_KBT','ENV Runner x14 — propriétés de phase paramètre visible des runners x14 double >0 dépend du benchmark; Couette x14w: 0.02 Cible thermique de la phase liquide; écrite dans species0ThermostatTargetKBT selon le mapping de types. Alias runner, non lu directement par le C++.');
INSERT INTO "search_fts_content" VALUES(1090,'symbol:env:GAS_KBT','SYMBOL','GAS_KBT GAS_KBT','ENV Runner x14 — propriétés de phase paramètre visible des runners x14 double >0 dépend du benchmark; Couette x14w: 0.08 Cible thermique du gaz et température de référence du mécanisme de paroi gaz; écrite dans la déclaration thermostat de l’espèce gaz. Les runners x14 utilisant l’EOS x6g alignent aussi la température globale utilisée par cette fermeture sur la cible gaz.');
INSERT INTO "search_fts_content" VALUES(1091,'symbol:env:PHASE_INTERFACE_KINETIC_BILATERAL_RELOCATION','SYMBOL','PHASE_INTERFACE_KINETIC_BILATERAL_RELOCATION PHASE_INTERFACE_KINETIC_BILATERAL_RELOCATION','ENV Runner x14 — interface alias conceptuel / écriture params x14k booléen true dans les runners liquide/gaz x14k+ Écrit phaseInterfaceKineticBilateralRelocation=true dans params.kv. La plupart des runners x14 écrivent directement la clé params plutôt que de dépendre de cet alias.');
INSERT INTO "search_fts_content" VALUES(1092,'symbol:env:X6G_MODE','SYMBOL','X6G_MODE X6G_MODE','ENV Runner x14 — pression gaz alias d’ablation/qualification x14u enum string selon benchmark Sélectionne côté runner le mode x6g à exporter vers MPCD_Q6_PHASE_GAS_PRESSURE_MODE_0493X6G. Utilisé pour comparer constant et eos_accessible_volume sans modifier le backend.');
INSERT INTO "search_fts_content" VALUES(1093,'symbol:env:WALL_SPEED','SYMBOL','WALL_SPEED WALL_SPEED','ENV Runner x14w — Couette paramètre physique visible du benchmark x14w double fini non nul 0.02 dans le runner; campagne de qualification renforcée: 0.075 Impose wallUxBottom=-WALL_SPEED et wallUxTop=+WALL_SPEED. La campagne à 0.075 augmente le rapport signal/bruit sans changer la chaîne physique.');
INSERT INTO "search_fts_content" VALUES(1094,'symbol:env:MPCD_X14V_SUBTRACT_X6G_THERMODYNAMIC_TRACTION','SYMBOL','MPCD_X14V_SUBTRACT_X6G_THERMODYNAMIC_TRACTION MPCD_X14V_SUBTRACT_X6G_THERMODYNAMIC_TRACTION','ENV Interface liquide/gaz x14v — séparation thermo/cinétique ajout 0493x14y; production x14v/x14ai-fix1 = 1 booléen entier 0/1 1 Soustrait de l’impulsion brute de réflexion gazeuse la traction thermodynamique déjà représentée par x6g; à 0, x14v transfère J_raw sans soustraction. Le défaut 1 est la sémantique physique retenue. La valeur 0 est l’ablation x14y et n’est pas un mode de production.');
INSERT INTO "search_fts_content" VALUES(1095,'symbol:env:MPCD_X14V_REFERENCE_PRESSURE_GEOMETRIC_CLOSURE','SYMBOL','MPCD_X14V_REFERENCE_PRESSURE_GEOMETRIC_CLOSURE MPCD_X14V_REFERENCE_PRESSURE_GEOMETRIC_CLOSURE','ENV Interface liquide/gaz x14z — prototype de résultante prototype x14z rejeté; OFF production booléen entier 0/1 0 Projette la contribution uniforme p_ref reconstruite sur la polyligne x10n vers une résultante globale nulle, sans modifier la partie de jauge. 24 octets de scratch, aucune nouvelle passe/kernel. N’explique pas le défaut n=1 observé; incompatible avec les modes x14aa–x14ad et requis OFF par x14ai.');
INSERT INTO "search_fts_content" VALUES(1096,'symbol:env:MPCD_X14V_X6G_FACE_THERMO_TRACTION','SYMBOL','MPCD_X14V_X6G_FACE_THERMO_TRACTION MPCD_X14V_X6G_FACE_THERMO_TRACTION','ENV Interface liquide/gaz x14aa — prototype de traction prototype x14aa non retenu; OFF production booléen entier 0/1 0 Évalue toute la traction thermodynamique absolue sur les faces x6f/x6g représentées et la disperse vers le liquide via les buffers CIC x14v. Déplace aussi le grand terme uniforme p_ref de la géométrie x10n/CIC vers les faces Q6; mode mutuellement exclusif avec x14ab/x14ac/x14ad.');
INSERT INTO "search_fts_content" VALUES(1097,'symbol:env:MPCD_X14V_X6G_GAUGE_FACE_THERMO_TRACTION','SYMBOL','MPCD_X14V_X6G_GAUGE_FACE_THERMO_TRACTION MPCD_X14V_X6G_GAUGE_FACE_THERMO_TRACTION','ENV Interface liquide/gaz x14ab — prototype hybride prototype x14ab non retenu; OFF production booléen entier 0/1 0 Conserve p_ref sur les segments x10n/CIC mais soustrait la seule pression de jauge p_g-p_ref sur les faces x6g représentées. Séparation référence/jauge plus cohérente que x14aa mais traction de jauge encore portée par les normales axiales des faces Q6; mode mutuellement exclusif avec x14aa/x14ac/x14ad.');
INSERT INTO "search_fts_content" VALUES(1098,'symbol:env:MPCD_X14V_X6G_GAUGE_RESULTANT_PROJECTION','SYMBOL','MPCD_X14V_X6G_GAUGE_RESULTANT_PROJECTION MPCD_X14V_X6G_GAUGE_RESULTANT_PROJECTION','ENV Interface liquide/gaz x14ac — projection de résultante prototype x14ac supplanté par x14ad; OFF production booléen entier 0/1 0 Conserve la traction locale x10n et impose à sa pression de jauge la résultante globale des faces x6g par correction minimum-L2 delta p_s=m_s·lambda. Utilise un scratch de 7 doubles sans nouvelle passe. Le principe de projection est conservé dans x14ad, qui améliore l’association locale pression/segment.');
INSERT INTO "search_fts_content" VALUES(1099,'symbol:env:MPCD_X14V_X6G_LOCAL_FACE_GAUGE_PROJECTION','SYMBOL','MPCD_X14V_X6G_LOCAL_FACE_GAUGE_PROJECTION MPCD_X14V_X6G_LOCAL_FACE_GAUGE_PROJECTION','ENV Interface liquide/gaz x14ad — traction locale retenue retenu x14ad; prérequis x14ai-fix1 pour composante liquide fermée booléen entier 0/1 0 Échantillonne la pression de jauge sur les faces x6g qui terminent chaque segment x10n, applique cette pression sur la normale x10n, puis corrige la résultante résiduelle par projection minimum-L2. Réutilise le scratch 7 doubles x14ac et l’octet/cellule x10m pour les ids d’arêtes; aucune nouvelle passe/buffer O(N). Mutuellement exclusif avec x14aa/x14ab/x14ac. Doit être 1 lorsque x14ai est actif.');
INSERT INTO "search_fts_content" VALUES(1100,'symbol:env:MPCD_X14V_SCATTER_LOSS_DIAGNOSTIC','SYMBOL','MPCD_X14V_SCATTER_LOSS_DIAGNOSTIC MPCD_X14V_SCATTER_LOSS_DIAGNOSTIC','ENV Interface liquide/gaz x14ae — diagnostic diagnostic x14ae uniquement; OFF production booléen entier 0/1 0 Cumule le nombre et l’impulsion des kicks x14v valides qui ne trouvent aucun support liquide après CIC puis fallback jusqu’au rayon 2. 3 doubles/24 octets; aucun changement de physique. Le cas discriminant a donné zéro perte terminale et a innocenté le scatter.');
INSERT INTO "search_fts_content" VALUES(1101,'symbol:env:MPCD_X14V_GLOBAL_BALANCE_DIAGNOSTIC','SYMBOL','MPCD_X14V_GLOBAL_BALANCE_DIAGNOSTIC MPCD_X14V_GLOBAL_BALANCE_DIAGNOSTIC','ENV Interface liquide/gaz x14af — diagnostic diagnostic x14af uniquement; OFF production booléen entier 0/1 0 Cumule les résultantes x14ad/x14v et Q6 nécessaires pour fermer le bilan global de quantité de mouvement. 11 doubles/88 octets; requiert x14ad et x14z=0. Le diagnostic a établi ΔP_tot=J_Q6(applied)-J_thermo(x14ad) au roundoff.');
INSERT INTO "search_fts_content" VALUES(1102,'symbol:env:MPCD_X14V_DEVICE_APPLIED_Q6_RESULTANT_CLOSURE','SYMBOL','MPCD_X14V_DEVICE_APPLIED_Q6_RESULTANT_CLOSURE MPCD_X14V_DEVICE_APPLIED_Q6_RESULTANT_CLOSURE','ENV Interface liquide/gaz x14ai-fix1 — fermeture conservative candidat production x14ai-fix1 pour composante liquide fermée/isolée; OFF par défaut booléen entier 0/1 0 Utilise comme cible de résultante x14ad l’impulsion Q6 réellement appliquée par B1 après correction périodique: ΣmΔv_RT0 - M_active C_periodic. Requiert x14ad local-face + x10o/CIC et x14z=0. +16 octets persistants; aucun nouveau kernel/passe/CG/transfert D2H par pas. Ne pas utiliser sans qualification si le liquide touche une frontière Q6 externe.');
INSERT INTO "search_fts_content" VALUES(1103,'symbol:param:q6PressureOutletDeflationEnable','SYMBOL','q6PressureOutletDeflationEnable pressureOutletDeflationEnable q6PressureOutletDeflationEnable','PARAM Q6-G-F — pressure outlet conditioning ajout 0414d; actif par défaut booléen true Active/désactive uniquement la déflation exacte x8s des modes lents des pressure outlets compatibles, sans changer x8r/x8t. Switch d’ablation runtime; géométrie partielle non séparable désactive automatiquement la déflation spécialisée.');
INSERT INTO "search_fts_content" VALUES(1104,'symbol:env:Q6_PRESSURE_OUTLET_DEFLATION_ENABLE','SYMBOL','Q6_PRESSURE_OUTLET_DEFLATION_ENABLE Q6_PRESSURE_OUTLET_DEFLATION_ENABLE','ENV Runner 0414 / x8s ablation ajout 0414d booléen true Runner alias writing q6PressureOutletDeflationEnable. Qualification conditioning-only ablation.');
