INSERT INTO "symbols" VALUES('symbol:env:SPECIES_Q6_MODE','ENV','SPECIES_Q6_MODE','Alias runner / Q6 multi-espèces','ajout/normalisé 0493w4–0493w8','common|weighted|independent_masked','weighted dans le runner partagé historique; independent_masked par override/qualification','','Écrit speciesQ6Mode dans params.kv.','Utiliser independent_masked pour liquide incompressible/gaz compressible; weighted reste reproductible.','delta runners 0493w4–0493w8 / branche surf commit caa5b6b');
INSERT INTO "symbols" VALUES('symbol:env:SPECIES_Q6_SENSITIVITY','ENV','SPECIES_Q6_SENSITIVITY','Alias runner / Q6 multi-espèces','ajout/normalisé 0493w4–0493w8','double dans [0,1]','1.0 dans le runner injection','','Écrit speciesQ6Sensitivity.','Pertinent pour weighted, sans effet sur independent_masked.','delta runners 0493w4–0493w8 / branche surf commit caa5b6b');
