INSERT INTO "symbols" VALUES('symbol:env:INJECT_TO_BACKGROUND_MASS_RATIO','ENV','INJECT_TO_BACKGROUND_MASS_RATIO','Alias runner / injection multi-espèces','ajout/normalisé 0493w4–0493w8','double >0','100 liquid->gas; 0.01 gas->liquid; 10 sinon','','Fixe le rapport de masses particulaires injectée/fond et les masses cellulaires de référence dérivées.','Ne pas confondre avec la fraction volumique; le masque Q6 utilise mass/referenceCellMass.','delta runners 0493w4–0493w8 / branche surf commit caa5b6b');
