INSERT INTO "symbols" VALUES('symbol:env:EVAPORATION_TARGET_TYPE','ENV','EVAPORATION_TARGET_TYPE','Alias runner — interface cinétique / évaporation','runner alias courant; production x12 = -1','entier','-1 (runners x12 et SimulationParams)','','Surcharge phaseInterfaceEvaporationTargetType.','Avec r=1 dans la chaîne x12 actuelle, aucun passage d''évaporation n''est utilisé. Si >=0 avec r>0, le type doit être enregistré, non projeté et distinct de A.','cycle_0493x9_surface_tension + 0493x10q_surface_free + 0493x11c_validation_20260822 + snap_260826_code_audit_20260826');
INSERT INTO "symbols" VALUES('symbol:env:GAMMA','ENV','GAMMA','Validateurs CUDA resampling — population','lecture C++ directe dans validateurs shadow; également variable shell courante des runners','entier >0','20','','Occupation moyenne gamma utilisée par les exécutables de validation CUDA resampling shadow.','La lecture getenv directe identifiée dans le C++ est limitée aux exécutables de validation CUDA resampling shadow. Le même nom est aussi utilisé comme variable shell par de nombreux runners qui l''écrivent ensuite dans les paramètres; ne pas le confondre avec un getenv du binaire de production.','snap_260826_code_audit_20260826');
