INSERT INTO "symbols" VALUES('symbol:env:GRID_CASES','ENV','GRID_CASES','Validateurs CUDA resampling — entrée de test','présent code; ajouté consolidation 0493w8','liste/chaîne de cas','défini par le validateur','','Sélectionne les cas de grille exécutés par plusieurs binaires de validation du resampling CUDA.','Variable de validateur, pas une option du solveur de production et ne se place pas dans params.kv.','delta getenv exhaustif / branche surf commit caa5b6b');
INSERT INTO "symbols" VALUES('symbol:env:KINETIC_REFLECTION_FRACTION','ENV','KINETIC_REFLECTION_FRACTION','Alias runner — interface cinétique / évaporation','runner alias courant; production x12 = 1.0','double [0,1]','1.0 dans runners x12 de production; défaut SimulationParams=0.0','','Surcharge phaseInterfaceKineticReflectionFraction.','Avec r>0, la validation Params impose speciesQ6Mode=free_surface_masked, q6ForceProjectionMode=prestream_single_fused, B=vacuum et exactement une espèce A projetée. x10o n''est actif que pour r>=1; r<1 bascule sur le chemin cinétique historique.','cycle_0493x9_surface_tension + 0493x10q_surface_free + 0493x11c_validation_20260822 + snap_260826_code_audit_20260826');
